/* 平成25年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h25.committeeSessions.push(...[{"id":"h25-20130826-5","meetingId":"h25-cm08","date":"2013年8月26日","dateIso":"2013-08-26","committee":"総務委員会","time":"午後 １時００分～午後 ４時５４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件整理しています。","topics":[{"id":"topic-01","title":"平成２５年度都区財政調整交付金当初算定の結果","agenda":"平成２５年度都区財政調整交付金当初算定の結果","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"２１日ですかね、平成２０年度のときは、財政調整交付金が４１２億３,０００万円以上出ているという状況になっているんですよね。何十億ですかね、平成２０年度から比べて、そこら辺の説明をお願いしたいと思います。","respondent":"本城企画財政課長","answer":"先ほど国文学資料館関係と言いましたが、そういった特別なでっこみへっこみはありますが、基本的な大きな流れは今２３区の状況とほぼ同じです。調整３税というのが、大もとは調整３税のもとになる住民税法人分が減ったこと、それが一番大きな要因です。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"５５％ということが決まっているので、５５％に合わせて需要額の見積額が、そういうふうに当てはまるような形でやっていくということなんでしょうか。もともとの、積み上げ方式でいくと、そこら辺の基準財政需要額の変更の中身と考え方というのはどうなっているのか教えてほしい。","respondent":"本城企画財政課長","answer":"調整３税と言われる原資が住民税法人分を含めて、三つの税がありますので、それが減ったことが本当の要因です。あくまでもその元手となります調整３税、その根本のところは調整３税そのものが減っていると、このような形になっているものです。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ということは、基準財政需要額もそれに合わせて少なくしない限りは、そういうふうになっていかないわけじゃないですか。その減ってはいないという中で、財調を減らしていくというのは、どういう考え方でやっていくのか、そこら辺のところを教えていただきたい。","respondent":"桑村企画部長","answer":"平均的にやれるのはどこなんだろうということを検討してやっているものなので、財政需要額の中で考える、２３区の中で考えられることがあれば。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"調整３税の税収が減ったということに合わせて、２３区の中でいろいろ調整をして減らしてきたと、そういうことでしょうか。あれば、パーセンテージを変えてほしいという東京都への働きかけというのはないのかなというふうに思いますけど、その点はいかがか尋ねました。","respondent":"桑村企画部長","answer":"都区のあり方で検討しているわけですけれども、その中で一定の結論を出していこうかというのが今の考え方です。ただそれについて、現在特別区の中で、今回５,０００万円足りないからくださいというような議論はしないというのが都区のルールになっているです。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その主な要因というのはどんなものなのかというのがわかったら教えていただきたいのと、９５％と５％ということで特別交付金が災害などというふうなことで言われているんですが、どんな中身で算定をされて出てくるのかということもあわせて説明を求めました。","respondent":"本城企画財政課長","answer":"そのようなものを含めて、一般の財政需要では算定できないということで、災害を典型的なものとしてあります。全体的にはちょっと繰り返しになってしまいますが、災害関係のものを中心に環境対策関係等々、いろんな範囲のものがここに含まれているものです。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"７０億円ぐらい減った主な中身というのは、どういう中身かというのがわかったら教えていただきたいということでお聞きしましたのでお願いします。防災というふうなことで、例えばこんなところというのがあったら、その一例でも教えていただけたらと思います。","respondent":"本城企画財政課長","answer":"特別な１個の要因によってこれが減ってきたと、そういう形ではちょっとなかなか言いあらわしにくいものがあります。例えば直近で言いますと、そういった浸水対策と用地取得の関係で特別交付金算定したものを財源に充てたと、そういうような例がたくさんあります。","id":"exchange-006"}]},{"id":"topic-02","title":"大井競馬場で１１月８日に開催される品川区長賞レースの愛称","agenda":"大井競馬場で１１月８日に開催される品川区長賞レースの愛称","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"応募数は１９４件ということで、それなりの応募者がいたと思うんですが、何か特別ご意見とか何かはなかったですか。何かほかに、今回こういうこと、愛称、皆さんに公募することに対して何かご意見とかは特段なかったか尋ねました。","respondent":"工藤総務課長","answer":"１９４件の中では、あと英語名、外国名等さまざまな応募があったです。そういったお話もございましたけれど、全体的な名前でいいだろうということで、最終的にはこちらのほうでおさまったです。","id":"exchange-007"}]},{"id":"topic-03","title":"品川区工事成績評定実施要綱の改定","agenda":"品川区工事成績評定実施要綱の改定","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"ちょっと内容なんですが、これはあくまで公共工事、ここに書いてあります品質確保の促進に関する法律を前提として、その区で発注した施設、工事に関して業者がどのくらいきちんとやったか、見ばえももちろんですけど、品質的にも優れているということを評価するということか尋ねました。","respondent":"平澤経理課長","answer":"委員ご指摘のとおりでございまして、品川区の公共工事、区が発注した工事につきまして、３００万円以上のものにつきまして、区の所管課ならびに検査員がその点数をつけるです。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"余りにも短期間の中で評価するというのはいいんでしょうかということと、１０年間、やはり保証するんだよというものがあります。品質的にどうだったというのをこの時点で評価するというのは非常に早計な気がするんですが、その辺について、ちょっとご見解を説明を求めました。","respondent":"平澤経理課長","answer":"できばえ以外の部分でも工事につきましては、その工事が円滑に行われている、こういった点の評価もかなり重要な部分ということを認識しています。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"建物のふぐあいというのは建物自身が教えてくれると思うので、その辺については、また評価をする評定表みたいなものはきちんとあるわけですよね。誰が見てもわかるような、その辺についてちょっと説明を求めました。","respondent":"平澤経理課長","answer":"ちょっと繰り返しのご説明で大変恐縮ですが、そういったふぐあいが生じた場合には、当然ながら点数は見直すということになってあります。東京都と同じものを使ってございまして、東京都のホームページでも公表してございまして、どなたでも見られるような形になってあります。","id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"評価は区のほうできちんとやられると思うんですが、実際、建物というのは、それぞれ専門的な観点から見るということがすごく大事だと思うんですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"業者を評価するので、必ずそこら辺でいろいろなふぐあいが出てくると思うので、そこら辺のところをもう少し突っ込んで教えていただきたい。どうしてもそこを評価していくと、新しい業者を育成していくという観点、ここら辺の考え方をどう捉えていらっしゃるのか教えてほしい。","respondent":"平澤経理課長","answer":"今回も東京都の担当職員を呼びまして研修をやる予定です。そういったところからも、実績につきまして、全く外すということは総合評価の考え方からしても、ちょっとそれはできないです。","id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今３００件弱というお話を伺って、その体制が何名かであると。これは要望にしておきます。","respondent":"平澤経理課長","answer":"やはり信用がおける、公共工事を任せるわけですので、やはり一定の公共実績というのは必要な部分であるというふうに私は考えてあります。","id":"exchange-013"},{"speaker":"浅野委員","kind":"質問","question":"今回の実施要綱の改定ですけれども、評定内容の件で５項目あるわけですけど、合計で１００点満点ですが、総合評価の中では、２０点中だったと思うんですけど、基本的な考え方で大体２０点ぐらいとっている中で、どのぐらいの点数の割合になっているのかなというのをまず説明を求めました。","respondent":"平澤経理課長","answer":"これまで品川区で昭和５５年からずっと行ってまいりました工事の成績評定につきまして、評価方法は変わっておりません。ならびに技術者の実績、こういったところを点数化して、総合評価をやらせていただいているところです。","id":"exchange-014"},{"speaker":"浅野委員","kind":"質問・要望","question":"今後の話になるんでしょうかね、そこら辺の今後の利用方法というんでしょうか、教えてほしいと求めました。","respondent":"平澤経理課長","answer":"極端な例ではありますが、一定の点、６０点未満なんですけれども、これにつきましては参加できないことになってあります。それをどういうふうに品川区の中で取り込んでいくかというのは、これからの課題というふうに認識しています。","id":"exchange-015"},{"speaker":"浅野委員","kind":"質問・要望","question":"どうするかということもあるかと思いますが、考えていっていただければなと、このように要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"いながわ委員","kind":"意見","question":"うちは６０点以上じゃないかと、どういうのを想定されているのか、説明を求めました。","respondent":"平澤経理課長","answer":"※に書いてあるところですが、工事主管課長に対し評定内容について説明を求めることができる。こういう結果なんですよということをきちんと工事主管課のほうで説明すると、こういったところからも苦情処理というふうには至らない。","id":"exchange-017"},{"speaker":"いながわ委員","kind":"質問","question":"５点あればホームページに載っかるんだみたいな思いの中で、向こうも理詰めで来たときに、ここの委員会で覆ることというのは実際にあるんですか。当然のことながら行政の仕事ですから、民間においてもやるべきことはやっぱり匠ですから、その辺について。","respondent":"平澤経理課長","answer":"工事の主管課長が入って、こういう形で評定をつけたという説明をする。１００点満点の工事というよりは、苦情処理につきましても、仕組みとして必要なものだというふうに理解しています。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/904361?Template=document&Id=1958#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":25081,"voices":61}},{"id":"h25-20130827-14","meetingId":"h25-cm08","date":"2013年8月27日","dateIso":"2013-08-27","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ４時０２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査、「契約のあり方に関すること」","agenda":"特定事件調査、「契約のあり方に関すること」","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"評定者が現行４名で、この４名の役割と申しましょうか、どういう立場の方が評定に当たられているのかというのが１つ。工事主管課長に対し評定内容についての説明を求めることができるというのは、これは苦情申出とは別に、その２つをご説明ください。","respondent":"平澤経理課長","answer":"工事実施に当たりまして、そういった配慮、こういったところも評価項目の１つとなっています。ご説明の中身につきまして、これは説明してくださいということをお話しいただければ、すぐに電話等で対応できると思いますが。","id":"exchange-001"},{"speaker":"渡部委員","kind":"意見","question":"評定者の件について、わかりました。２つ目の問い合わせるということは、また次のステップとして苦情申出があるというような考え方で、それは間違いないわけですねとの意見を述べました。","respondent":"平澤経理課長","answer":"こちらの後ろの、主な改定内容の表にお示ししましたとおり、説明につきましては工事主管課です。この部分についての苦情だということです。","id":"exchange-002"},{"speaker":"渡部委員","kind":"質問・要望","question":"品川区に対して、考えられる項目等をピックアップしていただいて、多岐にわたって１回考えていただきたい。ワーク・ライフ・バランス等ありますので、そのようなことを私らとしてはお願いしたいのですが、その件についてはいかがか尋ねました。","respondent":"平澤経理課長","answer":"ですので、例示から大きく外れる、大きく逸脱するようなものはなかなか難しいのかなと考えています。この辺が課題と考えているところです。","id":"exchange-003"},{"speaker":"渡部委員","kind":"質問・要望","question":"この１８点よりも上がっていってしまうことが考えられると思うのですけれども、この１８点、２０点に縛られることなく考えてほしいと求めました。それは要望として終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"質問","question":"１工事で１者しか出ないのでしょうから、それによって、総合評価に持っていく時期というのがものすごく変わってくると思うのです。大体、区として、区内の事業者に対して、どのくらいの期間で評定をしていくというふうに見込んでいるのか尋ねました。","respondent":"平澤経理課長","answer":"これからの検討項目ではあるのですが、３年間で最終的な、一番直近の工事の評価点で評価するという要綱のつくりになってあります。当面はそれを準用してと考えてはいるところですが、今後の検討によってこれは変わってくる。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問","question":"何社もありますよね。直近には評価に入ってこないところも出てきてしまうのではないかという心配もあったので、その辺は大丈夫だということでよろしいか尋ねました。","respondent":"平澤経理課長","answer":"委員ご指摘のとおり、契約の大原則は門戸を大きく広げるです。今度、私どもの内部の規定で門戸を狭めてしまうのは言語道断のことですが、そういうことはないようにできるところからやっていくという考えです。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問","question":"３枚目の最低制限価格制度の運用状況について、この表を見せていただいて、落札者がほとんど９０何％という１００％に近い数字が出てきています。何社かが応札しているわけでしょうから、これ以外の会社は契約予定金額をオーバーしていたととれてしまうのですが、そういう感覚でいいのか尋ねました。","respondent":"平澤経理課長","answer":"制限付き一般競争入札の場合、品川区では予定価格を公表しています。ですので、予定価格オーバーというのはなかったわけでございまして、辞退というのは何社かございました。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問","question":"この数字を見ていると本当に厳しいのではないかなという気がしたので、同じことになってしまうけど、予定価格を算出することに対しての考え方をもう一度説明を求めました。","respondent":"平澤経理課長","answer":"予定価格の算出の仕方です。そういったところの影響がかなり大きかったのではないかと私は思っております。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問・要望","question":"詳しくわからないので教えていただきたいところがあって、これは４者が、工事が終わった後に現場に行かれるということですか。それとも、工事に、現場に定期的に行かれて、内容を見られるということなのか尋ねました。","respondent":"平澤経理課長","answer":"工事ができ上がってからでないとできませんので、そういった意味でもって、こういう書き方をさせていただいてあります。積み重ねて評価していって最終的に、最後のできばえのところは、この１４日以内ということで、評価するです。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"確認","question":"昨年は２８０件、経理課所属の検査員の方が３名、これは非常に大変な作業になってくると思います。１００点満点で細かく採点をされるということで、そこのところ確認の意味で、それを確認させてください。","respondent":"平澤経理課長","answer":"この評定項目につきましては、業者には東京都と同じですとご説明をさせていただいた上で、東京都のホームページをご覧になっていただきます。そういった意味も含めまして、これまで同様、きちんとした評価をするということを肝に銘じているところです。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"提案","question":"この４つ、２３区のほかの区ではこれを採用していないところもあって、高度技術提案型という３種類のものを使い分けをする。これに限らず、そういった規模に応じての発注体制を検討されるのかどうか、そこら辺のお考えについて伺いたいと思いますとの意見を述べました。","respondent":"平澤経理課長","answer":"今回ご提案申し上げているのは、通常、区が管理する工事につきまして、いち早く総合評価特別簡易型を実施する。そういう段取りといいますか、案件ごとにどうやっていくかということを、今後も考えていかなければいけないと思っているところです。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問","question":"その中でお伺いをしたかったのが、例えばマンションの１室、そこら辺の選別が必要になってくるのではないか。そういったことについても細かく決めていかれるのかどうか、そこのところを伺いたいと思います。","respondent":"平澤経理課長","answer":"これは事実です。品川区に最も適した評価方法をどうやっていくのかというのを、これからきちんと決めていかなければいけないと思っているところです。","id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問","question":"防災協定を結んでいるだけではなくて、しっかり訓練に参加しているかどうか、そういう細かいところでも点数を見ていくことも必要だと思います。こういったものに対する苦情とか、これについて、何か品川区としての考えはあるのか尋ねました。","respondent":"平澤経理課長","answer":"品川区におきましては、現在、工事成績評定につきまして、実施要綱を改定して新しい取り組みの緒についたところです。こういったところも運用の中身を見た上で、それが必要なのかどうかもあわせて、今後の１つの検討課題だと考えているところです。","id":"exchange-013"},{"speaker":"あくつ委員","kind":"質問・要望","question":"前回もお伺いしたのですけれども、価格点と技術点ということで、価格点のところの最低制限価格の適用がない、今回に関しては考えてはいない。もう少し詳しく教えてほしいと求めました。","respondent":"平澤経理課長","answer":"そういったことが可能であれば、そういったことも視野に入れてやっていくというのも、これからの検討課題だと考えています。考え方として、話が別になりますので、それはこれからの検討課題。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問","question":"労務単価を国のほうでは全国的な平均を１５％上げて、東京都では１８％上げたということに対して、各発注者の対応状況を調査する。先ほど９９％という状況の中で、ダンピング防止であるとか、しっかりと総合評価方式に取り入れるという区の決意を最後にお伺いしたいと思います。","respondent":"平澤経理課長","answer":"それとは別に、今回、総合評価を実施していくというところでは、やはり国の言うとおり、品質と価格の両方にすぐれた発注をする。今年の第１回定例会でもご答弁申し上げたとおり、総合評価方式について拡充の方向で検討する、そういったこともあわせて行っているです。","id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"評定内容が１から５まであって合計１００点満点で評定されるのですが、現場を見て、正確な評定には結びつかないのではないかと思うんです。現実的に、工期が１０カ月なり１年の工事について、何回くらい現場に訪れて、チェックするのか尋ねました。","respondent":"平澤経理課長","answer":"それをやっていくことが、よりよい工事、できばえにつながっていくです。区の職員が目指さなければならない最も大事な、基本的な部分ですので、それに向けた手続はきちんとやっていくです。","id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"私は、そして１つ１つの企業の技術力を高めるという点でも大いに大事なことだと思うし、そういう点で危惧するので伺ったわけですけれども。品川区がそういう角度で、公共工事に対する基本的なコンセプトというのですか、その辺のことを改めて伺っておきたいと考えています。","respondent":"平澤経理課長","answer":"公の契約ですので、こちらは門戸を大きく開いていく、これが大前提です。そういった総合的なものを全て取り入れて、法を遵守して取り組んでいくのが、私たち経理課の職務だと考えています。","id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"非常に申しわけない質問をしてしまったなと思いながら聞いたのですけれども、私が一番伺いたかったのは品川区、同時に資本主義経済の状況ですから。そういうところをどうやって公共事業が、そのあたりの考え方について伺いたいと思っているのですが、いかがか尋ねました。","respondent":"平澤経理課長","answer":"そういった法令遵守並びに国の考えているダンピング防止に向けた取り組みというのも、いろいろなところで、いろいろな場面でやっているです。金額を上げたことも、品川区として直ちに対応させていただいて、契約変更をやっているというところも１つだと考えているところです。","id":"exchange-018"},{"speaker":"南委員","kind":"質問","question":"いろいろお話を伺っていると、４次下請けの方々に、一部絵に描いた餅で終わってしまう部分もあるのではないかという危惧も持つわけです。私は問題意識として持っているので、そのあたりのことをしっかりと意識として伺っていきたいと思って、質問しているのです。","respondent":"中山総務部長","answer":"こういうものもあわせてやっていくというのが基本的なスタンスの中で、さまざまな方法をとっているです。広い意味での品質確保と、きちんとした工事が施工される環境の確保ですので、ご理解いただければと思います。","id":"exchange-019"},{"speaker":"南委員","kind":"意見","question":"したがって、その１つのツールとして公契約条例があると思っているので、そういう角度で物事を見ていただく姿勢が大事なのではないかと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"あべ委員","kind":"確認","question":"繰り返しの確認になりますけれども、評定内容については、今回はいじらないという理解でよろしいでしょうか。どう聞けばいいのかしら、あるいは大体何％くらいが８５点以上の成績を得ているのかといった、何か８５点のイメージを教えてほしいと求めました。","respondent":"平澤経理課長","answer":"２つ目、８５点ですが、成績につきましては、大体なのですけれども、七十四、五点が平均です。８５点というと、年間に一件あるどうかという、非常に優秀な工事を考えています。","id":"exchange-021"},{"speaker":"あべ委員","kind":"質問・要望","question":"その点何か、ここまでは品質にかかわるところでいくのだというようなものはあるのでしょうか。このままでいくと、だんだん工事の質の部分が、評価対象として少しずつ小さく削られていくような気がするのですけれども、いかがか尋ねました。","respondent":"平澤経理課長","answer":"学識経験者はどのような方かというと、この前ご説明申し上げましたとおり、例えば東京都の建設事務所長、そういう人が入ってあります。そういったところのご意見をお伺いしながら、評価の際、いろいろなものを、品川区として最適なものを目指していきたいと考えています。","id":"exchange-022"},{"speaker":"あべ委員","kind":"質問・要望","question":"どういう制度によるかは別として、一定以下のところは排除なり、評価をしないような形で選定していただきたいと。この視点については、どのように。","respondent":"平澤経理課長","answer":"その入札の参加資格というところだけで見れば、委員のご指摘になっているような部分というのは、なかなか取り入れが難しいと思います。そういった中で、どう入れていくのかというのは、今の段階ではなかなか難しいとしか申し上げられないです。","id":"exchange-023"},{"speaker":"あべ委員","kind":"質問・要望","question":"今日、私資料を持ってきたので、いい加減な数字を言ってはいけないのですけれども、労務管理、２３区の中でも総合評価ではなくて、入札の前の段階。今のご答弁の中でも、観点自体の価値は一定受けとめていただいていると考えていますので、さらに研究をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"原委員","kind":"質問","question":"その次でお伺いしますけれども、経理部門だけで全部の答えが出てこないでしょうから、わかりやすいのは建築士が何人いるかとか。意外といろいろなところで聞くものですから、現場代理人とかの人数の把握までは要りませんけれども、ざっくり処遇が間に合っているのかどうなのか。","respondent":"平澤経理課長","answer":"契約を担当する者では、なかなかお答えしづらい部分でございまして、ただ、区として責任を持って発注しているという事実。この事実１つをとってみても、現在の人員でやっている、足りているです。","id":"exchange-025"},{"speaker":"原委員","kind":"質問","question":"ですから現場に足を運んでいただくのだと思うのですけれども、要は、品川区は非常によくやっていらっしゃると私は把握しております。今日の部分においては、お金の部分も含めてなのですけれども、その２点をお答えいただけますか尋ねました。","respondent":"平澤経理課長","answer":"予定価格の事前公表ということで、これを対応しています。こういったところでもって、現場に密着な対応をとっているというのは見受けられます。","id":"exchange-026"},{"speaker":"原委員","kind":"質問","question":"３人、４人のほうがいいというのは当たり前の話なのですけれども、そうすると今度は全体的なコスト高になってくる。ですから、事案ごとなのか、その辺のところは常時どんな形でやっているのかをお聞かせほしいと求めました。","respondent":"平澤経理課長","answer":"そういった体制は整ってございまして、そういった場合には、一定のバランスというか予算の範囲の中で、契約を変更する場合もあります。そういったところで担保しています。","id":"exchange-027"},{"speaker":"原委員","kind":"質問・要望","question":"要望になりますけれども、品川区の職員のチームワークですから、業者関係を当たっていただきたい。これはお願いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"井上副委員長","kind":"質問","question":"先に成績評定の実施要綱の改定についてというところでお伺いしたいのですけれども、条件づけみたいなことがされていたのかということ。２,５００万円以上の工事ということだったので、先ほど言われた２８０件の中で、大きな工事のものはここに含まれているのか尋ねました。","respondent":"平澤経理課長","answer":"これは工事請負事業者指名停止基準というのがございまして、６０点より下、５９点までのものにつきましては指名停止になります。ただ、私の記憶する範囲ではないと思いますけれども、こういう使い方をする。","id":"exchange-029"},{"speaker":"井上副委員長","kind":"質問","question":"公表しないまでも何かあるのか、それともこういうところを線引きしていますというのは、品川区は持っているのか尋ねました。","respondent":"平澤経理課長","answer":"事業者に公表することによって、これから品川区の発注する工事について使えますというのが大きなところです。今後、もう一度検討しなければならないところだと思いますが、今のところはまだそこまではいっていません。","id":"exchange-030"},{"speaker":"井上副委員長","kind":"質問","question":"第三者委員会として別に設置するのではなくて、そういう方が１人でも入っていくという仕組みのほうがいいのではないかと思うのですが、それをされなかったのは何かあるのか尋ねました。","respondent":"平澤経理課長","answer":"先ほどご説明申し上げました減点する場合には、口頭による指導、指示書、改善指示書、それから改善命令書という４つの段階を踏むような形になります。","id":"exchange-031"},{"speaker":"井上副委員長","kind":"質問","question":"１つ、総合評価の問題点ということで指摘されている項目で２つあると思うのですけれども、相当しっかりとした説明責任が問われてくると思うのです。その部分をどう説明していくのかということと、公金を使っての事業ですから、品川区はどういうふうに考えているのか尋ねました。","respondent":"平澤経理課長","answer":"先ほどご説明いたしましたが、例えば簡易型につきましては、提案書が必要だということが具体的に定められてあります。そういったところを肝に銘じながら、判断項目をつくっていきたいと考えているところです。","id":"exchange-032"},{"speaker":"井上副委員長","kind":"質問","question":"どういうふうに入れるかという問題が１つと、計画作業に取り組んでいくというようなことがあったのですけれども、そこら辺は先があるのか尋ねました。","respondent":"平澤経理課長","answer":"スケジュールというお尋ねでよろしいでしょうか。","id":"exchange-033"}]},{"id":"topic-02","title":"」を聴取いたします。 「未利用国有地にかかる取得等の要望","agenda":"」を聴取いたします。 「未利用国有地にかかる取得等の要望","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"年度が切りかわって、例えば新年度からやっていくといったときに、委員会のまとめが新年度に入ってからでは、何の要望も……。委員会としての実績、我々の検討した結果が出てくるのではないかということで、正式にまとめて出したほうがいいのではないかと私は思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"あべ委員","kind":"質問","question":"その内容について、今ここで示されている意見、これがベースになるということでしょうか。そこら辺がよくわからなかったものですから、それから２回の議論という中で、今後のスケジュール的なものをどのようにお考えなのか尋ねました。","respondent":"山元委員長","answer":"その間、９月の間に、また違う意見等がありましたら、後で言わせていただこうと思っているのですが、意見があれば、またそこに加えながら。それをまとめて、次回の行革委員会でこのようにまとめていきたいという形でお示しをしようと思っています。","id":"exchange-035"},{"speaker":"あべ委員","kind":"質問","question":"それは、こういう意見がありましたという感じでの中間まとめということになるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"あべ委員","kind":"意見","question":"どういう中身にするかというのは、次にお示ししていただいた中でまた議論をしていくというとの意見を述べました。","respondent":"山元委員長","answer":"次回には、もうある程度形をつくって、皆さんにこういう形にして提出というか、行革として、このようにまとめましたという形でお見せをする予定ではいるのですけれども。","id":"exchange-037"},{"speaker":"あべ委員","kind":"意見","question":"出すこと自体は、こういうタイミングですので悪くはないと思います。内容次第ということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"南委員","kind":"提案","question":"改めて確認しておきたいと思っているので、正副で今の時期に出していきたいというふうに考えて提案された、そのあたりの思いと背景を改めて確認したいと思うのですけれどもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"南委員","kind":"確認","question":"大体、特別委員会のまとめというのは、１年間の締めくくりの時期にやってきていたではないですか。そのあたりのことをもう１回、ちょっと確認をしておきたいと思って言ったのですけれども、もう１回伺いたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"震災対策特別委員会を考えても、まとまる前に委員会の要望として出された。それと同じ発想です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"南委員","kind":"確認","question":"そこを改めて確認したのですけれども、今この時期にというところを確認させていただいたのですが、あっていいと思います。先ほどあべ委員から確認をされたことは、ここの文章はこう直したほうがいいとか、こういうことも入れてということは十分可能なのですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"あべ委員","kind":"確認","question":"１つお聞きしたいのですが、行政側のスケジュールとして、いつまでに提言を受けとっていないと検討に間に合わないというのはあるのですか。今走っているから、こういうスケジュールになるのだと思うのですけれども、行政側のスケジュールを確認させてほしいと求めました。","respondent":"平澤経理課長","answer":"私どもは、まさに工事の成績評定は、１０月１日から開始するところです。例えば、平成２６年度当初を目指して、ぜひとも新しい方式を考えていきたいと考えているところです。","id":"exchange-043"},{"speaker":"あべ委員","kind":"質問","question":"９月６日だと、本当にもうすぐではないですか。だから、どういう日程で動いていらっしゃるのかというのを伺ったので、平成２６年度当初を目指すというのは常識的にわかるので。","respondent":"平澤経理課長、中山総務部長","answer":"一般的にどうかということでまいりますと、こういった大きな変更をする場合には、事業者への説明は必須項目になります。そういたしますと、第１回定例会における総務委員会等でご報告するあたりが限界という形で… よりよい制度を検討しているという中ですので、あくまでも正式な方針決定がある中でのスケジュールというわけではございませんので、その辺を踏まえてのご検討をよろしくお願いしたいと思います。","id":"exchange-044"},{"speaker":"あべ委員","kind":"質問","question":"今の質問は、来年度に間に合わせたいから１０月までには私たちが出しておきたいのだという形で示して、〔「それで予定表をつくったんだ。こうしたいのだということを委員会の意思として言って、そのうちにこのスケジュールのことを言ってほしかったと私としては思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/631596?Template=document&Id=5952#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":39033,"voices":111}},{"id":"h25-20130828-17","meetingId":"h25-cm08","date":"2013年8月28日","dateIso":"2013-08-28","committee":"震災対策特別委員会","time":"午後 １時００分～午後 ３時０６分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件整理しています。","topics":[{"id":"topic-01","title":"の１「特定事件調査」","agenda":"の１「特定事件調査」","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"これはどういう数字の捉え方として見ているのか。先ほどあったような気もいたしますけれども、改めてワークショップ実績で減っていることに対してどう思っているかについてお聞きしたいと思います。","respondent":"鈴木防災課長","answer":"これにつきましては防災課としても対応が必要と考えておりまして、年々、近年では数が減っているというのが防災課の認識です。今後、各町会・自治会にもそのような働きかけをしまして、今後も力を入れて支援していきたいと考えております。","id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"地域別に出ていないですからわかりませんけれども、やはり平成１８年度から始めているということで、早いところは７年前に行っているわけですから。そういう実践例を見ながら、何回でもやっていくことが必要だと思いますので、その辺の取り組みについても一言お伺いしたいと思います。","respondent":"鈴木防災課長","answer":"委員ご指摘のように、一度訓練をすればよいというものではございませんので、過去にやった町会も今後も継続してやっていただけるように働きかけをするとともに、区としてもしっかりと支援をしていきたいと考えております。","id":"exchange-002"},{"speaker":"本多委員","kind":"質問・要望","question":"６ページの（２）福祉避難所の2)で、それと「６.今後の取り組み」で一番最後の２行目ですけれども、その辺をもう少し詳しく教えていただきたいです。","respondent":"鈴木防災課長","answer":"１点目の電源喪失により生命に危険が及ぶような方についての対応ですが、医療機関等での対応が必要かと考えております。その場合には二次避難所や福祉避難所は対応が困難ですので、それから専門機関との連携により対応をするという、対応を分けて考えているものです。","id":"exchange-003"},{"speaker":"つる委員","kind":"質問・要望","question":"本日配られた中の災害時要援護者の定義のところと、それから５ページの1)名簿登録対象者、これは対象者の定義の違いというか、幅があると思いますけれども、その辺の考え方を教えていただきたいと思うのですけれども。","respondent":"鈴木防災課長","answer":"１番の定義につきましては、これは東京都の災害時要援護者に関するマニュアルであるとか指針についても似たような表現がされているものです。医療的な対応だったり、専門知識による対応が必要な方は、地域では対応が困難ということで入れていないところで違いが出ているものです。","id":"exchange-004"},{"speaker":"つる委員","kind":"確認","question":"何か別の機会にも似たようなことを確認させていただいて、その辺の整合性というのですか、その辺もあわせて教えてください。続けて５ページの登録者の内訳の中に希望者が３２１名おりますが、その辺の内訳ですね、この辺をざっくりと説明を求めました。","respondent":"鈴木防災課長","answer":"１点目、この災害時助け合いシステムで対応できない方の対応についての各課との連携ですが、基本的には先ほど２ページでご説明いたしましたように。","id":"exchange-005"},{"speaker":"つる委員","kind":"質問","question":"すいません、あと１つ、ごめんなさい、聞き漏れてしまったのが、内訳とかはわかりました。これは防災課ではないかもしれませんけれども、保健センターで把握をして連携をとるという形でよろしいか尋ねました。","respondent":"鈴木防災課長、大石荏原保健センター所長","answer":"今、委員からのご質問にありましたように、防災課だけでは把握や対応をし切れませんので、保健センター、それから健康課を含めた医療部門と連携をして、状況把握や対策についての協議を進めているというのが現在の状況です。優先順位をつけながら、ご家族の方ともに対応していただかなければいけないところがありますので、どういった形の対応をとっていったらいいのか。","id":"exchange-006"},{"speaker":"つる委員","kind":"確認","question":"別のときにもいろいろ確認させていただきましたけれども、いわゆる文京区で今やっている妊産婦乳児避難所のような機能ですね。品川区としてはそういう分娩セットが今現在備蓄されているのか、それとも考え方としてあるのかどうか、この辺を説明を求めました。","respondent":"鈴木防災課長","answer":"ご質問いただきました妊産婦への対応ですが、現在、分娩のための器具等のセットについては区では特に準備、備蓄はしていない状態です。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問","question":"２点お伺いしますけれども、最後の６ページですけれども、二次避難所と福祉避難所の大体の受入人数です。増やしていきたいということは、その辺はどのくらい受け入れられて、あとどのくらい増やさなければいけないのかということをお伺いしたいと思います。","respondent":"鈴木防災課長","answer":"それぞれの方によっていろいろな対応状況が違ってまいりますので、そこで対応し切れない方は二次避難所に、さらに福祉避難所にというような。そういう意味では、具体的な割り振りであったり移動についての支援というようなところを考えるのが現実的な対応になると考えております。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問","question":"小さいころからそういうものもやって、若者の取り入れもこれから先、考えていかなければいけないということをどのようにお考えかと。もう１点のほうですけれども、人数が多い場合はどうしようとかということが、どういうところを見ているのかというところをお伺いします。","respondent":"鈴木防災課長","answer":"全６回の講座を、防災区民組織を通した働きかけではなくて、一般公募の集まる方への取り組みということで実施したところですので。各施設と協議しながらできるだけ広げていく取り組みを今後も継続したいと考えているところです。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"避難所はできましたけれども助けてくれる人がいないというのがあるので、その辺は両方について考えてほしいと求めました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"沢田委員","kind":"質問","question":"そのうちの４,０００名という、上の２つの条件の対象者はどれぐらいいて、そのうちの４,０００名が登録されたのか尋ねました。","respondent":"鈴木防災課長","answer":"要介護１から５の認定を受けた高齢者の方、それから身体障害者手帳所持者の方、それぞれ対象者は各課で把握をしているところに含まれているものです。","id":"exchange-011"},{"speaker":"沢田委員","kind":"意見","question":"その１万件の方が対象でということで、区としてはやはりこの対象の方全員に名簿登録をしていただけることを望んで、こういった名簿を作成しているのかと思いますけれども、そういうことであって、そのうちの現在の数の登録者ということをどのように考えられていますかとの意見を述べました。","respondent":"鈴木防災課長","answer":"地域の一般区民の方、対象の方、現時点でもかなり地域での対応力でいきますといっぱいいっぱいの方が登録されているというのが現状の認識になります。","id":"exchange-012"},{"speaker":"沢田委員","kind":"質問","question":"本人の了解を得るなどプライバシーの保護に配慮しながらということですけれども、やはり中には登録は別にしたくないという方もいらっしゃるのかと思いますけれども、そういった方に対しての対応はどういうふうにされているのか尋ねました。","respondent":"鈴木防災課長","answer":"登録時に申請いただくときに、実際に支援する団体組織に提供してもよろしいでしょうかという同意をあわせて出していただくようになっております。","id":"exchange-013"},{"speaker":"沢田委員","kind":"質問・要望","question":"プライバシー等ありますけれども、命にかかわるということで、ぜひとも登録してほしいと求めました。想定数は特にまだ、大体の数を、どれぐらい人数が増えていくということは把握されているということでよろしいのか尋ねました。","respondent":"鈴木防災課長、松代防災まちづくり事業部長","answer":"この方が全員二次避難所、少なくともやはり３分の１から半分近くは対応ができるようなところは必要かというのが現在喫緊の課題と考えております。現時点ではそこまで全て担保できるところまではまだ整備ができていないというのが現状で… それに対して品川区としてどう対応するのかです。そういう構築をしていく中で、それをしっかりとつくっていく、そういった形が今後の計画を実施していく中身だろうと思っているところです。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"そうすると、残りの３万人といいますか、２万６,０００人といいますか、その方にはなぜお知らせの用紙そのものが届かないのか、伺いたいと思います。は品川区はここに書かれた報告書の内容、方向性について、これを具体化していくという立場に立っているのかどうか、そこを伺いたいと思います。","respondent":"鈴木防災課長","answer":"ご質問の趣旨である、先ほど説明しましたように各主管課や関係施設・機関との連携の中で対応していくというふうに、対応の役割を分けているものです。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"私はお知らせはさまざまな方に応じてわかりやすさも含めてしっかりやるべきだと思いますけれども、その点も伺いたいと思います。高齢者自身がどう動くのか、今どういうことが進められているのか、ここを伺いたいと思います。","respondent":"鈴木防災課長","answer":"この考え方としては二次避難所に何人、要援護者の方の全体像の中でできる限り対応できるような形で進めるというのが今の進め方です。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"改めて伺いたいのですけれども、昨年２月２８日の震災対策特別委員会で、いわゆるガイドライン的なものを新たにつくったと。いざとなったときにそこに障害がある方、高齢者の当事者参加をぜひ位置づけてほしいと求めましたけれども、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"もしくは専門的な施設に入っての対応、資源では対応できませんので、福祉法人や医療機関との連携で対応することになります。ただし、それに対応しながら、いかに区の全体の要援護者への支援をあわせて実施していくかというところを今相談しておりますので。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"改めて伺いますけれども、目標を設定してこのマニュアル、プランをつくる考えがあるのかどうか伺いたいと思います。先ほど伺ったのでお答えがなかったのが、お年寄りの方々、この点についてもご説明ほしいと求めました。","respondent":"鈴木防災課長","answer":"目標を設定してマニュアルづくりという件についてのご質問ですが、委員がいう目標が何の目標を指すのか、ご質問に出ていなかったので。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"スケジュールを定めていくべきだと、そういう切迫感を持ってやってほしいと求めましたけれども、伺いたいと思います。どう生活していくかを決めるわけですから、ぜひ当事者参加をしっかり位置づけるべきだと思いますので、改めてこの点は伺いたいと思います。","respondent":"松代防災まちづくり事業部長、鈴木防災課長","answer":"しっかり取り組んでいく内容だと考えていますけれども、まず本日の時点ではこれまでいろいろと提言を受けて進めたものを報告していると。このように受けとめていただければと思います。自分の災害時の対応とあわせて地域への貢献がありますので、現時点で日程を設定するという考え方はないというのが今のお答えになります。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"精神障害がある方、自閉症もそうですけれども、こうした方々は二次避難所と福祉避難所のどっちになるのかを伺いたいと思います。要するにこういうところを拡大していくということであれば、早くしてほしいと求めましたけれども、ぜひそこは具体的に伺いたいと思います。","respondent":"鈴木防災課長","answer":"区での取り組みや考え方、議会に報告をしたのが平成２４年度末、つまり今年３月です。４月から年度が変わりまして、区として取り組みを始めておりまして、８月までの取り組みを本日まとめてご報告させていただいているものです。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"何が必要なのか、どうすれば生命・身体・財産を守ることができるのか、こういうふうに進めていただきたいことを要望いたします。最後、要望です。","respondent":"鈴木防災課長","answer":"まとまりましたら、区としてはこういうふうにしっかりと考えてこういう対応をします。もうすぐ９月１日の区の広報でも防災特集とかを出しますけれども、そういう必要ないろいろな機会を捉えて、現在の区の取り組みです。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"では、災害時要援護者マニュアルも当事者参加、公開のもとで進めたらどうですかと。先ほどから伺っているので、ぜひご答弁ほしいと求めました。","respondent":"鈴木防災課長","answer":"先ほどから区の業務マニュアルのお話をずっといただいていたので、そのつもりでお答えをしておりました。つまり要援護者の方ご本人の行動マニュアルにつきましては当然必要性は認識しておりますが、まずは区の対応と関係機関がどういう対応ができるか。","id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"一本化ではないのですかね、共通化というのですか、これをお伺いしたいと思います。","respondent":"鈴木防災課長","answer":"ダブっていてとか、そういうところの調整といいますか、確認をこれからしなければならないとは考えております。各課との連携の進め方ですが、対応についても考えている部分がありますので、防災課の役割になるかと考えております。","id":"exchange-023"},{"speaker":"塚本委員","kind":"質問","question":"名寄せということですかね、１人の個人名で皆様がこの人はどういう方かというのがわかるようになるという、その辺をもうちょっと具体的にお伺いしたいと思います。","respondent":"鈴木防災課長","answer":"要援護者の方の事情に応じたり、状況に応じたものを作成するということで、一元管理とは性質が異なるかというのが現段階で考えているところです。","id":"exchange-024"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、それを持っている所管がその個人プランを活用して、何か災害時に支援をしていくというイメージになるのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"発災の当初の段階と、数日たってからの段階とで対応が異なってくるかと思います。どういうサービスを受けているかとか、あと、通常のサービスに移行していく形になるかと考えています。","id":"exchange-025"},{"speaker":"塚本委員","kind":"意見","question":"そうすると、ごめんなさい、認識がちょっとずれているのかもしれないですけれども、個別支援プランは、防災課が発災直後に個々においてどういうふうに支援しましょうということのためにつくるものという認識で、まずは合っていますかとの意見を述べました。","respondent":"永尾高齢者福祉課長","answer":"防災課のほうでつくる災害時助け合いシステムの個別支援なので、その方の現状の状態を見ながらどうやって避難していくかという計画になると思います。","id":"exchange-026"},{"speaker":"塚本委員","kind":"質問","question":"今のご答弁を聞くと、やはり防災課で名簿と一緒に個別支援プランも一本化が望ましいのではないかと思いますけれども、その辺、どのようにお考えか尋ねました。","respondent":"鈴木防災課長","answer":"発災直後の、要は避難誘導に関する個別支援プランにつきましては、委員ご指摘のとおり、やはり防災課としてしっかりと全体像を把握して、一元管理しながら、各地域における対応をしていただける組織への情報提供をしっかりととれる体制を維持していきたいと考えております。","id":"exchange-027"},{"speaker":"塚本委員","kind":"質問・要望","question":"それは福祉避難所というものが、現実として受け入れるというのはどういうふうになる、現実としてはどういうふうになるのかイメージできない。それは課題ということでしようがないことなのか、具体的に何かこうやってうまく受け入れていくというところが少しあればお示しいただきたいのですが。","respondent":"鈴木防災課長","answer":"そういうところに着目をしまして、やはり対応をしていただくのがほかの区の一般的な施設で対応するよりはよりよい環境になるだろうという発想です。","id":"exchange-028"},{"speaker":"塚本委員","kind":"意見","question":"確かにこれは難しい。私でもすぐにこうしたらどうだろうと軽々にはいえない問題だと思いますけれども、経験のある皆様の、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"木村委員","kind":"質問","question":"災害時要援護者名簿の作成のことですけれども、これは１万人の方に通知をしていることをお聞きしました。これは年に一度なのか、それとも数回に分けてやっているのか、そのやり方を説明を求めました。","respondent":"鈴木防災課長","answer":"災害時助け合いシステムの名簿登録のお知らせですが、年度初めに、年に１回実施しているものです。５月に通知をしまして、６月、そのような年に一度の全体のお知らせと随時対応を組み合わせて対応しています。","id":"exchange-030"},{"speaker":"木村委員","kind":"質問","question":"これも一度そういうふうになれば、そこでその６,０００名の方々を見捨てるわけにはいきませんよね。プライバシーですからいろいろな情報、そういうものをつくっていくべきだと思うのですが、その点を説明を求めました。","respondent":"鈴木防災課長","answer":"先ほど申し上げましたように、それの了解をセットにした登録ですので、そこに希望されない方についても情報としては区として持ち合わせております。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"この方はどっちなのかと伺ったのですけれども、どうしてなのかということを伺いたいのと、それについて伺いたいのが１点。もっと大きくいうと、どう考えを整理されていらっしゃるのか、これについて考えを伺いたいと思います。","respondent":"中山障害者福祉課長、鈴木防災課長","answer":"ただ、あるいは大声を出したり、周りのことを気にするためにご家族の方がとても一次避難所にはいられないというようなケースもあろうかと思います。場合によってはそこの対応になろうかと思いますし… ですので、その対応を中心に考えているところです。それ以後、避難所、申しわけありませんが最寄りの避難生活が対応できる施設に移動していただくというのが現在の考え方になっているところです。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"発災時には第一義的には救援・救助、もっと言えば情報収集を含めて、そこが第一義的だと思うのです。品川区が被災地になったとき、それともそれぞれ職員の方々もどこにどう動くというのも決められているわけですから、もう１回ご説明いただけますか。","respondent":"鈴木防災課長","answer":"ただし、避難者について避難所のような施設として受け入れというところは想定しておりません。それは災害対策本部、つまり区全体の災害対応をするための部隊の拠点ですので。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/480548?Template=document&Id=6438#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":42156,"voices":84}},{"id":"h25-20130920-4","meetingId":"h25-c-settlement","date":"2013年9月20日","dateIso":"2013-09-20","committee":"決算特別委員会","time":"午後 ３時３５分～午後 ３時４１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/571589?Template=document&Id=1370#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":2010,"voices":16}},{"id":"h25-20130924-6","meetingId":"h25-cm09","date":"2013年9月24日","dateIso":"2013-09-24","committee":"区民委員会","time":"午前１０時００分～午後 ０時１４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を60件整理しています。","topics":[{"id":"topic-01","title":"第５９号議案 平成２５年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第５９号議案 平成２５年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"要するにこの交付金が平成２４年度終了予定だったものが、そこを伺いたいのと、その経過を伺いたいと思います。今年度で終わるというものなのか、来年度以降はどういう動きになっていくのか、そこを伺いたいと思います。","respondent":"米田商業・観光課長","answer":"まだその支援の取り組みが始まったばかりであって、また再度、平成２５年度も継続してというようなことでの予算がついたと聞いております。それから、来年度ですけれども、所管の官庁としては継続してまいりたいというようなことで考えていると内々に聞いてあります。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"特に都市部ではどういう課題があるのかご説明いただきたいのと、今回の事業内容とどうタイアップされているのか、そこを伺いたいと思います。どんな枚数なのか、それが今回の中身でどんなふうに変わるのか、中身についてもご説明いただけますか尋ねました。","respondent":"米田商業・観光課長","answer":"明日またご説明しますが、高齢者になりますと、高齢者の相談が非常に増加しているところもあります。現状、それに対応するプリンターがないものですから、それでロール紙とかでいわゆる掲示物をつくっていたというようなことがあります。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に一言。必要だと思いますので、いろいろ相談、事例や実態に見合った対策を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"石田（し）委員","kind":"質問","question":"改めてお聞きしたいのが、消費者センターと品川区行政の関係はどのような位置づけで運営がされているのか、その辺をまずお知らせください。お願いします。","respondent":"米田商業・観光課長","answer":"消費者センターは、区の内部機関の一つです。その上位に所管しているところが、現在は商業・観光課であるということで、地域振興事業部の中の組織の一つに位置づけられているものです。","id":"exchange-004"},{"speaker":"石田（し）委員","kind":"質問","question":"区で備品を利用する場合に、リースと購入という２つが基本的に大きな備品に関しての契約等があるのですが、基本的にはリースがメーンだと思うのです。削減できるということで購入されるのか、その点、購入に関しての考え方を説明を求めました。","respondent":"米田商業・観光課長","answer":"今年度の消費者行政活性化交付金では、１年間の範疇におさまるというようなことが想像されるところです。ある程度最初に買って、その用途の中で使っていくということもできるのではないか、このように考えてあります。","id":"exchange-005"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"今までも従来もやられているとは思うのですが、ぜひそういった視点もしっかりと入れながらやってほしいと求めました。本当に電車内での１５秒のＣＭが効果てき面なのか、２つを選択して、そこだけ説明を求めました。","respondent":"米田商業・観光課長","answer":"当然、ビジョンの会社は、消費生活展等で実際にそういうものを見たというようなことについてはアンケート等もとれるのではないかと考えています。そういうようなことも含めて、今年度、新たなトライアルということで確認してまいりたいと思います。","id":"exchange-006"},{"speaker":"山元委員","kind":"質問・要望","question":"事業予算の中で相談員の謝礼で五十数万円ということですが、これは先ほどおっしゃっていた週１回のベテランの方のためのものなのか、その目的を教えていただきたいのですけれども。","respondent":"米田商業・観光課長","answer":"今お話がありましたように、定数は、今、６人で動かしております。その新人の相談員の方の相談等に対する指導も含めプラスアルファということで、週４時間、月１６時間の従事をお願いしているものです。","id":"exchange-007"},{"speaker":"山元委員","kind":"質問","question":"先ほど週１６時間、細かくて申しわけありませんが、どのぐらいになる。要するに１時間単位というか、週１６時間でどのぐらいになるのか尋ねました。","respondent":"米田商業・観光課長","answer":"１回いらしていただいたことに対して、時給当たりで２,８００円ぐらいで、それが交通費込みでというようなことで計算しています。で、これまで相談業務に携わってくださっている方の相場等を勘案して、そちらの金額で設定させていただいてあります。","id":"exchange-008"},{"speaker":"山元委員","kind":"質問・要望","question":"時給２,８００円という、それが妥当かどうかはわからないのですけれども、ぜひその辺を活用してほしいと求めました。この６人の方は全員女性なのか、質問がずれてしまうかもしれないですが、相談員に対しての苦情は区に上がってきていることはありますか。","respondent":"米田商業・観光課長","answer":"いわゆる相談の対応の仕方であったりとか、「こういう対応についてのご指摘がありました」というようなことで全体で共有するようにはしています。","id":"exchange-009"},{"speaker":"山元委員","kind":"質問・要望","question":"どうしても自分もそうですが、感情的になって、いずれにしても感情的にならないような冷静な対応をしていただければいいかと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問・要望","question":"今のお話の続きなのですけれども、その２,８００円に交通費込みということですが、キャリアも含めて理解ができるようなご説明をいただきたいです。申しわけないです。","respondent":"米田商業・観光課長","answer":"別に時給というわけではないのですが、いわゆる相談員の世間的な相場から大きく外れているということではないと考えています。私どもはぜひともその方の引き続きのこれまでの経験の活用ということでは、こちら側からその金額で提示してお願いし、ご了解いただいたものです。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"要するにキャリアがあって幅広くいろいろな知識があるということを実際にお話を聞いたのですけれども、これから先、この方はどうなのでしょうか。こういう、先も続けていっていただけるのかということですが、その辺はどうなのでしょうか、お聞きしたいです。","respondent":"米田商業・観光課長","answer":"そういった意味では、もうその期間を過ぎてあります。で、あとは私ども、その方の可能な範囲での引き続きの従事ができるような形であれば、そちらのほうはお願いしていきたいと考えているものです。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"できればそういう方にこれからも続けていっていただいて、次のそういう方が出てきていただけるような最善の努力を続けてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問","question":"高齢者福祉課になるのか、そこら辺のところ、消費者センターは割合待っている立場ですよね。何ら関連性、今やっているのと今後の展開をもう一度教えてほしいと求めました。","respondent":"米田商業・観光課長","answer":"最近の悪質商法の手口等をご紹介することを、その会のご希望に応じて、おおむね１時間から２時間ぐらいの時間で出前講座を無料で行っております。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その辺、うまくお話を詰めていただいて、万が一、何しろ起きないような対応をこれからもぜひお力添えをほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"消費者センターの強化は、今、必要なことだと思いますので、賛成です。あわせて、今回、補正にはないけれども、ぜひ商店街とか、中小企業とか、こういう支援もしっかり考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-02","title":"「品川区地域安全のつどい」の開催","agenda":"「品川区地域安全のつどい」の開催","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"１点だけ確認したいのですが、ほとんどが常に地域安全の運動を積極的にしていただいている方たちが基本的にそこに来て、結局は身内ですね。積極的に地域の安全運動に寄与している方たちのためにこのつどいが行われるのか、その点を改めて、その目的も含めてお知らせほしいと求めました。","respondent":"上垣外生活安全担当課長","answer":"そのために、一時的にはこの招待する方にありますように、防犯協会関係者の方を中心にお呼びいたしまして周知活動を行います。もちろん、それに伴いまして、この方たちを通じて、区内に広く犯罪の発生状況、防犯のための手法などを広めていっていただくというのが目的です。","id":"exchange-017"},{"speaker":"石田（し）委員","kind":"質問","question":"そうすると、基本的には会員の方対象に、地域の安全運動はこうあるべきとか、こういうふうにやってもらいたいとかというようなことを会員の皆様に伝えるためのつどいという認識でよろしいのか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"はい、そのとおりです。基本的には防犯協会の関係者を中心として周知をするのが目的です。","id":"exchange-018"},{"speaker":"藤原委員","kind":"質問","question":"それで４の内容なのですけれども、この地域安全のつどいに、まずは何で対談・歌謡ショーをやるのでしょうか。そして、歌謡ショーのゲストの方に幾らぐらい予算をつけているのか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"第１点目の、歌謡ショーで大月みやこさんを招致する理由です。","id":"exchange-019"},{"speaker":"藤原委員","kind":"確認","question":"改めて確認ですけれども、基本的には歌謡ショーをやらなければ集客は厳しいという現実があるということも把握していかなければいけないのでしょうか。そこを確認させてください。","respondent":"上垣外生活安全担当課長","answer":"必ずしも歌謡ショーでなければ人を集めることができないということではないと思われますが、今までの経験則からして、やはりこういった方法をとるのが一番ベストであろうという考えのもとに開催させていただいているものです。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"まずは犯罪の発生状況はどういう特徴なのか、それと見合ってこのつどいの開催や中身がどう対応していくのか、そこを伺いたいと思います。","respondent":"上垣外生活安全担当課長","answer":"この振り込め詐欺が管内で増加傾向にあるというのが管内の特徴であります。例えば今回のプログラムの中で寸劇をする予定にしておりますけれども、この中では、こういった形で周知をしていただくこととしております。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういうものに対してなくしていこうという取り組みの中で、こういうアトラクション的なものが本当にそれにふさわしいのかという疑問を感じるのです。もちろん大勢集まっていただきたい、そういった議論はあるのか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"現段階では、こういった形での寸劇、実際の役者による受け答えを見て、実際の被害の状況を見ていただくのが一番効果的と考えています。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問・要望","question":"２０１２年でしたか、これはどういう講話をなさるのか疑問なのですけれども、質問させてほしいと求めました。","respondent":"上垣外生活安全担当課長","answer":"小宮先生からは、「身近な犯罪から身を守るための手法」ということで、先生の専門の分野であると思われますが、この話をしていただく予定としております。","id":"exchange-023"},{"speaker":"吉田委員","kind":"質問","question":"この人選に関しては、毎年、目的はわかるのですけれども、年々見てみるとすごく広範囲に考えられるのですけれども、人選に関してはどのようなお考えなのか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"人選といたしましては、決定的な要因はございませんので、この趣旨に沿った方を幹事署である警察署と私どもで相談して決めているものであります。","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問・要望","question":"今年でこの企画は１８回目ですか、目的に沿っていただきたいと思うのですが、その辺に関して確認させていただけますか。何回目かということと、それから目的に沿った人選をしていただきたいのですが、その辺の考え方をもう１回お願いします。","respondent":"上垣外生活安全担当課長","answer":"回数につきましては、今回が１８回目と認識しております。中身につきましては、もちろんこの目的に沿った内容としていくように常々考えております。","id":"exchange-025"},{"speaker":"山元委員","kind":"質問・要望","question":"教えていただきたいのですけれども、そんな話があって、その町会の方たちも「ああ……」という感じもありました。それとも、これからしようとしていらっしゃるのか、何かその辺の考えはどうなのか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"その場に実際に警察署の担当の者が参ってご説明したり、あるいは私も直接招かれていってお話する機会をいただいております。これからもこういった機会を設けていただいて、どんどんこういった手口、被害に遭わないような対策をお話させていただきたいと考えております。","id":"exchange-026"},{"speaker":"山元委員","kind":"質問","question":"お年寄りが集まっているところに行っているのか、大体どのぐらい行っていらっしゃるのですか。数がもしわかれば説明を求めました。","respondent":"上垣外生活安全担当課長","answer":"具体的な数は、申しわけございません、正確なものは把握しておりませんけれども、私がこれまでお話させていただいたのは１回あります。既に予定が入っているものもありますので、積極的に話をさせていただきたいと考えております。","id":"exchange-027"},{"speaker":"山元委員","kind":"質問・要望","question":"最後です。何か工夫をしてほしいと求めましたので、これも要望ですけれども、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-03","title":"(2)「大崎盛り場環境浄化キャンペーン」の開催","agenda":"(2)「大崎盛り場環境浄化キャンペーン」の開催","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"「大崎盛り場」とはどこだ。文章を読んでいると、「五反田有楽街」と出るのですけれども、「大崎」とは、大崎署が所管するからという意味で、まず、いいのか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"管轄警察署が大崎署ですので、このような表題としています。先ほど申し上げました東五反田一丁目地区が中心となりますけれども、この活動そのものは、大崎署管内全体で実施するものであります。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"「大崎盛り場環境浄化キャンペーン」は初めてだと思うのですけれども、このキャンペーンをしようとした背景について、まずお伺いします。","respondent":"上垣外生活安全担当課長","answer":"背景につきましては、まず１点が、今回、地域安全運動という形で、きれいなまちは犯罪を起こさせないということでするものと、かねてから大崎署でこういった行事をやりたいと考えていたのですけれども、今回、この機が熟したということで実施するものであります。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"いいですね、区民の気持ちも高まってすばらしいと思うのですけれども、目的の中で「違法風俗店の営業」とあるではないですか。「違法風俗店」とは具体的にどういうことなのか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"具体的には、今、検挙の対象となっているのが例えば違法な客引き等、こういったものが顕著な特徴となっております。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"質問の仕方が、「違法風俗店」は具体的にはどういうことですかと聞いて、客引きをしているところが違法風俗店と思っていいのですか。今の答弁だと、客引きがという、迷惑な客引き。","respondent":"上垣外生活安全担当課長","answer":"違法行為についてはいろいろ種類がありますので、例えば無届け、無許可、こういったものも違反の対象となっております。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"いかがですかということと、区民が約５００人参加しますよと言うのですけれども、これをやって何を区民に求めるのですか。だけれども、これと歌謡ショーはどういう関係になるのかもお伺いします。","respondent":"上垣外生活安全担当課長","answer":"この点につきましては、もちろん大崎署のみならず警視庁の本部においても取り締まり活動を実施しているところであります。ぜひともそういった形でご協力いただきたいという趣旨でキャンペーンを実施いたします。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問・要望","question":"ですけれども、これは名指ししてしまっているではないですか。その辺、そんな意味も含めて大成功に終わっていただきたいと思うのですけれども、そういう意味で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ですから、今回参加する人たちは、もともとその対象ではない人たちがほとんど来てくれるわけですよね。ですから、対象になるような業種、それから、悪質な客引きをやっているようなところはこの中に入ってこない。","respondent":"上垣外生活安全担当課長","answer":"条例化というお話をいただきました。現段階では、そういったことも検討する余地があると思いますけれども、現段階ではそういう段階ではないと考えております。","id":"exchange-035"},{"speaker":"鈴木（真）委員","kind":"質問","question":"例えば地域の中での区政協力委員会、区政懇談会とか、そういうところはそんなに話が出てこないものなのですか。その辺の状況を説明を求めました。","respondent":"上垣外生活安全担当課長","answer":"区政協力委員会等でのご意見というお話でしたけれども、私の知っている限りでは、そのような意見は上がってきていないのが事実です。","id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"意見","question":"割合と我々の耳、私は五反田とはちょっと離れた地域にいますけれども、そういう人たちからも話は結構入ってきます。少し品川区の条例はどうなのという話は聞かれる中で、そこら辺、もう１回お願いしますとの意見を述べました。","respondent":"中川原地域振興事業部長","answer":"先ほど来ご質問がありましたが、防止と犯罪の対応の両方から一緒に協力することで安全・安心のまちづくりをしようということで進めてきております。","id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"十分わかります。ぜひ１点だけ、それと同時に万が一減らなかったときには、やはり品川区としてその先も考えておいてもらいたいということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"五反田の有楽街だったら「五反田の盛り場」と言ったほうが明らかにわかるではないですか。もともと呼んでいないのか、その点、来賓の呼び方についての考え方を説明を求めました。","respondent":"上垣外生活安全担当課長","answer":"今回は、この当初の計画で実施させていただきたいと思っているのですけれども、次回からは検討していきたいと考えております。具体的な名称につきましては失念いたしましたけれども、声をかけておりまして、パレードに参加していただく予定をしております。","id":"exchange-039"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは要望です。これはあえてここに個名を出されているということは、協力してもらうということで位置づけをしているのか、その点だけ最後に説明を求めました。","respondent":"上垣外生活安全担当課長","answer":"現在のところ、まだ計画途上のものでもありますけれども、来賓としてご招待するのはこちらの方となっております。あるいはパレードの参加者といいますか、表現はいろいろあり得ると思いますけれども、参加を広く呼びかけていきたいと考えております。","id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういう宣言なのか、どういう文面なのか、そこを伺いたいと思います。いわばされるものについての取り組みという、そういう関係にあるのか、そこをご説明いただきたい。","respondent":"上垣外生活安全担当課長","answer":"「品川区民の安全向上に関する協働宣言」となっておりまして、これは平成２３年３月に区と４警察署との間で締結させていただいたものであります。今回のキャンペーンで予定されます宣言とはまた別のものです。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"では、今回の見立ての宣言は、どういう名前の宣言なのか、いつ、どのように、誰がつくられて、どういう内容の文面なのか、そこをご説明ほしいと求めました。","respondent":"中川原地域振興事業部長","answer":"その中で、今回、区と幹事署の大崎署で相談してこの１０月１４日に向けてキャンペーンの準備を進めてきたというのが本日の報告の内容です。今回、キャンペーン活動をしたいということで取り組んだのが、今回の「大崎盛り場環境浄化キャンペーン」です。","id":"exchange-042"},{"speaker":"中塚委員","kind":"質問","question":"そういうのはなくて、全体の今言った計画だと、そういうことですか。では、当日も含めてもう一度ご説明いただけますか。","respondent":"上垣外生活安全担当課長","answer":"平成２３年３月に結びました宣言とはまた別の趣旨で宣言をいたすものであります。当事者としましては、警察署と、区と、料飲組合との中で、今、調整をしている最中であります。","id":"exchange-043"},{"speaker":"中塚委員","kind":"質問","question":"要するに当日、式典の中で宣言というかアピール文を、今、発表するということだと思うのです。それを決めるわけですから、どういう中身のものを決めるのか、そこをご説明いただけますか。","respondent":"上垣外生活安全担当課長","answer":"宣言の中身につきましては、まだこれから詰めていっている最中でありますけれども、大まかな柱といたしましては、犯罪のないまちにしよう、そういった内容を柱にいたしまして、その細目を詰めているところであります。","id":"exchange-044"},{"speaker":"山元委員","kind":"質問","question":"そんなような内容の物を何か張りつけるというか、こういう調印をしましたので、うちの店は反対だよとかと何かそういうことまで考えていらっしゃるのか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"具体的な表示をするか否かについては、検討はしておりません。","id":"exchange-045"},{"speaker":"山元委員","kind":"質問","question":"なさっていない。うちは反対だよというもの、やはりこういうキャンペーンをやるわけですから張るとこまで考えていくべきではないかと思いますが、いかがか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"ただ、これを１店舗ごとに表示することについてはいろいろよろしくないと思う方もいらっしゃるのではないかというところです。こういったような形で、その表示につきましては、機運の盛り上がりに応じまして実施していきたいと考えております。","id":"exchange-046"},{"speaker":"山元委員","kind":"質問","question":"機運はぜひ盛り上がってもらいたいと思うのですけれども、やはり生活安全担当課長の中で張ることによっていろいろ被害とおっしゃっていたのですけれども、それを今度は逆に守るのが警察だし、追放というか、それをするためには、それは勇気が要ることかもしれないけれども、大事ではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"}]},{"id":"topic-04","title":"区立総合区民会館および区立体育館における指定管理者のモニタリング・評価結果","agenda":"区立総合区民会館および区立体育館における指定管理者のモニタリング・評価結果","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"いわゆる決算としての要素が強いのかどうか、そこを１点伺いたいと思うのです。例えば戸越体育館はなかなかとりにくいという話もよく伺いますので、あらかじめ落としておいていただければ一目瞭然になってくるのだと思うのです。","respondent":"安藤文化スポーツ振興課長","answer":"報告の意味と申しましょうか、これは品川区指定管理者制度活用に係る基本方針、平成１７年７月２９日に決定されています。そういうものに対して、しっかり議会への報告をしていくというふうに私は認識しています。","id":"exchange-048"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひガイドラインの様式そのものをできるだけわかりやすく常に改善していただきたいと思うのですけれども、その点を１点伺いたいと思います。区民の利便性を大事に考えることが公の施設としての役割ではないのかと思うのですけれども、その点についても伺いたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"予算の財政の視点はどうかというような問いに対して私どもが考えるには、指定管理者の目的の一つの経費の節減は指定管理者の大きなものです。区民のニーズに合ったものを展開しながら利用料収入を上げていきなさいよ、そういうような視点でここを書かせていただきました。","id":"exchange-049"},{"speaker":"中塚委員","kind":"質問・要望","question":"改善いただきたいのは、そういうところに絞っても、そういう改善の仕方はあると思うのです。ぜひそこは改善してほしいと求めましたけれども、改めていかがか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"このシートにつきましては、先ほどもご説明しましたけれども、全庁的なシートの中でやってあります。ただ、どこまでやれるかは定かではございませんけれども、とりあえず全庁画一的なものであるということでご理解いただきたいと思います。","id":"exchange-050"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは図っていくのは指定管理者ですから、指定管理者目線になります。その辺の改善も含めてぜひ検討していただきたいと思うのですが、今後のもしビジョンがあればお答えほしいと求めました。","respondent":"安藤文化スポーツ振興課長","answer":"その中で私どもも、そういう部分ではなくして、しっかり経営の視点も取り入れてやってほしいという思いでこういった明記をさせていただいています。先ほどの表現方法だとかそこら辺も、来年度に向けてはちょっと研究させていただきたいと思っています。","id":"exchange-051"}]},{"id":"topic-05","title":"品川歴史館特別展「大井に大仏がやってきた！ ─養玉院如来寺の歴史と寺宝─」","agenda":"品川歴史館特別展「大井に大仏がやってきた！ ─養玉院如来寺の歴史と寺宝─」","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"今回、大仏のこういうイベントを特別展として品川歴史館でするわけですけれども、本家本元の如来寺には担当課長として伺いましたか。もし伺ったのであるならば、どういう感想を持ったか説明を求めました。","respondent":"安藤文化スポーツ振興課長","answer":"先ほど冒頭に言いましたけれども、ここには本当に大きな仏像がお寺の本堂の中に５体おさまっているというものでございました。今回の特別展は、今回の特別展も本当に品川区が誇る養玉院の如来寺と五智如来、これの特別展ということで見逃せない特別展になると思ってあります。","id":"exchange-052"},{"speaker":"藤原委員","kind":"質問・要望","question":"だから、これを機会に、その観光の一つという形にこれをどうか結びつけていただきたいということを大井出身としては思うのです。最後に、その辺はいかがですかということを担当課長と、お二人にそれをどういうふうに結びつけていくかということをお伺いして終わりたいと思います。","respondent":"安藤文化スポーツ振興課長、米田商業・観光課長","answer":"そういうものと常に歴史館も連携してございまして、かつての文化財めぐりの中には養玉院もコースの中に入れていただきました。そんな中で、また特別展を契機にそういうコースの中に入れていただいて… 今、所管課長からもお話がありましたように、十分連携をとってまいりたいと思います。十分、今後はそういったことがこちらの方面でも起こせないかというようなことには、また所管とも十分連携しながらやってまいりたいと思います。","id":"exchange-053"},{"speaker":"中塚委員","kind":"質問・要望","question":"自分たちが大事にしてきたものが紹介されるのはすごくうれしいことですから、どういうふうに決めていらっしゃるのか、そこを伺いたいと思います。今、どのようなお考えがあるのか、伺いたい。","respondent":"安藤文化スポーツ振興課長","answer":"この特別展は、年に１回ずっとやってまいりました。少し研究しまして、より区民を問わず区外の方々に特別展をもっと知っていただくための研究をして、掲載させていきたいと思っています。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問","question":"このせっかくの特別展ですけれども、区内の小中学生の参加、そういう機会があるのかどうかをお伺いします。授業の一環としてですけれども、お願いします。","respondent":"安藤文化スポーツ振興課長","answer":"しかし、今、私どもで学校サイドに働きをかけて学校全体で来ていただくとか、そういうことは、今現在はしていません。情報提供として、そこら辺は周知されると思いますけれども、今の段階では子どもたちについては自主研究ということで進めます。","id":"exchange-055"},{"speaker":"吉田委員","kind":"質問・要望","question":"今、働きかけのお話ですけれども、できれば、せっかく区内にいいものがあって、歴史館に行って特別展ということで、こういうチャンスを活かしていただいて、区内の学校等にも働きかけていただき、参加していただければいいと思いますので、その辺を要望として。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"向副委員長","kind":"意見","question":"今回、私も大変楽しみにしているのですが、海外向けとか、海外の方がここといって従来どおり訪れれば対応していただけるのか、それとも、これだけ力を入れていただいていて１カ月半にわたる公開ということなので。","respondent":"安藤文化スポーツ振興課長","answer":"海外の方用に特別展を、海外の方のために特別展のご案内だとかそういうものは、今現在はつくってはございません。先ほどの話ではございませんけれども、関係所管と連携をして、より海外の方にも来ていただけるような工夫をしていきたいと思っています。","id":"exchange-057"},{"speaker":"向副委員長","kind":"質問","question":"いろいろ展示物も見ていると、涅槃図も展示するのであれば、やはり同じような宗教の共通点がある観光客の方を取り込もうと思えばできると思うのです。そのあたりは今後の課題ということで、一つのきっかけとして考えていただければいいと思うのですが、いかがか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"その展示のための一部ではありますけれども、英語版は用意しています。今後、特別展などに特別にそういうものができるかどうかは研究させていただきたいと思います。","id":"exchange-058"},{"speaker":"中塚委員","kind":"質問","question":"現状考えている問題意識や、現状の把握や、そこを伺いたいと思います。その辺も「検討する」ということの中身に含まれているのかとも思いながらも、現状の検討の中身を伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"共産党は南議員の質問の中で、ご答弁の内容をもうちょっと確認しながら、それから質疑したいということ。八潮地区の中で実施されることから、八潮との関連性がもし聞ければ、その辺も確認させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/398926?Template=document&Id=2676#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":40755,"voices":159}},{"id":"h25-20130924-7","meetingId":"h25-cm09","date":"2013年9月24日","dateIso":"2013-09-24","committee":"厚生委員会","time":"午前１０時００分～午後 ３時１２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"井上委員","kind":"質問","question":"区としてこのグループホームをどういうふうに捉えているのか、定期借地で借りるというような報告をされたときに、「５床」という表記でした。ですから、グループホームというものを区はどう捉えているのか、そこの認識をお願いします。","respondent":"中山障害者福祉課長","answer":"それから、グループホームの５床についての認識ということですが。これが完成することで、区内の知的障害者の方のグループホームは合計で７０床になります。","id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"質問の仕方がまずかったのかなと思うんですが、５床というベッド数でカウントしていくのか、住宅として、住まいとして位置づけているのか、区はどちらと捉えているのですかという質問をさせていただきました。","respondent":"中山障害者福祉課長","answer":"あくまで住まいという捉え方で考えております。","id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"条例のところで、今日、視察をさせていただいたので、その設計のほうについても少し触れてもよろしいでしょうか。さっきもちょっと担当の方に伺ったら、対処法とか、その辺の検討はどういうふうに行われて今の設計になったのか尋ねました。","respondent":"中山障害者福祉課長","answer":"収納スペースをとることも考えまして、その結果、水回りについては共用でいいだろうということで落ち着いたところです。時間帯ですとか、その中でスケジュール立てながら日常生活の管理、できることをできるだけ自力でやっていただくような工夫をしています。","id":"exchange-003"},{"speaker":"井上委員","kind":"質問・要望","question":"今の認識は変わっていますので、今、その辺については認識を改めていただくような方向でぜひ検討していただきたいというふうに思います。一言何かあればお願いします。","respondent":"中山障害者福祉課長","answer":"２年間そこで生活する中で地域の一般のアパートを借りるということになっておりますので、ミニキッチンとかを設置しているんですね。","id":"exchange-004"},{"speaker":"たけうち委員","kind":"質問・要望","question":"この辺の意味を教えていただきたいのと、指定管理者を公募しているんだと思うんですけれども、２階に児童のほうの思春期サポートが入りますよね。その辺の事業者間の連携のあり方みたいなものについての区の考え方がありましたら説明を求めました。","respondent":"中山障害者福祉課長","answer":"今、予定しているのが、こちらのほうの１階の部分の施設を利用していただくということもできようかと思います。そういった意味では、実際に就労している場面が見えるということが何よりスムーズに継続的に支援ができるところではないかと考えているところです。","id":"exchange-005"},{"speaker":"たけうち委員","kind":"質問・要望","question":"そこはぜひ区が主体的に調整していただきたいなと、これは要望させてほしいと求めました。そこをまず確認なんですが。","respondent":"中山障害者福祉課長","answer":"委員ご指摘のとおりです。","id":"exchange-006"},{"speaker":"たけうち委員","kind":"質問","question":"ただ、指定管理者ではなくて区が直営でやってくださいとか、もっと別なやり方でやってくださいというふうになる可能性もあるわけだよね。今、どうしてもそうせざるを得ないスピード的なものがあるのだったら、どうなんか尋ねました。","respondent":"中山障害者福祉課長","answer":"本当はこの第３回定例会の議案が通った後に公募をして、それで第４回定例会でというのが筋かとは私どもも考えております。今後もう少しスケジュール管理のほうを十分にして、例えば、適正な公募のスケジュールということで今後は注意していきたいと考えています。","id":"exchange-007"},{"speaker":"たけうち委員","kind":"質問","question":"今日ここで議案で指定管理するのかどうかと決めるのに、ちょっとどうなんだろう、丁寧にぜひこれからも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"渡部委員","kind":"確認","question":"そうなると、例えば指定管理者側は、もうある箱で、要するに、自分たちの使い勝手も関係なしで、そこをどうやって運営していくかとなりますよね。それの確認が一つと、あくまでも弘済会のほうで当然設計も施工もなさるわけですから、その辺の考えをちょっと説明を求めました。","respondent":"中山障害者福祉課長","answer":"就労継続支援につきましても、グループホームにつきましても、それを活用するということを前提に施設のほうの整備を先に進めすることとなりました。ただ、軽微な一般的な修繕、日常的なものにつきましては、指定管理者にお願いをする予定です。","id":"exchange-009"},{"speaker":"渡部委員","kind":"確認","question":"では、もう１回確認です。しっかり入っているというふうな認識でいいですねというのが１点と、先ほど現地でもご説明がありまして、昭和３０年代の建物だったか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"渡部委員","kind":"確認","question":"まだ２０年後のことなんですが、例えば、あらあら今回これはイメージとして２０年なんだというので私たちもいいのでしょうか。確認です。","respondent":"中山障害者福祉課長","answer":"それから、３０年たった建物ということで、残りの２０年というところで、区のほうでは借りて事業を行う予定です。まだ２０年後のその先というところまでは、実際のところ、鉄道弘済会とそこまでの話はできていないのが現状です。","id":"exchange-011"},{"speaker":"井上委員","kind":"質問・要望","question":"あったら教えていただきたいということと、区がここではそういうものが適切ではないでしょうかというようなことでは、そこ２点お願いします。","respondent":"中山障害者福祉課長","answer":"発達障害の方の就労継続支援というところで、パルレで思春期サポートの中でパソコンクラブですとか、そういったこともやっております。いろいろな状況を考えたときに、今回、事業化するところです。","id":"exchange-012"},{"speaker":"井上委員","kind":"質問","question":"第６４号議案のほうの第４条で、事業の内容で、第４条第２項で発達障害者に係る相談ということで、パルレのところは発達障害児も含むだろうというふうに思うんですが、ここの部分で、これは発達障害者に係るというのは、幾つを想定していますか尋ねました。","respondent":"中山障害者福祉課長","answer":"実はパルレの部分も含めてここは区の施設の設置の事業の中身になってきますので、この２号の中にはパルレのところも入っております。早い方であれば１２歳ぐらいから、そこから成人期ということで、長ければ４０代ぐらいまでというふうに考えていただければと思います。","id":"exchange-013"},{"speaker":"井上委員","kind":"質問","question":"そこで安心しました。それとあと、就労継続Ａなんですけれども、品川区に就労継続Ａは、これで幾つになって、どこがあるのか尋ねました。","respondent":"中山障害者福祉課長","answer":"現在、区内で就労継続Ａ型をやっているのは、福祉工場しながわの１カ所になります。なので、２３区の中でもＡ型の事業所をやっているところはすごく少ないというふうに認識しています。","id":"exchange-014"},{"speaker":"井上委員","kind":"質問","question":"ここでは、説明によると、発達障害就労継続Ａ型事業も行うということで、それはどういうイメージでされて、就労継続Ａ型事業という私の認識だったら、一般とか就労できる人たち向けの訓練みたいなものをＡ型というふうに思っていたので、福祉工場みたいなものをここにつくるという今の感じか尋ねました。","respondent":"中山障害者福祉課長","answer":"区内には就労継続Ｂ型の施設がたくさんありますし、何が違うかというと、その雇用型なのか非雇用型なのかというところになります。あくまでここは就労移行支援ではないので、最低賃金をしっかりと獲得できるぐらいの仕事をしていただくというようなイメージの施設になります。","id":"exchange-015"},{"speaker":"井上委員","kind":"質問・要望","question":"できればそういうふうにしていただきたいということも思うんですが、そこで就労継続で指定管理者の中に、そこのところは仕様書として、それをしてくださいということを盛り込むということか尋ねました。","respondent":"中山障害者福祉課長","answer":"今回の提案の中身の中で、Ａ型とＢ型とそれぞれ出していただきます。要するに、仕事をとってこられるかどうか、そこが多分今回のプロポーザルの肝になってくるかなというふうには考えているところです。","id":"exchange-016"},{"speaker":"井上委員","kind":"確認","question":"本当だったら新規だから、どのようなプロセスでしていくんだろうという、そこが今回はどうだったのかということを一つだけ確認。","respondent":"中山障害者福祉課長","answer":"２回、都合全部で４回事業説明と最後に工事の説明会ということで、その質問にできるだけ具体的にお答えするようにということでやってまいりました。","id":"exchange-017"},{"speaker":"井上委員","kind":"質問・要望","question":"ぜひいろいろな方たちとコミュニケーションをとっていくということを、ぜひこれからも続けていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"先ほども就労のほうでは２カ所目だということなんですけれども、小さい保育園や学齢期は、学校の中でどうしていくのか。先ほども言いましたけれども、そういった相談窓口的な、区が関わっているところでは何か所ぐらいあるのか説明を求めました。","respondent":"中山障害者福祉課長","answer":"相談の入り口から、そしてコンパスという発達障害児向けの事業も行っておりますので、そこで療育をしていただくような形になります。それで、Ａとしては２カ所目の事業所になるんですが、発達障害の方に特化した就労継続施設というのは今回が初めてになります。","id":"exchange-019"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"これは指定管理には社会福祉法人かなと思っていたんですけれども、株式会社もあり得る、参入できるというようになってくるのか尋ねました。","respondent":"中山障害者福祉課長","answer":"就労継続の事業をやっていること、そして何より発達障害の方に理解があることというのがプロポの選定の基準になってきますので、実際は社会福祉法人の方が運営するようなことになろうかと思います。","id":"exchange-020"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"実際は社会福祉法人になってくるということですけれども、１０月１日からですよね、手を挙げていく、募集をされていくというところで。選定していく中で、そういう方向に株式会社もありだと、社会福祉法人でやっていくという担保があるのかどうかをお聞かせいただきたい。","respondent":"中山障害者福祉課長","answer":"そういう意味では、委員のおっしゃる担保というのは必ずしもあるわけではありません。経験があれば、しっかりと安心して区立施設を任せられる、そういったところに事業のほうを委託していきたいというふうに考えているところです。","id":"exchange-021"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"私たちも求めてきたことですけれども、施設ができても、やっぱり運営が一番要になってくると思うんですね。これだけ待たれて本当に期待されている施設が、そこへの担保がないというところでは、私たちはこの議案には賛成できないということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-02","title":"の第５９号議案、平成２５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"の第５９号議案、平成２５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"井上委員","kind":"質問","question":"なぜこれができたのかという、その理由をお願いします。上大崎の債務負担行為で１,９００万円余というのは、それとも一部が債務負担行為となっているのか、その辺をお願いします。","respondent":"永尾高齢者福祉課長、中山障害者福祉課長","answer":"９月をめどに準備を進めているところですが、予定としては９月だったんですけれども、動く予定になっております。上大崎の関係ですけれども、こちらは本年度１００％基本設計を終わらせる予定だったんですけれども… 今回この中等度難聴児発達支援事業につきましては、東京都のほうが市区町村対象事業として補助事業を行いました。それに伴い、品川区のほうも東京都の事業を活用する形で実施するものです。","id":"exchange-023"},{"speaker":"井上委員","kind":"質問","question":"最初の認知症のところ、区のほうのスタッフの総勢が何人かということと、交代でと言われて、荏原医師会のほうは３名の方が交代でというふうなお話だったので、それはアウトリーチで何班かグループができて回っていくという仕組みなのか、その辺は完全に固まっているものなのか説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"区のスタッフにつきましては、３人の保健師で決定をしているところです。そのほか看護師１名、３名で何チームと、そういうような考え方にはなっておりません。","id":"exchange-024"},{"speaker":"井上委員","kind":"質問","question":"どういった方に対して、地域包括支援センターに情報が行って回ろうとするのか、訪問する人たちはどういうふうな経緯で行くのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"在宅支援センターの方につきましては、まだ検討が十分なところではないんですけれども、現在のところ。は、この認知症コーディネーターのほうにつなげて、医療のほうに流れるような形に持っていくという方法を今想定しております。","id":"exchange-025"},{"speaker":"渡部委員","kind":"質問","question":"わかればまずそれを教えてほしいのと、これは事業年度が長くてこれからやっていかれるんですけれども、７月の厚生委員会でご説明がありましたよね。その基本計画が遅れますということで５０％減額しているのか、なぜなのかという、その２点をお伺いできますか尋ねました。","respondent":"中山障害者福祉課長、永尾高齢者福祉課長","answer":"この事業を今回東京都が始める前から区の単費でやっていたのは、大田区のほうで実施していました。今、少なくともお一人の方はこれからこの事業が整うことで補助の対象になるかなというふうに考えているところです。上大崎三丁目高齢者福祉施設整備費のことですけれども、最初の公募期間を当初予算のときよりも延ばしまして、その関係で事業者の決定が遅れました。","id":"exchange-026"},{"speaker":"渡部委員","kind":"質問","question":"このとおり行っているということなんですか。このとおり行っていて、この時点でもう間に合わないやというのがわかっていて、今回、補正が上がってきたということなんか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"７月の時点でスケジュールの変更が必要だということで、７月に報告した内容が変更後のスケジュールというふうになっております。","id":"exchange-027"},{"speaker":"渡部委員","kind":"確認","question":"では、これに基づいて動いていてということであれば、ちょっとその確認だったので、申しわけございません。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"あくつ委員","kind":"質問・要望","question":"都の事業で平成２５年度もモデル実施をされているようなんですけれども、私もいろいろ高齢者福祉課にお願いをしてご相談に乗っていただいたこともあるんですけれども、平成２５年度の実績みたいなものがあれば教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"今年度については、まだアウトリーチチームはこれから動くということですので、実績というのは特にはございません。","id":"exchange-029"},{"speaker":"あくつ委員","kind":"確認","question":"失礼しました。そういった今この内容を見ると、今までもそういったことはされていたのかどうか、そこの確認をさせてください。","respondent":"永尾高齢者福祉課長","answer":"区では個別のケースの中で在宅支援センターのケアマネジャーがつなげるということはありましたけれども、こういう仕組みとしてつなげるというのは、今回が初めてです。","id":"exchange-030"},{"speaker":"たけうち委員","kind":"確認","question":"一応確認ですけれども、こういう全く同じ考え方でいいのかどうかということと、その辺は所管としてはあまりかんでいないのか。","respondent":"永尾高齢者福祉課長、中山障害者福祉課長","answer":"こちらの事業につきましては、両医師会との調整を必要としておりまして、その調整の時間と、このプレス発表の期間が間に合わなかったということで載っていないということです。 都の制度を活用するというところですので、最大ですと、耳穴型が１３万７,０００円ということになりますので、それが必要だよということで医師の診断が出れば、最高額はその金額になります。","id":"exchange-031"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"認知症のケアのところで、つなげる仕組みが初めてだというところなんですけれども、もうちょっと何がどう違うのかを具体的に教えていただきたいです。それと、８月１日から引き下げが実施されていますけれども、このシステムはもう改修されて実施はされているということなんか尋ねました。","respondent":"永尾高齢者福祉課長、竹田生活福祉課長","answer":"これまでのつなぎの部分というのは、本当に個別のケースの中でのかかりつけ医のつなぎというような言い方をしていました。在宅介護支援センターのケアマネジャーだけではなくて… 基準改定の件ですが、８月１日の基準改定に向けまして、既に実施済みのものです。本来は６月に補正予算を組みたかったところですが、東京都より正式な通知が間に合わなかったものですから、今回の補正とさせていただいたものです。","id":"exchange-032"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"認知症のところはわかりました。それを３年かけて軽減措置がとられているというところなんですけれども、再来年になれば、そこに予算がまたついていくということなんか尋ねました。","respondent":"竹田生活福祉課長","answer":"国および東京都から今回のシステム改修につきましては、来年、再来年にシステム改修が極力必要がないように改修することということで指導されておりますので、来年、再来年を見越して、極力改修が必要のないような形でしたところです。","id":"exchange-033"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"でも、１０％ともう掲げられている中で、それが、要は、その目標を達成していくために３カ年かけていくということなんじゃないでしょうか。なのに、それが来年はどうかわからないというのは、１０％引き下げありきの今回そういう計画なのではないんか尋ねました。","respondent":"竹田生活福祉課長","answer":"来年度以降につきましては、これはあくまでも計画の段階でございまして、実際に計画どおり実施されるかというのは未定です。当然その３年の間にいろいろ状況が変われば、生活扶助費自体が毎年適正な水準かどうかということが見極められていくものだと考えております。","id":"exchange-034"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"何で１０％と掲げているのかなという、そのように言われているということしか言いようがないのかなとも思うので、このぐらいにしておきます。もしこれが５人分を超えた場合というのはどうしていくのかなというのと、あと、今年度だけの予算なのかどうかということを説明を求めました。","respondent":"中山障害者福祉課長","answer":"予算上は５人ということにしておりますが、この事業に該当する方がいらっしゃれば、枠の中で対応していきたいというふうに思っております。","id":"exchange-035"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"やはり健康で文化的な最低限の生活を営む権利としての命を守る最後のラインだというところでは、第２５条を踏みにじるものだなと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"}]},{"id":"topic-03","title":"の３、報告事項、平成２４年度指定管理者の管理に対するモニタリング・評価の結果","agenda":"の３、報告事項、平成２４年度指定管理者の管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"４点質問させていただきたいんですが、二つずつまとめて質問します。７ページの管理運営委託料と利用料金なんですが、平成２４年の委託料が非常に多いような気がするんですが、これはこれでよろしいのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"こちらの金額の差というのは、平成２３年５月に開設いたしまして、初度調弁の分が大きく入っているということです。平成２４年度が３億３,８７６万９,５１４円ということで、こちらは稼働率が上がったということでの利用料金の増額ということになっております。","id":"exchange-037"},{"speaker":"鈴木（博）委員","kind":"質問","question":"１２ページの荏原在宅サービスセンターなんですけれども、これは結局、それに対する対策としてこういうことをやったということなんでしょうか。具体的にこの辺が、こちらの自己申告だと思うので、ちょっとよくわからなかったのでお聞きしたいんです。","respondent":"永尾高齢者福祉課長","answer":"具体的というよりは、高齢者のサービスセンターの中で、インフルエンザ、ノロウイルス等の感染症というのが多く発生しがちだというところで、事業者みずからがマニュアルの見直しを行ったというふうに聞いております。","id":"exchange-038"},{"speaker":"鈴木（博）委員","kind":"質問","question":"いろいろ対策を考えているみたいなんですけれども、これは中延の在宅サービスセンターで、品川総合福祉センターは、中延で特養もやっていますよね。同じところでやっていて同じ地域なのに、例えばそういうことを利用するとかということも方法としてあるので、いかがなんか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"このなかのぶ会等を活用して、どういうプログラムにしたほうがいいのかということを話し合っていくべきだというふうに思っておりますので、区のほうもそういう支援をしていきたいというふうに思っております。","id":"exchange-039"},{"speaker":"井上委員","kind":"質問","question":"どういう意味で載せているのかということが１点と、３ページで、なぜこれがすぐ入所できないという事態になっているのかということをまずお聞きします。","respondent":"永尾高齢者福祉課長","answer":"ご本人が見学に行った後に、いや、もうちょっと在宅で頑張るというご家族の方も結構いらっしゃいます。その見学だとか説明とかをしている間に日程的に空白ができてしまって。","id":"exchange-040"},{"speaker":"井上委員","kind":"質問","question":"施設との何らかのケアの体制をもう少し違う形にしていけば改善をされるというものであるのかどうかというところも、認定の方法が本当に適切なんですかと、区の体制としての認定のところに課題はないのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"自分のご家族の気持ちの中で後ろめたさというか、そういうものもあったりということで、葛藤があるように見受けられます。もう１週間ぐらい待ってくれとか、そういう形でのお話があったりということで、あきが出てくるというような状況です。","id":"exchange-041"},{"speaker":"井上委員","kind":"確認","question":"ちょっと基本的なところで確認なんですが、そこはこの今報告をされた中で利用料金制をとっているのは、健康センターだけなんでしょうか。ちょっとそこを説明をお願いします。","respondent":"永尾高齢者福祉課長","answer":"利用料金のところは、自己負担の部分と、あと介護報酬の部分と、合計した金額が入っています。そのほか、ここに書いてあるとおり、食費とか居住費等のご本人の負担というのもこの中に入っているということです。","id":"exchange-042"},{"speaker":"井上委員","kind":"意見","question":"どういう根拠があるのかということと、そちらのどういったところに委託事業とか再委託をされているのか、具体的にお知らせくださいとの意見を述べました。","respondent":"永尾高齢者福祉課長","answer":"本日ご説明してある施設は全部区立の施設になりまして、区立の施設としての維持管理の部分の金額を委託料として事業者にお渡ししている内容です。給食なども専門の給食の業者に委託をして提供してもらう、そういうような内容になっております。","id":"exchange-043"},{"speaker":"井上委員","kind":"質問","question":"維持管理費の管理委託とすれば、規模は同じなんだから、そんなに毎年この管理委託料が変わるということについては、何か今、説明がちょっと違うのかなと思ったんですけれども、そこについてはどういう状況なんか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"この管理委託料は毎年毎年算定をするんですけれども、経常的に発生するものと、例えば、大規模なのは区が直接なんですけれども、ちょっとした修繕だとか、改修とかの部分は、指定管理者にお願いしていますので、その部分で出っ込み引っ込みが出てくるです。","id":"exchange-044"},{"speaker":"井上委員","kind":"質問","question":"稼働率に対して変化があるという認識ではなくていいんですねということが１点と、高齢者住宅なんですけれども、どこでしたでしょうか……。〔「３６ページ」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"井上委員","kind":"質問","question":"３６ページの４番、わかくさ荘のところで、「ワーデン業務は引き続き福祉工場しながわに業務委託し」というのは、就労継続Ａ事業の福祉工場に業務委託をするというのがよくわからないんですけれども、これについてはどういうことか尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"ワーデン業務をこの福祉工場しながわに業務委託という、こちらのほうについては、従来からこちらのほうにお願いをして行っているというふうに聞いておりますけれども、今の委員の質問は業務委託になじまないというお尋ねなんでしょうか。","id":"exchange-046"},{"speaker":"井上委員","kind":"質問","question":"では、ワーデン業務は、ここでは何を言ってるのか尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"午後７時以降ということになるんですけれども、このサポしながわのほうから３名雇用して、ローテーションでもってこの業務委託を行っているです。","id":"exchange-047"},{"speaker":"井上委員","kind":"質問","question":"福祉工場しながわに管理委託している法人に対してという意味なのでしょうか。サポしながわの３名雇用、改善をしていただいたほうがいいと思いますが、いかがか尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"この管理業務委託につきましても、やはりきちんとその内容について、これまでどおりでいいのか。やはりもう少し危機管理、こういった意識も持ちながら、その辺は十分これからもきちんとした体制を築いてまいりたいというふうに思っております。","id":"exchange-048"},{"speaker":"井上委員","kind":"質問","question":"今のところで、もし何か表記が違うとかがあるようでしたら、次回の委員会でも、申しわけありませんけれども、お願いしたいと思います。そもそもこれはもう問題なんじゃないですかと、離職率がどうなのか、そこのところの今の現状はどのようになっているんか尋ねました。","respondent":"中山障害者福祉課長","answer":"１点目のご指摘の児童遊具のところですけれども、そういう意味では、きちっとした管理をしています。職員配置自体は、また研修等も充実させていきながら、児童の発達支援のほうをしっかりと対応できるような体制を今整えているところです。","id":"exchange-049"},{"speaker":"井上委員","kind":"質問","question":"基準より多いということだったんですけれども、基準が何名で、平成２４年度に何人いて、平成２４年度に退職された方が何人いて、その分が平成２５年度に採用されたのか、そこの具体的なところはどうなっているのか尋ねました。","respondent":"中山障害者福祉課長","answer":"申しわけありません、ただいま具体的な個々の人数というのは持っておりません。当然補充はされておりますので、平成２４年度と平成２５年度を比較したときに、直接処遇する職員の数が少なくなっているということはございません。","id":"exchange-050"},{"speaker":"井上委員","kind":"質問","question":"あまり快適ではないなというふうに思って見ていましたので、ここについての何か区民からのご意見とか、そういったものは一切ないのか。なかったとしても、行ったときにそういうことを感じたので、何らかの対策が必要と思うんですが、いかがか尋ねました。","respondent":"江部健康課長","answer":"ただ、この問題は確かに私も行ってみてそうだなという気もしますので、今、エスフォルタのほうに検討を指示をしております。その結果はまだ把握しておりません。","id":"exchange-051"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"平成２４年、平成２２年から見ても、何か問題はなかったのかどうかということ。何が起きるかわからないというところでは、大変なんじゃないかなという、そういうところの声なんかはないものなのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"こちらはあくまでも医師の指示に従ってやるということになりますので、そういう指示のない中でやるということではございません。全て受け入れるということではなくて、可能な方についての受け入れを行っているところです。","id":"exchange-052"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"２ページ目の４番の「常勤職員９８％の介護福祉士を配置」と書いてあるんですけれども、常勤職員と非常勤職員の割合というのは、どうなっているのか。今、ほかのページにも書いてありましたけれども、やっぱり離職率が３年以内にどれぐらい割合があるのかというのをちょっと教えていただきたいんです。","respondent":"永尾高齢者福祉課長、早津健康福祉事業部長","answer":"ショートの場合だと、継続的に見ている方ではない場合もありますので、そんなに大きな医療行為の必要な人を受け入れるということはあまりないです。設置基準等は満たしているとは思いますけれども、申しわけありませんけれども… 処遇改善交付金は確かになくなったわけですが、それがなくなるときに、介護報酬自体が人件費分加算されておりますので、全体としてバランスは保たれているです。","id":"exchange-053"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"３ページと５ページの改善が必要とされた原因の分析及び対応方針の１個目の丸のところが、違う社会福祉法人なのに文章が全く同じなんですね。もしくは、こういった傾向だよというのがあるのかなというの、ちょっと素朴な疑問ですとの意見を述べました。","respondent":"永尾高齢者福祉課長","answer":"全庁的な視点として経営会議での評価ということ、これを合わせた内容で総括シートというものをつくっております。要医療状態になるというのは、特養の中では共通するような課題になっているので、同じような表記になっております。","id":"exchange-054"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"そうなんですね、ごめんなさい。こういった高齢化、重度化がいろいろ進んでいる中で、体制のプラスなんかは考えられているのかどうかを説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"介護度改善事業のほうは、平成２５年度に開始をしたところですので、この平成２４年度の中にはまだ反映はされておりません。どこの施設でもそうなんですけれども、介護職員の技術や知識の向上を目指すという項目が今後の方針の中に入っているということになっておりますので。","id":"exchange-055"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"はい、わかりました。４５ページの西大井福祉園のところで、就労Ｂ型事業の利用率というのは、Ｂ型の利用率というのがどこかに出ているのか説明を求めました。","respondent":"中山障害者福祉課長","answer":"済みません、この１０２％というのが生活介護事業のほうの利用率になっておりまして、就労継続支援Ｂ型のほうは載っていないんですが、こちらのほうも西大井福祉園のほうは１００％を超えているような状況です。","id":"exchange-056"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"最後に、保健センターのところです。今回、その利用者へのアンケートとかそういうものではなく、直接的な説明というのは行う予定はあるのか尋ねました。","respondent":"江部健康課長","answer":"５年前、教室のメニューなどが結構特徴的なところが変わって、今までのお客さんが利用できないということで苦情があったことは聞いております。説明会のほうは３社ほどいらっしゃいましたけれども、今、決定手続をとっている段階に入っておりますということをご報告いたします。","id":"exchange-057"},{"speaker":"井上委員","kind":"質問","question":"利用したいと思う希望のところが１００％ということではないというようなこの数字を見ると、事業者の努力不足ですよと言っているのか、その辺はいかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"ですので、事業者としては、行きたくないというふうに思わせないようなプログラムの工夫というのは必要なのかというふうに考えているところです。","id":"exchange-058"},{"speaker":"井上委員","kind":"意見","question":"だとすると、来年度からこの総括シートの中に、登録率が何％なのかということを載せていただければ、私たちもこのモニタリングを見て、どういうところに課題があるのかということがわかると思いますので、その評価シートの工夫をちょっと検討いただければなというふうに思いますとの意見を述べました。","respondent":"永尾高齢者福祉課長","answer":"登録率について平均をどういうふうに出すかとか、そういう課題もありますので、事業者全部含めて検討してまいります。","id":"exchange-059"},{"speaker":"渡部委員","kind":"質問","question":"１点だけ済みません。これに関しては、しっかりと改善をしていただいて、その改善の報告とかが区に上がってくる仕組みになっているのかどうかだけ説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"それとともに区も現場に出向いて、実際に現状どういうサービスをされているかということを確認をした上で、また来年度の事業計画を決めるというようなサイクルになっております。","id":"exchange-060"},{"speaker":"渡部委員","kind":"質問・要望","question":"箱がどうだとか、設備がどうだというよりも、対人だと思うんですね。しっかりと次年度そういうことがないような仕組みづくりのほうを逆に強くつくっていただければと要望して終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"}]},{"id":"topic-04","title":"の４、その他","agenda":"の４、その他","exchanges":[{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"要は、関連している事業数と、そこに関わっている人数を知りたいなと思います。表になってこの事業に、就学援助とか、非課税のとか、それを人数がパッと見てわかるようになったらありがたいのですが、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/626613?Template=document&Id=3366#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":57392,"voices":173}},{"id":"h25-20130924-8","meetingId":"h25-cm09","date":"2013年9月24日","dateIso":"2013-09-24","committee":"建設委員会","time":"午前１０時００分～午後 ４時２４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を122件整理しています。","topics":[{"id":"topic-01","title":"第６５号議案、専決処分の承認を求めること","agenda":"第６５号議案、専決処分の承認を求めること","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"最初に基本的なことをお聞きしたいと思います。この間生活の変化があったのか、収入の変化などがあったのかどうか、その辺の基本的なことをまず説明を求めました。","respondent":"大串住宅担当課長","answer":"３点ほどご質問をいただきました。あくまでこちらは訴訟を起こしておりますので、この方のプライベートな部分ですので、この委員会での答弁は遠慮します。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"どういう変化があって滞納に至ったのかという判断をしたいので、その材料という意味でお聞きしたのですが、その辺もわからないのかどうか。ちょっとその辺も、収入というのはそういった意味でお伺いしたんですが、説明を求めました。","respondent":"大串住宅担当課長","answer":"入居の審査を行いますが、その審査のときにはお仕事をお持ちになっておりましたし、一定の所得があるということで入居の許可をさせていただきました。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"意見","question":"ここは指定管理者制度ですよね。指定管理者がこの被告に対してどう接していたのか、また区はその上でどう接触をしていたのか、判断材料が欲しいのでお知らせくださいとの意見を述べました。","respondent":"大串住宅担当課長","answer":"月額のこの方の居住に際しての賃料という形になります。住宅担当といたしまして担当職員から連絡を重ねて行っておりましたけれども、残念ながらこの方からのお返事がいただけなかった、こういった状況です。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"全く一度も会わないで、やはり何らかの形で面接をすることができなかったケースなのかというところを、もう一回お聞かせいただきたいのと。税金とか介護保険料、その他の部分での滞納とかは把握していらっしゃるんか尋ねました。","respondent":"大串住宅担当課長","answer":"特に他部署との関係がありますので、そちらとの連携というのは特にとっているところではございません。先ほど申し上げましたように一義的には指定管理のほうで対応していただいておりますし、今回こういう形で訴訟に踏み切った案件であるです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"提案","question":"今、税金とか介護保険料と連携していないと、行政の面で調べようと思えば調べられるのではないかと思っているのが一点と。平成２４年のこの時期から困難が出てきたというのは、どうしたらいいか提案はできないですが、最後になりますけれどいかがか尋ねました。","respondent":"大串住宅担当課長","answer":"逆にいうとアプローチをかけて何らかの返答があった方については、それなりに対応ができるです。残念ながらこちらからの呼びかけに回答いただけなかった、私どもの財産の保全ということで訴訟にまで踏み切らざるを得なかったです。","id":"exchange-005"},{"speaker":"西本委員","kind":"確認","question":"契約時はどうなっているんですか。そこら辺の、借りるときはどういう状況で、皆さん借りられているのか説明を求めました。","respondent":"大串住宅担当課長","answer":"６カ月滞納があった場合には、こういった流れに基づいて交渉あるいは今回のような訴訟といったことに流れがいっているです。提起を踏まえた上で、弁護士のほうからまたご連絡あるいは交渉といったことで進めていく、こういったことになってあります。","id":"exchange-006"},{"speaker":"西本委員","kind":"意見","question":"今までもこういうケースはたくさんあったと思いますが、そのとき最終的にどのぐらいの期間で解決されて、どういうケースで解決に至ったのか、詳しく聞きたいと思いますとの意見を述べました。","respondent":"大串住宅担当課長","answer":"ことしも３件ほどですが強制執行を行いました。一つの案件で、ものによっては１年近くかかってしまう、それによって初めて明渡しが成立するということが、最近多くなっているといったところです。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"その求めるとき、理解を求めて、手だてがないわけですから。これは要望で、以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"伊藤委員","kind":"確認","question":"やはりその前の段階で、さまざまなアプローチをしていただいて、安い金額のうちに家賃を納めていただくのが一番だと思うんです。難しいことを聞くのですけれど、家賃滞納をしないような努力はどのようにしていらっしゃるのでしょうかという確認をお願いいたします。","respondent":"大串住宅担当課長","answer":"こういったケースは、正直申し上げて少数のレアケースと認識しております。そういったことができませんので、明渡しということをやらざるを得ない、こういったところです。","id":"exchange-009"},{"speaker":"伊藤委員","kind":"質問・要望","question":"このことについてはどうこうできないけれども、だけれどそれはやはり理解を求めていくところもありますので、よろしくお願いします。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"原委員","kind":"質問","question":"聞きたいのは、この弁護士費用ですけれど、どなたが持っているんでしょうか。指定管理者か尋ねました。","respondent":"大串住宅担当課長","answer":"１件の訴訟当たり２６万円、法律事務所のほうには委託料ということでお支払いをして、訴訟事務を進めていただいているところです。区の負担です。","id":"exchange-011"},{"speaker":"原委員","kind":"質問","question":"今、質問的にももう同じような内容になっているものですから、あと訴訟になってくると全てがオープンに開示されてこないという部分もあるんですね。ですから、今後においてその辺のご意見があれば。","respondent":"大串住宅担当課長","answer":"１点目の指定管理者ですが、なかなか指定管理者にこの滞納のリスクを背負わせるというのは、難しいと考えております。こと住宅に関しましては、我々住宅担当のほうで全て対応させていただいているところです。","id":"exchange-012"},{"speaker":"原委員","kind":"質問・要望","question":"ですからその辺のところまでもう少し、この件はこれで結構だと私は思っているのですが、先々でそういった動きをやはりしていっていただきたいと。品川区は自治体として非常にいい財政内容を持っているわけですから、その辺ちょっとご意見をほしいと求めました。","respondent":"大串住宅担当課長","answer":"委員ご指摘いただいたところにつきましても、我々担当のほうで考えているところではあります。その制度自体の根幹にもかかわってくる問題かと考えておりますので、その辺は今後の検討課題とさせていただきたいと思います。","id":"exchange-013"},{"speaker":"こんの副委員長","kind":"質問","question":"先ほど質問はありませんでしたけれども、ある一定のそうした動きの中で、残念ですがやむを得ない処置だったのかなと思います。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"意見","question":"不正は許されないことであります。やはり早い時期に接触をする努力、工夫を重ねてお願いして、賛成しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]},{"id":"topic-02","title":"第５９号議案、平成２５年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第５９号議案、平成２５年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"１７ページの国道１５号線の災害時帰宅者支援でお伺いしたいんですが、ここで今、議案として上がってきています。そこのところ、前回は報告ということで文言等々いただいておりますけれども、そこら辺の考え方についてお示しほしいと求めました。","respondent":"鈴木防災課長","answer":"考え方といたしましては、正式に審議いただいて、承認いただいた時点で事業の正式な着手ができるというふうに認識しております。ですから、委員ご指摘のとおり、今回この予算案をご承認いただいてから、正式な事業として着手するというふうに考えております。","id":"exchange-016"},{"speaker":"大沢委員","kind":"質問・要望","question":"確かに報告を逐次すべしということで議会からの要望も上がっているということですが、ここの順序というのはおかしいような気がするんです。議決を求めるべき話の内容ではなかったんですけれども、どういう議決になって、原則としてどういうふうに運んでいくのか説明を求めました。","respondent":"鈴木防災課長","answer":"前回８月２６日にご報告をさせていただいた時点では、防災課長の認識としては、参考になるご意見をいただいた場というふうに認識しております。","id":"exchange-017"},{"speaker":"大沢委員","kind":"質問","question":"参考になる意見というのは、それは言葉の欺瞞であって、議案にはかかってこないけれども少なくとも報告で来ている以上は、こちらも真摯に望みながら、それなりの意見を述べるのであれば、時期は違っても同種同様な議論の内容になるのではないですかというお話をしているんですけれども、違いますか。","respondent":"松代防災まちづくり事業部長","answer":"先ほど課長からご説明したとおり、時期というものがありますし、先方からの問い合わせ等がありました。取り組むに当たりましてはこのような形で、今、話が来て、執行部としてはこのように考えているということを報告させていただいたものです。","id":"exchange-018"},{"speaker":"大沢委員","kind":"質問","question":"これ以上は結構です。あえて質問というか疑問を投げかけさせていただきましたので、その部分もお酌み取りいただきながら、今後対処をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"伊藤委員","kind":"確認","question":"国道１５号線関係について、国道１５号線はご承知のように、品川区だけではないですよね。ここでどういうことを、品川区に何を望んでどういうことをしていらっしゃるのか、ということの確認をお願いします。","respondent":"鈴木防災課長","answer":"日本全国、品川区で先行的なモデル実施をした結果を踏まえて、参考事例として全国に発信したいというのが国のほうの考え方です。考え方を踏まえまして、この地域でしっかりとした自主的な取り組みがなされていたこともありましたので、お引き受けしたという経過です。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"質問","question":"品川区のデータだけをとって国交省がこれだというのは、しかも全国に広めていく話でしょう、データ不足のような気がするんですけれど。神奈川県は川崎市あたりですか、やはり共通の課題を持って対処していくべきだと思うんですが、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"委員ご指摘のように、それぞれ区の対策への取り組み状況、一律に品川区のやり方で一緒にやりましょうというお話ではございません。次のエリアでの連携というところで、港区の防災課のほうにさせていただきまして、しっかりとした連携をしたいと考えております。","id":"exchange-021"},{"speaker":"伊藤委員","kind":"質問","question":"それが今の現状で言えると思いますので、よろしくお願いします。２７ページの百反歩道橋架替関連調査委託ですが、完了の見込みが翌年度となったためとあるんですが、もう少し具体的なことを教えていただけますか。","respondent":"溝口都市開発課長","answer":"直近に走っておりますので、それぞれの影響調査を行うために、債務負担行為を１年延ばしている形になっております。平成２５年、平成２６年の債務負担に組み直すという補正を、今回提出しているものです。","id":"exchange-022"},{"speaker":"伊藤委員","kind":"確認","question":"たしかこれは百反歩道橋が、あそこを建替えるから随意契約の話になった記憶があるんです。今ののり面の確認ですけれども、おっしゃっているのは百反歩道橋の旧自動車学校側のほうののり面ですか、どこののり面のことなんか尋ねました。","respondent":"溝口都市開発課長","answer":"すみません、説明が不足してしまいまして、申しわけありませんでした。そこの部分ののり面に階段をする計画になっておりますので、そののり面の掘削工事というのが、今回の主な延伸の理由になっている工事箇所です。","id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問","question":"のり面の掘削工事は、あくまで東海旅客鉄道株式会社が計画したんか尋ねました。","respondent":"溝口都市開発課長","answer":"のり面の掘削する工事につきましては、ＪＲ東日本のほうに委託している工事です。それの計測を、変位測定をするための調査委託というのが、今回の補正の対象になっているものです。","id":"exchange-024"},{"speaker":"伊藤委員","kind":"確認","question":"つまり、ＪＲ東日本がやっている路面の掘削工事が遅れたので、結果として百反歩道橋の調査が延期になったという判断でいいんですね。その確認だけ。","respondent":"溝口都市開発課長","answer":"ご指摘のとおり、従前計画した期間というか工事のスケジュールよりもおくれたことは、ＪＲ東日本が区から委託を受けてやっている工事が遅れたことによって、その影響としてＪＲ東海に委託しています影響調査がおくれたということになっているものですから、ご指摘のとおりです。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ここにものすごく期待されているのか、その辺の３・１１以降の流れ的な、この位置づけを教えてほしいのと。品川区がどうだったのか、国道１５号線沿線がどうだったのかというところをしっかりと実態を調査して、その辺についてのお考えを説明を求めました。","respondent":"鈴木防災課長、松代防災まちづくり事業部長","answer":"それから全体６００万円の使途ですが、いろいろな調査を担当するコンサルタントを委託する予定でございまして、その経費となります。地域の方への調査なり聞き取りもあわせて行いまして… ３０キロとなった場合は、やはり何らかの対応が必要だろうと、国も東京都も考えております。位置づけのもとで、区がどういうことをやるべきかということをしっかり踏まえた上で、対応していきたいと考えているところです。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そこのところもお伺いしたんですが、そういった意味で区の一般財源の３００万円というのは、妥当なところなんでしょうか。まず１６３台の根拠と、この場所を選ばれた理由をお伺いしたいのと、その植栽との関係も説明を求めました。","respondent":"鈴木防災課長、谷口交通安全担当課長","answer":"一問目の国道１５号線の経費についての考え方ですが、帰宅困難者対策は都と区で連携をして行うということになっております。３００万円が都の経費で、また既に東京都のほうで実施している事業についても調査した上で… 選んだ理由ですが、この付近は５月１日に放置禁止区域にかけたところですけれど、いろいろ協議の中で進めたところです。植栽については、撤去しまして駐輪場を設置していきたいと考えているところです。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"内訳を教えてほしいのと、２３ページの２カ所なんですけれども、具体的にどこなのかなと。滝王子通りはどこだかさっぱりわからなかったので、場所もあわせて、この金額をどういうふうに考えているのか、説明を求めました。","respondent":"谷口交通安全担当課長、品川木密整備担当課長","answer":"事業予算の３,９００万円の内訳ですが、ラックの設置ですとか工事、あと先ほど申し上げました植栽についてだとか、もろもろ含めましての総額です。 防災まちづくりのほうの用地取得の件をご説明いたします。この１軒をあけることによって林試の森公園の水車門のほうにそのままスムーズに通れるということで、今回この用地の取得をする方向でおります。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"今回補正で組まれているんですが、ちょっと仕組みがよくわからないんですが、よく用地の取得のときは土地開発公社を利用したりするんですが、今回補正を組んで直接区がという、そこの仕組みを説明を求めました。","respondent":"品川木密整備担当課長","answer":"この用地２カ所に関しましては、今年度急遽取得ができることになりまして、補正予算という形で進めようと考えております。それから補助金に関しましても、国が３分の１補助が出るんですが、そちらは何とかできそうということで、当年度に取得していきたいと考えております。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"歳入と歳出の関係を知りたいんですけれど、歳入の土木使用料で自転車の一時利用というのは、これはどこなんでしょうか。２点目は先ほどの用地取得で、ここに出てきているのか、その関連性を説明を求めました。","respondent":"品川木密整備担当課長、谷口交通安全担当課長","answer":"国や都の中で、国としては全国、東京都としては東京都内で補助金を出している都合上、金額が出せる見込みがあるかということでお話をしていきます。その中で、国に関しては補助金が今年度中に出せるという見込みでありましたので… 歳入の面で大森駅の関係ですけれど、２月以降に供用開始を考えておりますので、２カ月で１５０万円ぐらいを歳入を見込んでいるところです。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"それともほかのところの使用料が増えるということで、計上されているんですか。それはどちらか尋ねました。","respondent":"谷口交通安全担当課長","answer":"大森駅の増設によって歳入が増えるです。","id":"exchange-031"},{"speaker":"大沢委員","kind":"意見","question":"１７ページの国道１５号線の協議会設立と訓練経費ということですが、し尿の処理についてはどこら辺の、対策を打つために議論に加わっていただくのか。ここのところはどういうふうに考えて、協議会設立の中に組み込んで議論を深めて、し尿処理に関しては品川区はどういうふうにとの意見を述べました。","respondent":"鈴木防災課長","answer":"現時点で品川区の取り組みとしましては、回収処理作業のお願いをするという協定を結んでいるところです。区のほうでは都と連携した下水道の耐震化とあわせまして、下水道が使えない場合にも対応できるように、複数の手段で対策を講じているのが現状です。","id":"exchange-032"},{"speaker":"大沢委員","kind":"質問","question":"マンホール型はくみ取りですよね、そこの部分の費用と効果、いつ起こるともわからない災害に対して備えるというのは、費用がかかるものなのでどうしろとは言えないんですけれども、そこら辺の部分で対応方、きちっと収集する部分の体制というのは考えられて、できているんか尋ねました。","respondent":"鈴木防災課長","answer":"し尿の収集処理に関しましては、ご存じのように現在、区で独自のし尿処理車とか処理施設を持っているわけではございません。なので、先ほど申し上げましたように専門事業者の方と協定を結んで、その方たちの協力で処理をするというのが現在の考え方になっております。","id":"exchange-033"},{"speaker":"伊藤委員","kind":"質問","question":"１点だけですけれど、大森の歩道橋のことについて、記者懇談会の資料では場所も地図も添付されていました。そういう対応については、担当の課なり部で少し努力をしていただければ対処できると思うんですが、いかがか尋ねました。","respondent":"溝口都市開発課長","answer":"百反歩道橋のことでしょうか。","id":"exchange-034"},{"speaker":"伊藤委員","kind":"意見","question":"同じものを議会にも出していただけないか、さまざまな対処をしていただきますよう、お願いだけしておきますとの意見を述べました。","respondent":"あべ委員長","answer":"すみません、１点だけ。議会とプレス発表、あるいは区の広報全体の課題だと考えますので、委員会以外の場で取り上げる機会を見つけたいと思います。","id":"exchange-035"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"１点だけ確認と、要望です。この屋根の考え方を説明を求めました。","respondent":"谷口交通安全担当課長","answer":"なぜ設置をしないのかというと、あそこは舗道上ですので、建物でなく駐輪場ということで設置をします。屋根がついていると、建物という判断になります。","id":"exchange-036"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"屋根というのはほかでもある話ですから、建物とそうでないということで、公園内ではそれが許されるということなのかもしれないですが。この大森駅は非常に違法駐輪がたくさんありますので、ぜひここは積極的に進めていただくよう、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-03","title":"平成２５年請願第１２号、武蔵小山駅周辺地域の開発計画に関する請願","agenda":"平成２５年請願第１２号、武蔵小山駅周辺地域の開発計画に関する請願","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"民主主義の基本となる求めの内容であると思っていますので、私はこれからの時間、十分な審議をお願いしたいと思って、内容に入ります。周辺でいろいろ地域のまちづくりを考えている人との公平性というんですか、公平性をどう考えているのか、この２点をまずお伺いしたいと思います。","respondent":"溝口都市開発課長","answer":"そういったところでの説明は十分にできておりますし、十分にお知らせができているというふうに考えているものです。区と権利者だけで進めているわけではなく、近隣に対しての説明会または都市計画案についての説明会というのは十分進めながらやってきておりますし。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どのぐらい行っていらっしゃるんでしょうか。説明をしてほしい、意見に対して答えてほしいということに対しての、一つ教えていただきたいのと。","respondent":"溝口都市開発課長","answer":"これから開催される予定になっておりますが、ことしの１０月に都市計画案の説明会を開催を予定しておりますので。とはいえ、事業者のほうで任意ではありますが建築計画の高さの２Ｈを一つの基準として、周知して説明会を開催しているものです。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"意見を聞いてほしい。もっと信頼して行政は意見を聞くべきであると思うんですが、この不公平さをどうしてくれるのかと思うんですけれど、いかがか尋ねました。","respondent":"溝口都市開発課長","answer":"これまでも具体的な事業についてはしっかり説明をしていかないといけない、また都市計画の段階ではなく、２Ｈの範囲ではありますが説明会を開催して。そういった中で、特に改めて今回、説明会を開催してご説明するという考えはありません。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問","question":"私は、今の答弁だとそれを拒否するものであると思うのと、あと不公平感、これをどう考えているんですか。マスタープラン第６章の「計画の実現に向けて」という、都市計画法第１８条の２には「市町村は、その辺はいかがか尋ねました。","respondent":"溝口都市開発課長、藤田都市計画課長","answer":"改めて説明会という話ではなくて、窓口または呼んでいただければ、そういった必要な説明等はしっかりやっていきたいと考えているところです。マスタープランの広報についてですが、すみません、担当の所管課長からお答えします。しっかりと説明するということの中で、事業化を進める中で都市計画の手続にのっとりながら、区民の意見の把握に努めていきたいと考えています。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"地元内部の活力向上に対する要望が、この２点なんですが、これは４４％なんですね。この意向を尊重する方向、もしこれが不十分だったらこれを補完する方法をもっととっていくべきであると思うんですが、いかがか尋ねました。","respondent":"溝口都市開発課長","answer":"平成１９年に行いました地域住民等意向調査アンケートの中での上位、そして庶民的なまちというお話があります。ですからアンケートを全く無視してまちづくりを進めているというふうには、私どもは考えておりません。","id":"exchange-042"},{"speaker":"伊藤委員","kind":"質問","question":"だから、品川区独自の条例で２Ｈ対策をとっているわけであって。お願いします。","respondent":"溝口都市開発課長","answer":"建築計画の高さの２倍の範囲、個別にポスティング等をしながら説明会の開催をお知らせして、説明会をしてきております。これまでも同様の方法をとって進めてきておりますし、周辺の方々にしっかり開発事業を説明しながら、事業を進めていきたいと考えているところです。","id":"exchange-043"},{"speaker":"伊藤委員","kind":"質問・要望","question":"今の法治国家において、極端なことをいうと説明というのは、地権者と権利関係者だけでいい話じゃないですか。大きな影響があるからこそ高さの２倍、今回は６,０００名と言いましたっけ、理解してもらえる方法は何かお考えか尋ねました。","respondent":"藤田都市計画課長","answer":"その説明も近隣の方、またこれまでも２Ｈの範囲の説明会というのは、それにつきましてもしっかり指導していく中で説明会を開催していくと。","id":"exchange-044"},{"speaker":"伊藤委員","kind":"質問","question":"今の答弁の中でも、もともと事業者にはそれをする必要性はないわけではないですか、今のさまざまな法体系の中では。個々の相談を受けていくとか、そういう内容を一つ一つやっていく必要があると思うんですが、いかがか尋ねました。","respondent":"溝口都市開発課長","answer":"これまでも任意の説明会等、また法に基づく都市計画についての説明会等を行ってきた中で、窓口または電話等でお問い合わせが来ることはあります。","id":"exchange-045"},{"speaker":"伊藤委員","kind":"意見","question":"いろいろな意見をお持ちの方々がいらっしゃるから。私としては品川区のあるべき姿だと思うので、品川区のこれからの方向性について、答弁くださいとの意見を述べました。","respondent":"溝口都市開発課長","answer":"品川区の再開発に関する取り組みとしては、そういった中で、一つの手法として再開発というものが生まれてくると思います。そういったものに対しての説明、よりよい品川区のまちづくりが進められるように、再開発事業を進めていきたいと考えております。","id":"exchange-046"},{"speaker":"大沢委員","kind":"質問","question":"今、課長の言葉の節々に、何をしたいと考えていますということで、希望的な文言がありました。および近隣地域までを巻き込みながらまちづくりをしていくわけですから、この案件については対処していってもらいたいのですけれども、いかがか尋ねました。","respondent":"溝口都市開発課長","answer":"武蔵小山につきましては、区の西の玄関口、また荏原地域の中心核を担っていっていただきたいまちだと考えています。ですからそういったものの発展につながるまちづくりをしていきたいというふうに思います。","id":"exchange-047"},{"speaker":"西本委員","kind":"質問","question":"品川区のまちづくりをどういう視点で見ていくのか、去年ですか、なったと思うんですね。どういう問題があるから、それをどういうふうに分析なされて進められようとしているのか、まず根本的なところをお聞きしたいと思います。","respondent":"溝口都市開発課長","answer":"その隣の駅前通り地区の都市計画決定に向けての取り組み、そういったもののあらわれだと考えています。ですからまちづくりの方向性については、地元の方たち、また特に地権者の方を含めて、合った方向でまちづくりが進むというふうに考えているものです。","id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"ここは商店街ですから、どういうビジョンを持ってこれから自分たちの商売をして、もう当たり前の順番なのかなと思っているんですね。まちの中でいろいろな議論をして、もっと深い意見交換ができるのではないかと思うんですけれど、その考え方についていかがか尋ねました。","respondent":"溝口都市開発課長","answer":"資料にはありませんが、また説明会の開催ごとに地元町会長、こういう説明会をやりますという事前周知等を行いながら進めてきておりますし。地元の商店街とどういう形なら将来のまちづくりを進めていけるのか、個別にいろいろご相談等はしていきたいと考えているものです。","id":"exchange-049"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、意見を吸い上げて次の理事会に持ってきてくださいというぐらいのところまで言わないと、広がっていかないと思うんです。でも、少しでもわかっていただくような工夫はもう少しできると思いますので、いろいろ考えていただきたいと要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問・要望","question":"周りのことを考えない建物が建つようなところに、豊かなまちづくりは求められません」、これ本当に一部なんですが、こういうお手紙を寄せられました。面的にまちがどうなるのか、環境を守っていくという立場での区の責任は不十分で、改善が十分求められると思うんですね。","respondent":"藤田都市計画課長","answer":"そういったものをどこでという話ですが、先ほどの２Ｈの説明会でも、そういったご質問をいただいたときにしっかり説明はしていると考えております。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"提案","question":"提案もしていくと、そういった姿勢を持っていらっしゃるところを、私は決して拒否するものではないと思うんですね。そういった意味では、本当に今の足りない部分を改善してほしいという思いを伝えて、終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ただその中で、やはり私たちの要望としては最大限、関係する方々のご意見を聞いてほしい。したがって、この請願については不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"こんの副委員長","kind":"意見","question":"ある一定の説明をされていると、そしてほかの委員からもありました積み上げてきたものがあるのだというのは、この資料で理解をしております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"木村委員","kind":"質問・要望","question":"しかし、そして請願の理由として三つある中全て、本当にしっかりと説明してほしいという気持ちがすごく強くあらわれている文章だと思います。そういう中で、私たちとしては、趣旨採択という形でやっていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今回のこの請願は、行政とのコミュニケーション、協議のできる場の設置を求めますといった、本当に基本的な願いなんですね。民主主義を尊重する品川区のまちづくりを望むこの請願は、もう当然の要求であると思いますので、採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"西本委員","kind":"提案","question":"この地域をどういうふうにしていくんだということを考えることについては、行政側だけでなくて住民側もやはり考えてほしいと思います。自分たちでこういう会もあるわけですから、その会でどんどん品川区に、それこそビジョンを提案できるようなところまで育てればいいんですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"}]},{"id":"topic-04","title":"平成２５年陳情第１２号、東京都の「木密地域不燃化１０年プロジェクト」不燃化特区制度募集に対する補助２９号線沿道地区の応募除外を求める陳情","agenda":"平成２５年陳情第１２号、東京都の「木密地域不燃化１０年プロジェクト」不燃化特区制度募集に対する補助２９号線沿道地区の応募除外を求める陳情","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"現段階において品川区として住民の納得が得られていると考えているのかどうか、今後その点をどう改善していこうと思っているのかという点。その辺が今も受け継がれているのかどうか、現時点において補助２９号線道路は誰のための、改めてお伺いしたいと思います。","respondent":"藤田都市計画課長","answer":"説明が十分かどうかという点ですけれども、この辺については説明会、都と連携しながらしっかり説明をしていきたいと考えています。補助２９号線についても、最終的に現段階で必要な道路であるという東京都の判断の中で、今回の事業につながったと考えています。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"補助２９号線は最終的には必要な道路であると。先ほどの質問の、道路というのはいろいろな方が利用されるので、特にここの点をもう一回明確に答えてほしいと求めました。","respondent":"品川木密整備担当課長、藤田都市計画課長","answer":"補助２９号線の必要性ということですけれども、まず私のほうから、防災の面に関しての必要性をお答えいたします。こちらに逃げるためには一つの避難道路という形でも使えるということで、効果があるというふうに考えております。これは今、防災の観点から担当課長から説明もございましたけれども、あわせてやはり道路ネットワークの観点もあります。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その点を確認したいんですけれども、冬の夕方の６時という設定で８メートルの風速ということだったんですけれども、火災をとめていくんだと。延焼遮断帯として本当に効果があるんだと掲げること自体、すごく現実にそぐわないものでないかと思うんですが、この点はいかがか尋ねました。","respondent":"品川木密整備担当課長","answer":"当日に東京都から延焼遮断がなされたという説明の点ですが、あくまでも東京都の考え方としては、個人情報に触れることがあると困ってしまうと。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私はこのことでごり押しをしてほしくもないし、まして補助２９号線を進める意味で、本当にこういった面からはそぐわないことであると思っています。この点はいかがか尋ねました。","respondent":"品川木密整備担当課長、藤田都市計画課長","answer":"それとも道路上での車両火災のことを言っているのか、この辺の判別がつきませんので、現段階ではとにかく調査ができないという回答にします。これは防災上高いという点があるので… ですので、延焼が起きてしまう部分について不燃化を進めるという考え方を、取りまとめたものです。ご存じだとは思いますが、一応報告します。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"確認","question":"では伺いますけれど、道路の沿道をどうしていって延焼遮断効果を高めていくのかという点を、もう一度確認したいのと。道路一辺倒で進めていく中身ではないという、こういうところも十分力を注いでいかなくてはいけないと思うんですが、いかがか尋ねました。","respondent":"品川木密整備担当課長","answer":"それから地域危険度が５から３という、これは後で説明しますので、それはそのとおりです。準耐火建築物に建て替えていただくように、また空地にしていただくということを進めていくのが、この不燃化特区の一番の課題だと考えております。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問","question":"今の質問は、耐火、準耐火にしていくことが必要だと。それが普通の木造住宅を準耐火、耐火にすることで大丈夫というのか、そこのところをはっきり答えてください。","respondent":"品川木密整備担当課長","answer":"これで沿道３０メートルが耐火建築物でなくても、十分遮断効果があるというふうに考えておりますので、そこに向けて事業を進めているような考えです。沿道を全て高層建築物で固めてというようなイメージは、区としては持っておりません。","id":"exchange-063"},{"speaker":"伊藤委員","kind":"質問・要望","question":"私も国土技術研究センター、国交省、さまざまなデータを確認させていただきました。この補助２９号線等については、十二分に説明していただきたいのと、改めて品川区のお考えを説明を求めました。","respondent":"片田都市環境事業部長","answer":"最低限の高度を７メートルとか一定の高さ以上にすることによって、あるいはもらわないようにといったまちづくりも進めております。丁寧な説明を心がけているという状況ですので、委員にご質問いただきましたような整備をきちっと進めていくというのが、役割だと認識しています。","id":"exchange-064"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そちらはプロですから、生命、財産が守られたという事実はこの先たくさん要ると思います。だからそういうことをもって、地域住民にさらに説明していってほしいと求めましたが、最後に答弁をお願いいたします。","respondent":"片田都市環境事業部長","answer":"いろいろなシミュレーションの話もありましたけれども、私ども区としてはきちっと丁寧な説明に心がけて、やはり住民の生命と財産を守るという視点に立って、きちっとした説明を心がけていきたいと考えています。","id":"exchange-065"},{"speaker":"西本委員","kind":"質問・要望","question":"ちょっと教えてほしいんですが、「不燃化特区制度募集に対する補助２９号線沿道地区の応募除外を求める陳情」、募集というふうになっていますね。今、どういう状況なんか尋ねました。","respondent":"品川木密整備担当課長","answer":"現在のところ、補助２９号線沿道の不燃化特区については募集をしている段階で、今のところ正式受理というところまで受けております。ただ、確実に決定かどうかということは、今年度末もしくは来年度初頭になるかと考えております。","id":"exchange-066"},{"speaker":"西本委員","kind":"質問","question":"ということは、今の段階で募集をやめてくださいという陳情ですよね。それで、区はどう考えているんか尋ねました。","respondent":"品川木密整備担当課長","answer":"区としては、当然延焼遮断効果を高めるため、それから沿道の不燃化を進めていくために、進めていく考えです。","id":"exchange-067"},{"speaker":"西本委員","kind":"質問・要望","question":"それから９番で、これはどういう事実があってこう書かれているのか。区としての認識をお聞かせほしいと求めました。","respondent":"藤田都市計画課長","answer":"六丁目を対象にした説明会そのものは２月２７日に行われているんですが、西大井四丁目、ここの区間については現在もまだ開かれていない状況です。","id":"exchange-068"},{"speaker":"西本委員","kind":"質問","question":"西大井四丁目でも「測量説明会を行ってから、測量を始めると約束したにもかかわらず」という部分がありますが、これはどういう意味なんでしょうか。何か行政の事情が何か違ったのか、状況のほうをお伝えください。","respondent":"藤田都市計画課長","answer":"３.５キロという長い延長を測量するのに、説明会の数と同じだけの測量会社に委託をして、図面作成をしています。先般西大井四丁目のほうの勉強会もあったというお話をしましたけれども、その際にも十分説明をさせていただき、ご理解に努めたところです。","id":"exchange-069"},{"speaker":"西本委員","kind":"質問・要望","question":"測量が始まっちゃっているよね」なんていう誤解が、まあ、すごく多かったわけですよ。やはりそれは誤解なので、住民に対してもあまりよろしいことではないので、くれぐれも誤解のないような形で配慮してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そこに住んでいらっしゃるその命そのものに対して理解を得ないで、進めていいんですかと、私は問いたいです。ここに対して答えてほしいのと、正しくておかしくもないと思っていますので、それをつけ加えながら質問します。","respondent":"片田都市環境事業部長","answer":"そのことはきちっと、やはり全体の説明会は全体の概略、その上できちっと個別の説明あるいはご了解をいただきながら進めていきます。きちっとそれには耳を傾けた中で、そういう意味では東京都とも連携をとって、しっかりと進めていきたいということで考えております。","id":"exchange-071"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、やはり個々に真剣に取り組んでいただいてほしいということを、改めてお願いします。先ほどお話しさせていただいたとおり、またさまざまな形で行政も進めていると思われますので、不採択とさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"この陳情を出された方々のお気持ちは、反対意見ということで伺いました。一方で防災の強化、それを求める声というのもたくさんあるかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、そこに住んでいる住民の方々とともに十分な話し合いを行って、安全安心なまちづくりを進めていただきたいと思っています。よって、補助２９号線沿道地区の不燃化特区から除外すべきという意見に賛成なので、採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"西本委員","kind":"質問","question":"にいろいろな補償が出ているわけですから、どういう状況になるかわからない中で、まちづくりができればいいかなと考えています。不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"西本委員","kind":"意見","question":"以前、許可をして、こちらまで出てきて写真を撮られた方がいらっしゃったんですね。ということがありましたので、それはやはり会議運営上よろしくないので、そういうことも含めて考えると、冒頭だけという形でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-076"},{"speaker":"伊藤委員","kind":"意見","question":"参考までに。大概冒頭の撮影だけお願いして、その後は撮影はお控えくださいということがありましたので、それに倣っていただければいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-077"}]},{"id":"topic-05","title":"平成２５年陳情第１３号、白金幼稚園の日照環境を守ることについての陳情","agenda":"平成２５年陳情第１３号、白金幼稚園の日照環境を守ることについての陳情","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"実際都のほうはどのような、本件について都のほうの態度というか、ご意見はどのようになっているのか、教えてほしいと求めました。","respondent":"藤田都市計画課長","answer":"地域の方々のお話を受けて、地元の区のほうにもしっかり説明をするように、事業者に説明を求めたというふうに聞いてあります。それに基づいて私のほうにも説明があり、本日の資料の作成等に生かしたところです。","id":"exchange-078"},{"speaker":"大沢委員","kind":"質問","question":"この建築に関して、法令上については問題があるか、ないのか、それについて説明を求めました。","respondent":"藤田都市計画課長","answer":"私どもが確認している中では、日影規制についての法律上の観点からいうと、影響がないといいますか、法律の範囲の中で計画されているものだということで、ほかの建築にかかわる部分についても、建築確認の具体的な手続を行う中で、おそらく確認していくことになろうかと思います。","id":"exchange-079"},{"speaker":"大沢委員","kind":"意見","question":"この陳情について、都との中でらちが明かない、請願代表者の方々が、なぜ品川区のほうに陳情を出されてきたのか、そこの部分はどういうふうに区としては判断していますかとの意見を述べました。","respondent":"藤田都市計画課長","answer":"やはりこういったいろいろな案件は、まずは皆さんが生活している地元である区のほうにお話をしていくというのが、非常に多くあるケースです。今回の件についても、まず身近な地元の区のほうに意見申し上げようと思って、品川区に来たのかなと感じているところです。","id":"exchange-080"},{"speaker":"大沢委員","kind":"質問","question":"では伺いますけれども、当該の日照権について、いわゆる教育施設というものに関して、法的には日照権の扱い部分があろうかと思うんですけれど、そこのところを、教育施設についての日照権はどのように区は受けとめられているのか。","respondent":"藤田都市計画課長","answer":"もちろん商業地域等で日影規制にはなじまないということで外している場所もありますが、まずはその考え方を一旦当てはめて行っているところです。そういう形で考えていく、そういう形で進めるのが一番現実的かというふうに、私は感じているところです。","id":"exchange-081"},{"speaker":"伊藤委員","kind":"質問","question":"この大林組の建物自体が、現行の建築基準法等に適用しているものなのでしょうか。わからなければわからないで。","respondent":"藤田都市計画課長","answer":"建築基準法の関係ですけれども、もちろん建築する当時は、その当時の建築基準法に合わせてしっかり建築されたというふうに考えてあります。","id":"exchange-082"},{"speaker":"伊藤委員","kind":"確認","question":"大林組ですから、合法的にこの建物が建てられているという現状が確認できる一方、品川区にあるんでしょうか。このことに関して。","respondent":"藤田都市計画課長","answer":"その後建築基準法の改正が、１９７６年ですから昭和５１年にあって、その中でこの日影規制という考え方が導入されたです。この考え方をもとに展開しているわけですので、法の中での基準、一定のルールを守ってやっているということになるというふうに考えてあります。","id":"exchange-083"},{"speaker":"伊藤委員","kind":"確認","question":"直接の指導ができるかどうか知らないけれど、東京都になるんでしょうか、確認です。昭和５１年に制定された現行の日影規制に関して、合致しているんでしょうかという確認ができればありがたいんですが、わかりますか。","respondent":"藤田都市計画課長","answer":"資料の１枚目の中ほどに、黒四角で説明会等経過というところがありますが、東京都紛争予防条例の適用ありということを書かせていただいてあります。今のは私の間違いです……。","id":"exchange-084"},{"speaker":"伊藤委員","kind":"確認","question":"そうすると確認しますけれど、東京都紛争予防条例の適用により一義的には東京都の所管なんですねという確認と。だけれど、そういう権限以外の部分になってしまって申しわけないんですけれども、そういうことをやっていくおつもりはありますか。","respondent":"藤田都市計画課長","answer":"現行の日影規制の考え方は、現計画の地上１０階建てで、現状でも内側におさまっているのではないかと考えています。東京都のほうから仮に、それは都と連携をして、区からも事業者に対して話し合いの継続をお願いするようなことはできるのかなと考えています。","id":"exchange-085"},{"speaker":"伊藤委員","kind":"質問","question":"それからあくまで推測だけれども、いわゆる日照をさまたげる階数が建てられているということ。多少話を聞いて、考えを示したほうがいいと思うんですが、いかがか尋ねました。","respondent":"藤田都市計画課長","answer":"そこの話の中で、次に区が何をするかという中で、できるものとできないものがあります。これについては区としてできることではございませんので、話し合いの継続をお願いしていくというのが、区ができることなのかなと考えております。","id":"exchange-086"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この間お話を伺ったところによると、園庭で遊べるように残した冬至の一番大事なところが、この建築で奪われてしまう。そういったところで、今もいろいろ苦しい部分も伺ったんですけれども、今、現状において区はこういった状況をどう捉えていらっしゃるのか。","respondent":"藤田都市計画課長","answer":"工事の進め方とかそういった関係の中で、あっ旋まで進んだことが１件ありますが、あっ旋に進んだのも珍しいケースと考えています。あるいは地域の中で独自のルールをつくっていくとか、そういったことがないと、なかなか先に進めないのかなというふうに考えてあります。","id":"exchange-087"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはり子供たちの成長、この幼稚園の存続にもかかわってくるぐらいの状況であると、私は重く受けとめていただきたいと思うんですけれども。都と区も連携をして、話し合いの場をつくっていただきたいと切望するんですけれども、いかがか尋ねました。","respondent":"藤田都市計画課長","answer":"先ほど来言っていますとおり、区のほうとしてできることと、なかなかそこまで手出しができないことと、あります。そういう中で都と連携しながら、区としてできることはやっていきたいと考えていますが、都としっかりお話をしていきたいと考えています。","id":"exchange-088"},{"speaker":"西本委員","kind":"質問","question":"１１階を１０階にしたということになるので、それだけ譲歩してきたというか、建築用件を変える手間というのは、どういう形になるんでしょうか。仮に１０階からもうちょっと下げてください、どういう作業が出てきて、それはどういうふうに考えるのか。","respondent":"中村建築課長、藤田都市計画課長","answer":"周辺の皆様に説明をするという段階になりますと、これを１層減らすということになりますと、構造計算も最初から全部やり直しているのかなと推測されます。その中で、１回目はやはり階段状にしてほしいというようなお話があったというふうに聞いてあります。","id":"exchange-089"},{"speaker":"西本委員","kind":"質問・要望","question":"非常に難しい問題だと思いますけれども、もう一度区の立場として、何ができるんですか。そういうところまでの強制力が品川区にあるのかどうか、そこをはっきりしていただきたいと思うんですが、いかがか尋ねました。","respondent":"藤田都市計画課長","answer":"仮に先ほど申した２時間のエリアがかけてはいけないところに出るのであれば、これについてはしっかり指導していく、そういったような形になります。","id":"exchange-090"},{"speaker":"西本委員","kind":"意見","question":"非常にご苦労はわかりますし、もったいない話だなと思いますけれど、でも日影のところの保育園、幼稚園はたくさんあるんですよ、はっきり言って。子供たちのためにというのであれば、子供たちのための日照権をどうするかという、これは意見として終わりたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-091"},{"speaker":"原委員","kind":"質問","question":"先ほど東京都との話し合いのことがあったんですけれども、当該幼稚園自体は港区、港区との話し合いというのは、今度は区同士での関係、区境ですので、その辺はあったのかどうかということを説明を求めました。","respondent":"藤田都市計画課長","answer":"今回の案件ですけれども、７月３０日に私ども品川区のほうには都から指示があり、事業者が説明に来ました。港区のほうにはどうも９月に入ってからそのような話が行っているようで、現段階では、私は直接港区の方とはまだお話をしている段階ではございません。","id":"exchange-092"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、先ほどから各委員の方がおっしゃっていたように、第一義的には東京都だと、そういうふうに言って逃げてしまうのは簡単なことなのかなと。法的な問題ではないです、そういったことも十分に考えていただきたいと僕は思うんですけれど、その辺についてご意見があれば。","respondent":"片田都市環境事業部長","answer":"ただ強制力が、先ほども申し上げましたようにありません、相手がその話し合いに乗っていただけるかどうか、それが一番のポイントだと考えています。そういう担保はとれませんけれども、区としては地域の話をきちっと伝えていきたいと、このように考えているような状況です。","id":"exchange-093"},{"speaker":"原委員","kind":"質問・要望","question":"その辺と十分な話し合いを、これは法律の範囲ではないと思います、法的にはある程度クリアされておりますので。ですからその辺を十分に、課長ポストではなくて部長以上の方々にお力添えをいただきたいと、その辺をお酌み取りほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"再度確認なんですけれども、強制力等々も含めてどういうことができるのかというところでは、それはそうなんですかという確認です。話し合いの場を設けていただきたい、品川区としてやれることをお願いできるのかなと思いますけれど、いかがか尋ねました。","respondent":"藤田都市計画課長","answer":"もなかなか話し合いの継続ができなければ、建築の専門家から、事業者と地域の方々に対してご意見をいただけるような場の設定もできます。そういう中で話し合いの継続がなかなか形にならないということであれば、都からのお話というのもあるかと感じているところです。","id":"exchange-095"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"ある一定のルールにのっとった中で、その話し合いの場がなかなか継続されていないということでお願いしたいということだろうと、思っております。品川区の子供たちもお世話になっている幼稚園であるというところから、少しずつ寄り添う気持ちというのは、品川区もできるとわかりました。","respondent":"藤田都市計画課長","answer":"話し合いの継続の部分ですけれども、話し合いの継続を区がお願いする前提というのは、区としても動けると。脇からちょこちょこやるとかえって話がややこしくなってしまいますので、そういうことではないということで、ご理解いただければと思います。","id":"exchange-096"},{"speaker":"大沢委員","kind":"質問","question":"なぜ区に来たんですかという流れの中で、この方たちはなぜこういうものを出してきたか、こういうものを出してこられたと私は思っているんです。受け手側のこういうものに対する意識というか、体制が必要だと思うんですけれど、どうか尋ねました。","respondent":"藤田都市計画課長","answer":"そういう面では区のほうにお話をいただければ、区から東京都のほうに伝え、それで徐々に形にしていくというやり方もあるかと考えています。ひとまずは都なので、その中で区にもということであれば、都とのお話をする中でしっかり動いていきたいと考えています。","id":"exchange-097"},{"speaker":"大沢委員","kind":"質問","question":"これは民民のものですから、民民で基本的には解決しなければいけない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"西本委員","kind":"質問","question":"その前に、やはりここは本来は東京都でやるべきことだということも踏まえて、もしかしたらこういう内容ではなかったかもしれないと私は思うんですね。やはり品川区ができることというのをきっちりとお伝えして、ということの中で判断を私たちがしなければならないのではないかというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"伊藤委員","kind":"質問","question":"品川区の権限外であるということが一点、ですからもし可能性があるとするならば、話を続けていただきますように品川区がバックをアップしていくと。ですから、今できないことが相当あるので、総合的に判断して不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"教育現場というところが私は一点、どうかそこら辺のお気持ちは組んで差し上げていただきたいという思いから、趣旨には賛同したいと思います。趣旨採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"木村委員","kind":"質問","question":"いろいろなことを考えますと、どちらの肩を持つわけにもいかないという、そういう状況です。ですから、この問題に関しては趣旨採択でお願いしたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"原委員","kind":"意見","question":"ただ、やはりこの陳情に絞って話をすれば、「ご指導いただきたく」というところで品川区は指導権限がない。であれば、責任を持ったご返答ができないので、不採択という考えですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-103"},{"speaker":"飯沼委員","kind":"意見","question":"やはり都の権限というところがあっての区が、この打開をする必要性というものを重く感じていただくことが、先に進むことになると思うんですね。もし趣旨採択で一致をしてまとまるのだったら、趣旨採択にしてもよろしいですけれども、そうでなければ採択を主張いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"それと、教育環境保全ということにおいては非常に参考にさせていただきたいと思っています。残念ですが、今回は不採択という形にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"}]},{"id":"topic-06","title":"「」を行います。 はじめに、(1)専決処分の報告","agenda":"「」を行います。 はじめに、(1)専決処分の報告","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"第６５号議案と同じような質問をしてしまいますが、平成２４年１０月からの入居で、その確認をさせてほしいと求めました。その継承できる場合の特例の説明をちょっとしていただけたらと思います。","respondent":"大串住宅担当課長","answer":"当然１カ月目から、先ほどの午前中のときにもご説明させていただきましたが、督促といったことを行っている状況です。こういったものを勘案して６カ月間の時間的な猶予があるということで、この２件とも最終的には法廷への提起ということで、訴訟に至ったです。","id":"exchange-106"},{"speaker":"西本委員","kind":"質問","question":"すみません、すごく基本的なことなんですけれど、第６５号議案は議案審査で、この２件は報告で、これは金額なんか尋ねました。","respondent":"大串住宅担当課長","answer":"委員おっしゃるとおりで、３００万円というのが一つの壁になっていまして、３００万円を超えた場合には承認という形、３００万円以下であれば報告という区分けになっております。","id":"exchange-107"},{"speaker":"西本委員","kind":"質問","question":"第３０号のほうです。この１万３,１１０円という購入費となっていますが、この算定はどういう、申告になるんですか、どういう算定の方法なんか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"通常の耐用年数を５年、購入価格の総額は１万６,０００円でございましたが、経過年数による減価率を減算しまして１万３,１１０円と算出してまいりました。","id":"exchange-108"}]},{"id":"topic-07","title":"地震に関する地域危険度測定調査（第７回：東京都）結果報告","agenda":"地震に関する地域危険度測定調査（第７回：東京都）結果報告","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"豊町５丁目、二葉３丁目、ほかに何が原因があったんか尋ねました。","respondent":"品川木密整備担当課長","answer":"二葉３丁目等、先ほど説明しました上位１０位内に入っていた町丁目につきましては、一つには考えられるという点が上げられます。そういった部分でも、危険度が下がったという結果が出ているのではないかと考えます。","id":"exchange-109"},{"speaker":"伊藤委員","kind":"質問","question":"もちろん東京都の調査だから相当さまざまなシミュレーションをしているんでしょうけれども、前回の調査よりも今回の調査のほうがより具体的な被害の状況に、そもそも明確になっているんか尋ねました。","respondent":"品川木密整備担当課長","answer":"そういった面では、もっと大きな地震に対しての被害の想定、危険度が出されているというふうに考えます。やはり地盤の弱いところでは、前回の調査よりはより現実性に向けた形で調査ができているのではないかと考えております。","id":"exchange-110"},{"speaker":"伊藤委員","kind":"確認","question":"確認したい部分と、今のお話ですけれど、つまりは品川区の総合的な安全性は高まったと判断しているわけですよね、東京都は。だけれど数値が１年だけでこんなに変わるというのは、もしおわかりになれば、何か説明していただけますか。","respondent":"品川木密整備担当課長","answer":"荒川区とか足立区といったところが非常に危険度ランクが高いんですけれども、相対評価の中で順位が上がったというものと考えてください。","id":"exchange-111"},{"speaker":"飯沼委員","kind":"質問","question":"もうちょっと具体的にこういう計算だというところと、これが今後どういうふうに活用を、これを参考にしていろいろなことが行われるのかというのを説明を求めました。","respondent":"品川木密整備担当課長","answer":"６メートル以上の道路に到達すれば非常に避難がしやすいというような評価のもとで、消火のしやすさ、それを指標にあらわしているものです。危険度ランクの高い地区については道路整備なり、地区計画等そういったものが必要になるのではないかというふうには考えております。","id":"exchange-112"},{"speaker":"飯沼委員","kind":"質問","question":"それで道路幅というのをどう考えていくのかというのを、今伺ったところで疑問を抱いたので、その辺が一点です。どう伝えていくのか、どう対策をとっていくのかということが非常に重要であると思うんですが、その辺を説明を求めました。","respondent":"品川木密整備担当課長","answer":"区としてどう説明していくのかですが、もしくは４から３に下がったということで、ランク３までというのは全体の３５％になります。そういったことを区民の皆様にも伝えつつ、既存の木密事業、木密地域不燃化１０年プロジェクトを進めていく考えです。","id":"exchange-113"},{"speaker":"飯沼委員","kind":"質問・要望","question":"前から４メートル以上の道路が確保されていれば、車が入るというところで、そこは特に変わりがないということですか。そういった意味では、この品川区内で何が求められているのかというところでは、特に住民の方の声をしっかり受け取ってやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-114"},{"speaker":"西本委員","kind":"質問","question":"２の円グラフがあるところなんですけれども、パーセントだとここ５年間の中で建物の数とか当然変わってくると思うんですよ。数字で比較したほうがわかりやすいのではないか、動向が見やすいのではないかと思うんですけれど、いかがか尋ねました。","respondent":"品川木密整備担当課長","answer":"各町丁目の中で、ここに建物棟数とかそういう要素を入れて出すというのは、非常に難しいところであると思います。ちょっと忘れてしまったんですが平成１０何年かのデータを使って、今回は平成２２年のデータを使っていますので、今回の調査はやってあります。","id":"exchange-115"},{"speaker":"西本委員","kind":"質問","question":"だからこの第６回と第７回の比較をして、対策が進んでいますねとかいうのはなかなか言いづらいというところを非常に感じたんですけれども。それはそれとして、これらのデータを見て品川区の事業がかなり進んでいるというふうに、検証されているかどうかの評価は、どうか尋ねました。","respondent":"品川木密整備担当課長","answer":"もう一つは先ほど説明しましたとおり、今回地盤の部分での評価が入ったという点がかなり、大きく順位を変えているのではないかと感じます。ですので、両方の要素を抱えているというふうに思っております。","id":"exchange-116"},{"speaker":"飯沼委員","kind":"質問","question":"今日の資料だと１００位までしかデータが出ていないのでわからないので、その下の(4)災害時活動困難度を考慮した総合危険度のところで、品川区はどうなのかというところを説明を求めました。","respondent":"品川木密整備担当課長","answer":"品川区はランク４が非常に多いかとは思います、品川区南西部、大田区のあたりがやはり危険度の高い町丁目が多いという見分け方ができるかと思います。中野区、杉並区あたりの危険度ランクが高くなるという傾向が出ているということで、こちらのほうに記述しているという状況です。","id":"exchange-117"}]},{"id":"topic-08","title":"武蔵小山駅前通り地区再開発計画に関する都市計画案","agenda":"武蔵小山駅前通り地区再開発計画に関する都市計画案","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"２のところの都市計画原案の縦覧は、いつまでか教えてほしいのと。関係権利者が全体で何人いらっしゃるのかというのを教えてほしいのと。","respondent":"溝口都市開発課長","answer":"説明会については、今現在１０月１７日の開催を目途に、周知を図っていきたいと考えているものです。あくまでもＡ地区だけが対象ではありませんで、今回の都市計画原案の説明会につきましては、説明会を開催している者です。","id":"exchange-118"},{"speaker":"飯沼委員","kind":"提案","question":"これから資料をちょっと、いろいろあるかとは思うんですけれども、もうちょっと見やすく工夫していただきたいと思うのが要望と。今と全然中身が違う提案をされているわけですよね、詳しく説明をしてほしいと求めましたので、要望しておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-119"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特に１番目の「巨大地震による住宅倒壊から区民の命を守る対策を急げ」の中で、消防車を求めたんですけれども、あと消火の箇所をもう一回。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"},{"speaker":"飯沼委員","kind":"質問","question":"消火活動の問題ですね。同時多発で起こった火災に対して何カ所の消火対応が可能なのかというところを、詳しくお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-121"},{"speaker":"飯沼委員","kind":"質問","question":"消火対策の一つで伺っているんですが。震災はまだこれからなので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-122"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/890615?Template=document&Id=4084#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":99856,"voices":344}},{"id":"h25-20130924-9","meetingId":"h25-cm09","date":"2013年9月24日","dateIso":"2013-09-24","committee":"文教委員会","time":"午前１０時００分～午後 ０時２６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"第５９号議案、平成２５年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第５９号議案、平成２５年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"本多委員","kind":"質問","question":"１人で３人ということでわかりました。床面積の、その辺の関係というのは、特にないんか尋ねました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"お子さん１人当たりにつきまして３.３m2ということで考えておりますので、大体３人で６畳一間程度、９人でしたらそれが３部屋という形、そして４組でしたらそれが４部屋に区切れる形で、１人の保育ママがその３人にきっちり目を配るという形で、保育室を設置しております。","id":"exchange-001"},{"speaker":"本多委員","kind":"確認","question":"７０.６８m2で９人、６５m2に１２人というのが定員で、特にその辺は今の説明の単位に合致していると思えばいいんですよね。それだけちょっと確認を。","respondent":"今井制度改革・待機児童対策担当課長","answer":"それぞれのお部屋の状況によりまして、例えば廊下で仕切られるのか、それとも柵で仕切るのかによって、全体の面積は変わっておりますけれども、お子さんお１人当たり３.３m2で、お１人のママが１部屋９.９m2以上という形の面積は、きちんと基準のとおりになっております。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"現実的にこの２園は頑張ってきたら、その辺の状況がどういうふうに見ているのかなというのが、ちょっと伺っておきたいなと思いました。聞くまでもないのであれですけれども、きちんとそこはしていただきたいという要望にとどめたいと思うんですが、その辺を指摘しておきたいと思います。","respondent":"立川保育課長、今井制度改革・待機児童対策担当課長、和氣学務課長、渋谷指導課長","answer":"来年度以降についてはまだ国から継続等の発表はございませんけれども、都に対しましては、必要な要望をしてまいりたいと考えています。… 開設支援にかかわるものですので、私から私立保育園家賃助成につきましてお話します。私どもも坪１万２,０００円というところで考えておりますので… すごく低いのではないかですけれども、東京都の平均の小学校は５７％、中学校は４３.５％になります。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"学校教育の１つの大きな眼目のところ、教育委員会として持っていらっしゃるのかどうか、そのあたりを確認したいなと思うんです。そこを教えていただきたいのと、どういうことなのかがわからないので、考えていることを教えていただきたいなと思います。","respondent":"渋谷指導課長","answer":"月２回、３０分間をスポーツタイムとして設定し、そんな取り組みをしているというものです。総合的な子供の基礎体力向上方策第１次推進計画というところでうたわれたものでございまして、議員がおっしゃったとおりの意味合いのものです。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"先ほど来年度以降も必要な要望はしていくとおっしゃいましたけれども、私は当然だと思うし、保育園が存続できなくなっちゃいますよね。改めてそのあたりのことを伺いたいと思います。","respondent":"立川保育課長","answer":"今回の補正の中身ですが、それに上乗せをするということで、制度的につくってあります。それで、これは繰り返しになりますけれども、こういった保育士の処遇等の改善経費につきましては、今後とも引き続き国等に要望してまいります。","id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"国でそういう補助金がついたわけですから、違うことだと思いますので、そこはしっかりとお願いしたいと思います。事前の教師の解剖に対する講習会、そういう具体的な資器材だとかも含めて、どういうふうに考えているのかなということを伺いたいと思います。","respondent":"渋谷指導課長","answer":"理数フロンティア校の取り組みにつきましては、子どもの興味・関心を高めたりだとか、さまざまな工夫をするところです。教材等の選び方につきましては、教師が創意工夫をして選んでおり、もちろん、安全面、衛生面には十分配慮して進めているところです。","id":"exchange-006"},{"speaker":"塚本委員","kind":"質問・要望","question":"開設の要望があれば、定員的に例えばこれぐらいの人数までというようなところがもし数字的にあるのであれば、それを教えていただきたいのが１つ。保育ママが非常に増えてきている中で、行き先がなくなっちゃうみたいなことを懸念されることはないのかというところでお伺いしたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"補正予算で対応させていただいたとおり、２年、機能的に対応できてスポット的に対応できるこの家庭的保育事業を。３歳児の受け皿という形で、今後３歳児の受け皿については、連携園のあり方も含めて大きな課題と認識しております。","id":"exchange-007"},{"speaker":"塚本委員","kind":"質問","question":"３歳児以降のことについては明日、子ども・子育て新制度の所管事務調査で入っておりますので、またそこでもお伺いしたいと考えています。予算から見ると多分１名の方だと思うんですけれども、常駐なのか否かということと、勤務地はどこになるのかということをお伺いしたいと思います。","respondent":"渋谷指導課長","answer":"非常勤職として配置しておるところです。場所は、基本的には源氏前小学校の通級指導学級に配置して、その子どもの在籍校に行き来をしているという使い方です。","id":"exchange-008"},{"speaker":"塚本委員","kind":"質問","question":"副籍で交流するというところでのケア・アドバイザーの出番というか、役目というのはあるのかないのか、お伺いしたいと思います。","respondent":"渋谷指導課長","answer":"副籍というよりも、特別支援の通級指導学級ですので、もともとの在籍校があって、そこで週に何回か源氏前に通われているお子さんがいると。また小学校でも特別支援の支援員の経験のある方、その両者をうまく結びつけるような働きをしているというのが実際の働き方です。","id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"保護者の方が非常に悩まれるところの一つみたいなんですが、そこをカバーするのが第１の目的で、このインクルーシブ教育モデルということでの第１の目的という認識でよろしいのか尋ねました。","respondent":"渋谷指導課長","answer":"通級指導学級で、通級に行っている間に遅れてしまった分の補充をするという意味合いではございません。こんな配慮をして説明するよりも、学校の校内委員会で説明して、そんなアドバイスをする役割を果たしています。","id":"exchange-010"},{"speaker":"塚本委員","kind":"質問・要望","question":"確認で、これは東京都が特別支援教育の推進実施計画ですかね、１つの目標として進めている事業があったと思います。そのモデル事業とは別物なのか、その一環なのかというのを教えていただきたい。","respondent":"渋谷指導課長","answer":"その方を対象にした研修を実施し、また通級指導学級との連絡・連携役を、この特別支援コーディネーターが担っているです。それから２点目の、東京都が特別支援教育推進計画、第３次の実施計画を平成２２年度から進めております。","id":"exchange-011"},{"speaker":"大倉委員","kind":"質問・要望","question":"すいません、確認をさせていただきたいんですが、保育ママで３施設新しく開園するときに、９００万円ということなんですけれども、これは１施設３００万円と考えていいのかを教えてほしいと求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"１施設当たり３００万円です。上限です。","id":"exchange-012"},{"speaker":"大倉委員","kind":"質問・要望","question":"例えば人数とかになるのかというのを教えていただきたいのと、１施設幾らかわからない、安定して保っていけるのかなというところを教えていただきたい。","respondent":"今井制度改革・待機児童対策担当課長","answer":"３００万円の経費というのは広さではございませんで、マンションの一室を借りますので、実際の改修経費のように考えていただければと考えています。保育ママの経費は人数によって、そこの部分は差が出てきておりますけれども、人数に応じて運営費は補助しております。","id":"exchange-013"},{"speaker":"大倉委員","kind":"質問・要望","question":"１点、わかりやすい授業をしていただきたいのと、教材の先生の利用をしっかりと促していく体制があるのかということを教えてほしいと求めました。これを見て、子どもたちの理科の興味というのもなかなか湧いてこないのかなという思いがあったので、ちょっとそこの部分だけ教えていただきたい。","respondent":"和氣学務課長、渋谷指導課長","answer":"教材購入に当たりましては、各学校から希望をとっています。使えるというものをリストの中で選んでいただいて、出しておりますので、基本的には活用していただいていると考えております。理科が好きで得意な小学校教員の指導力、教材開発力を高めていくというコア・サイエンス・ティーチャーの養成講座を実施して、取り組みをしています。","id":"exchange-014"},{"speaker":"高橋委員","kind":"質問・要望","question":"教育委員会ではなくて学校からの要望だというお話だったので、その辺、どういうふうに配慮されて教材を決めているのかということです。何m2とかどうとかというのはあれになりますけれども、その一方で、そういった問題点に対する対処方法についてお答えほしいと求めました。","respondent":"渋谷指導課長、和氣学務課長、今井制度改革・待機児童対策担当課長","answer":"介助員、学習支援員に直接指導ができないという現状がありますので、子どもに対する的確な支援を行う上での非常に重要なポイントだと思っています。… 委員ご心配の点はもちろんありますので、特に校長に対して、継続性をきっちり担保するようなものを買いなさいということでやっています。… 監督を行いますので、月に１度、保育ママとやりとりしながら確認しています。安定的に運営を担保しております。","id":"exchange-015"},{"speaker":"高橋委員","kind":"質問・要望","question":"それが実行に移されているかどうかという検証も、ぜひしっかりとやっていただいて、それを活用してほしいと求めました。その手前の段階で指摘された事項とかを、お尋ねすれば教えていただけるんでしたら、また教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"先ほどいろいろ指摘した点について、しっかり取り組んでいただきたいということを申し添えて、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-02","title":"平成２５年陳情第１４号、国有地などを使って、区立認可保育園の増設を求める陳情","agenda":"平成２５年陳情第１４号、国有地などを使って、区立認可保育園の増設を求める陳情","exchanges":[{"speaker":"南委員","kind":"質問","question":"等々含めて２,０００人以上を受け入れてきたというお話なんですが、改めて区立保育園にしないという、そこのところをもう一度伺いたいと思います。そういう屋上庭園を、屋上を園庭にしている保育園が株式会社では何園あるのか、また屋上についての品川区の見解も伺いたいなと思います。","respondent":"今井制度改革・待機児童対策担当課長、立川保育課長","answer":"２点目の検討の経緯ですが、議員ご案内のとおり、公有地の活用につきましては行財政改革特別委員会でしっかり議論されていると考えております。先ほど１０園と申し上げましたが、社会福祉法人立で屋外遊戯場で活用されているところは８… 平成１４年の国の通知、現在、屋上を園庭として申請しているところは１園もございません。","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"区の内部の検討の中身を教えてくれと、どういう理由でそこに判断したのかを教えてくれと質問しているので、もう一度同じ質問をしたいと思います。ちょっと確認したいんですが、園庭としているところは何園あるのかというのを伺ったつもりなので、そこも改めて教えてほしいと求めました。","respondent":"今井制度改革・待機児童対策担当課長、金子子ども未来事業部長","answer":"区立保育園としてではなく、私どもと企画のほうでそれぞれの提案を持ち寄りまして、内部で検討した結果です。 保育園をかなり数多くつくってきた、数多く支援してきたというのは、先ほど制度改革・待機児童対策担当課長がご説明申し上げたとおりです。ただ… 開設支援に当たりまして、その２園両方とも、１園につきましては屋上の部分も含めて屋外遊戯場として届け出が出されております。","id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"そういうあたりの見解はどうですか、伺いたいと思います。園庭についての保育に対する影響、効果というのは、どういうふうに考えているんですか、質問したいと思います。","respondent":"金子子ども未来事業部長、今井制度改革・待機児童対策担当課長","answer":"で、株式会社が何でもかんでも悪いというような認識は、私どもは持っておりません。こういう立場にありますし、現にそうやっていく考えです。 先ほど保育園を視察されたところで、避難路がないというお話でしたけれども、これは東京都と品川区が開設のときに実地検査して、２方向避難というのは認可の条件ですので、先ほどの発言は訂正していただきたいと思います。","id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"そういうところが、都会ですからやむを得ないと言ってしまえばそれまでですけれども、そこはしっかり押さえてほしいと求めました。先ほど部長の答弁で確認できたので、しかし園庭をきちんと確保できるような指導は、これからしっかりしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"わかりました。どんな説明を何回伺っても、そういういろいろな基準を満たした区立の保育園をつくってほしいという要求は、受けとめていきたいなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"本多委員","kind":"質問・要望","question":"結論を出してほしいと求めました。今の質疑、答弁のやりとりを聞いていて、もう自分の中では考え方がまとまりましたので、区の説明に十分理解できたと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"塚本委員","kind":"質問","question":"今日、結論を出す。これまでの中での実績をきちんと評価すべきだと思うし、どうやって保育園を拡充していくのかという中では、そういう理由です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"大倉委員","kind":"意見","question":"本日、結論を出します。活力を利用して、今あるニーズへの対応というのも大事だと考えていますので、これに関しては不採択をお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"それは本当に私は大事にするべきだと思ってきたし、品川区のかつての保育への接近の仕方、捉え方と。区立認可保育園にしてくださいというところと、この陳情についてはぜひ採択していただきたいし、ぜひ皆さんも採択してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"高橋委員","kind":"質問","question":"今お話を伺っていく中で、量と質の両面から、区としてはでき得る範囲の中で待機児ニーズに応えてきていらっしゃったと思っています。今後この事業に関しても、どのような設立主体であったとしても保育園の運営の中で進めていけると思いますので、この陳情に関しては不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-03","title":"の報告第２５号、専決処分の報告","agenda":"の報告第２５号、専決処分の報告","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"その辺、どういうふうに区としては見ているのかを伺いたいと思います。その辺についてどういうふうに考えているのかを説明を求めました。","respondent":"福島青少年育成課長","answer":"努力があったのかですけれども、前回も説明させていただきましたが、これらの方はかなり長い間、滞納しております。同様に、それでも何らかのことを区としては行っていかざるを得ないだろうと考えているところです。","id":"exchange-028"},{"speaker":"南委員","kind":"質問","question":"そのあたりについての見解を伺いたいんです。これからもっと消費税も増税されるようになったら、もっと大変になると思うので、そのあたりの考え方を伺っておきたいと思います。","respondent":"福島青少年育成課長","answer":"調査権ですとかそういうのがあれば、いろいろあるんでしょうけれども、そういう強制力は持っておりませんので、強制的な調査はできないです。","id":"exchange-029"}]},{"id":"topic-04","title":"図書館電算システムリプレイスにともなうサービスの変更","agenda":"図書館電算システムリプレイスにともなうサービスの変更","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"こういったシステム変更をするときは業者にお願いするんだと思うんですけれども、これは図書館長の範囲内でお願いするレベルのお話、情報システムとかそういうところにこれを持っていって、お願いして何かやるとか、図書館所管の中だけでも済む話なんか尋ねました。","respondent":"中元品川図書館長","answer":"企画部サイドにまず、こういうことでリプレイスを考えているんですがという協議を上げさせていただいて、まず方針決定等をいただくんです。最終的には政策予算要求の作業の中で、区の一定程度の方針をいただくような形になってまいります。","id":"exchange-030"},{"speaker":"南委員","kind":"質問","question":"３割をどう見るかというのはあると思うんですけれども、品川区の図書館のこういうサービスについて評価があるんじゃないかなと思っているんですね。矛盾するというか、そんなふうに受けとめたので、そのあたりの判断をもう一度伺いたいです。","respondent":"中元品川図書館長","answer":"利用登録の変更制度のときにその辺の数字をご報告申し上げて説明したところであると思いますが、図書館としては課題と考えているところです。","id":"exchange-031"},{"speaker":"南委員","kind":"質問","question":"そうすると、そういうサービスができているから、別に品川の図書館を利用しなくても、自分のところでできるじゃないかということなわけですか。そうすると、その辺についての周知というか、ご理解していただくことが大事なんですけれども、そのあたりはどういうふうに展開するんか尋ねました。","respondent":"中元品川図書館長","answer":"行政サービスコーナーであったり、大抵、区外の方はホームページはよくご覧になっていただいているところであると認識しております。現在利用されている方にはチラシを配付したり、窓口でお問い合わせがあれば丁寧にご説明させていただきたいと思います。","id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"それはそれとして伺っておきたいんですけれども、今回がそういうふうになるかどうかがちょっとあれですけれども、そのことを一言言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"沢田副委員長","kind":"質問","question":"ちょっとお伺いしたいんですけれども、品川区に働きに来られている在勤の方の会社の登録をしてもらうとか、そういったことは考えられないですか。そうすれば、会社に対しても言っていけると思いますので、一応、働いている方も区民と考えれば、そういうことも考えられるのかなと思うのですが。","respondent":"中元品川図書館長","answer":"なかなかその辺まで、会社名までということは、お伺いは今していない状況です。本当にその２点だけの、言葉はあれですが、サービスは行わないです。","id":"exchange-034"},{"speaker":"沢田副委員長","kind":"質問・要望","question":"広く、せっかくのこの行政サービスを多くの方に利用してほしいと求めましたので、考えてほしいと求めました。１月９日まで休館ということで、ホームページは１２月３０日から１月９日までということですが、いつからいつまでか尋ねました。","respondent":"中元品川図書館長","answer":"品川図書館と荏原図書館は１２月３０日まで開館いたしますので、１２月３１日から１月９日まで休館となります。それ以外の地区館につきましては、１２月２９日から１月９日までです。","id":"exchange-035"},{"speaker":"沢田副委員長","kind":"意見","question":"１週間以上、期間の考え方というのは、結構長いんじゃないかなと思ったんですけれどもとの意見を述べました。","respondent":"中元品川図書館長","answer":"全てのデータ、皆さんの利用されているデータとかも新しいシステムに移しかえる、セットアップする必要があります。なおかつ、学校図書館とのネットワークも、品川区の場合組んですので、そこのところの動きもきちんと確認するということで、この期間となっています。","id":"exchange-036"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"前回だったでしょうか、子ども・子育て会議の第１回が開かれまして、資料の提供をしていただきたいなと思うんです。ホームページで公開するのであれば、そのときに公開、そのあたりのことをどういうふうに考えていらっしゃるのかを伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"これは全ての会議そうなんですけれども、会議におかけして修正等が出てくる可能性もあります。そのようなご発言等があった場合にも備えて、それも踏まえて、きちんとした資料は残していきたいと考えているところです。","id":"exchange-037"},{"speaker":"南委員","kind":"質問","question":"伺ったことをメモしていくのに、ご発言した内容も含めて、今の説明をもってでも私は納得できないなと思うんですね。修正が出ることがあるので回収だというのであれば、修正した部分をホームページへ掲載するということで不都合なんか尋ねました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"別に紙を持ち込んでいただいて、それに書いていただく分には、私どもはそこはお止めするものではございません。修正につきましては、きちんとしたものを最終的にもう一回事務局で、正副会長に諮りながらアップしていくということでご了承いただきたいと思います。","id":"exchange-038"},{"speaker":"南委員","kind":"質問・要望","question":"部内で検討していただきたいし、説明された中身をそのときに正確に聴取して持ち帰るということは、大事にしていただきたいなと思うんです。ですから、これ以上はしませんけれども、ぜひ検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"南委員","kind":"質問","question":"しかし、ぜひ１ヶ月の停職の期間にいろいろと考えていただければと考えています。ちょっと伺いたいのは、いずれも同じ生徒に対して起こしたと理解していいんでしょうか、それだけ１点。","respondent":"渋谷指導課長","answer":"これはそれぞれ別々の生徒です。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/646567?Template=document&Id=4802#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":44894,"voices":127}},{"id":"h25-20130924-5","meetingId":"h25-cm09","date":"2013年9月24日","dateIso":"2013-09-24","committee":"総務委員会","time":"午前１０時００分～午後 ０時０１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件整理しています。","topics":[{"id":"topic-01","title":"第６０号議案、品川区私債権等の管理に関する条例の一部を改正する条例","agenda":"第６０号議案、品川区私債権等の管理に関する条例の一部を改正する条例","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"今回５％に改正する、根拠ですか、ただ数字はここに確かに出ています。それをわかる範囲でちょっとお聞かせ願えませんか尋ねました。","respondent":"久保田会計管理者","answer":"今回、やっぱり４％ぐらいの差で設けることができますので、そういう点では妥当な利率ではないかなというふうに考えているところであります。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこのところを１点教えていただきたいのと、平成２３年３月ということで、それがなかったときはどうだったのかというところもあわせて説明を求めました。","respondent":"久保田会計管理者","answer":"区にとってみれば、債権のいわゆる事務だけが残っていたというのがあるんですけども、今回私どもの私債権等の管理に関する条例を設置したことで。そういったところで、従来なかった効果が出ているです。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この条例があることで、弁償金のほうは回収が進んでいると、そういう考え方でいいんでしょうか。それと、具体的に対象になるものは、ほとんど生活保護の弁償金のための条例というふうな考え方でいいのか、そこら辺のところを説明を求めました。","respondent":"久保田会計管理者","answer":"幾つかあるんですけども、具体的なものとして挙がってくる例というのは具体的なものがない限り、なかなか説明しにくいところがあります。１件ずつ処理できないということもありますので、新たにシステムを設置して、こういう項目です。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"ごめんなさい、もう一回確認だけ。弁償というふうなところは整理がされていると、そういうことになるのか、その確認だけちょっとお願いします。","respondent":"久保田会計管理者","answer":"延滞金のほうが経済的合理性に欠けるということで、取らないと決定した場合にはすることになります。","id":"exchange-004"},{"speaker":"浅野委員","kind":"質問・要望","question":"先ほど５％の利率というんでしょうか、そういうものがあったら教えていただきたいのと、そういう考え方で正しいのかどうかということについて説明を求めました。","respondent":"久保田会計管理者","answer":"おそらく５％という形で数字を置いたとしても、大きな影響は出てこないだろうというふうな判断をしていただいたということが一つあります。","id":"exchange-005"},{"speaker":"浅野委員","kind":"質問","question":"今、他の自治体を見ながらというようなお話があったんですけども、参考までに、他の自治体は大体といいましょうか、ほとんど５％で、その前後ぐらいなのか、そこら辺の状況がわかれば説明を求めました。","respondent":"久保田会計管理者","answer":"香川県は、県のほうで５％というような採用をしております。それから、岐阜県の多治見市、福井県のあわら市などという例はあります。","id":"exchange-006"},{"speaker":"浅野委員","kind":"質問","question":"今、香川県と多治見市と言われたんですけど、区部のほうですね、２３区、もしまだそういう意味では条例がこういう形で決まっていないというところもあるかもしれませんけれども、そういう中で、状況ですか、そういうものがもしわかれば、近場で説明を求めました。","respondent":"久保田会計管理者","answer":"ほかの区については、今回の税制改正で検討中のところもあれば、全く考えていないということで、まちまちです。ちょっとどういうふうになるかというのは、全体的にはまだはっきりしていない状況です。","id":"exchange-007"},{"speaker":"浅野委員","kind":"質問","question":"延滞金ですか、切ってもいいのかなという気がどうしてもしてしまうんですけれども、そういう意味も私はあるかなと思うんですね。２３区の中である程度連携をしながら、この点、いかがでしょう。","respondent":"久保田会計管理者","answer":"すみません、ちょっと説明が足りなかったと思います。検討している区とそうじゃない区があるということで、大体延滞金については、どこの区もそれは課すという考え方に基づいています。","id":"exchange-008"}]},{"id":"topic-02","title":"第６１号議案、職員の給与に関する条例の一部を改正する条例","agenda":"第６１号議案、職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"一つだけお伺いします。いろいろ今災害も含めて、インフルエンザはちょっと違うんだけれども、そうやってどんどん来るのかということだけ教えていただきたい。","respondent":"堀越人事課長","answer":"東日本大震災を受けまして、それぞれ特別立法で対応していたようなもの、例えば内閣におけます対策本部の設置ですとか。第２回定例会、第３回定例会という形で連続いたしましたけれども、できるだけ即時に区として対応するために今回条例改正をお願いしているものです。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"東北地方に例えば品川区から派遣されているとか、そういう実例というか実態というのはあるのかどうか、そのことだけちょっと。復興計画作成のためにとの意見を述べました。","respondent":"堀越人事課長","answer":"それから、福島県の富岡町にも１名職員を派遣しております。これについて、柔軟な対応をしてという形で職員がしっかりと働いてもらえるようにというふうな形で運用を考えておりまして、そういう状況にあります。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、今行かれている方は、災害対策基本法に基づいて行っているけれども、これが通ったところで、ある一定のところからは、こちらの法律に基づいて手当が出されると、そういう形になってくるという、現状としてはそんな感じなんか尋ねました。","respondent":"堀越人事課長","answer":"繰り返しになりますけど、国のほうから交付金が支給されておりますので、そのような形になるかと思います。この法律は、今後長期化するに当たっての枠組みを定めた法律というふうに理解をしています。","id":"exchange-011"}]},{"id":"topic-03","title":"第６２号議案、品川区特別区税条例の一部を改正する条例","agenda":"第６２号議案、品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"ここだけは、品川区の税収は上がるような気がしてならないので、そういう考え方を持っていらっしゃるかどうか。そういうことは可能だと思うので、この部分は、そこら辺の考え方だけ説明を求めました。","respondent":"高森税務課長","answer":"品川区は第二のふるさとだからというふうにしていただければ、区としては、歳入としては広がるという形になると思います。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そもそも罰則部分が７.３％という根拠はどこから来ているものなのか、これは崩れないものなのかということを一つ教えていただきたいのが１点です。それとあと、そういう延滞金を取らなくていいというふうな規定で決められているのかどうなのか、そこら辺のところも説明を求めました。","respondent":"高森税務課長","answer":"先ほど申し上げましたように、私どものほうもこれを糧に早期納付を促すような形で対応していきたいというところで考えているところです。２点目については、払えないということであれば、ご相談に来ていただいた上で柔軟な対応をしているというのが実情です。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"続けて４番なんですけど、つくりやすくするための、そういうところでつくられた税制という考え方なんでしょうか。今後、この適用になりそうなものというものが、どんなものがあるのかということがわかったら説明を求めました。","respondent":"高森税務課長","answer":"これは国のほうの考え方で、そこが５％になればなりますし、そういうふうな状況だということでご理解をいただきたいというふうに思います。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"例えば認可保育園とか一般的な幼稚園というのは含まれないということなんでしょうか、そのことを１点お聞かせください。７番なんですけど、徴収の仕組みとかなんかがすごく難しくてわかりにくいので教えていただきたいんですけど、それはどういうことかということと。","respondent":"高森税務課長","answer":"例えば６万円だった予定が３万６,０００円になったときは、年税額が３万６,０００円ですから、１０月以降の本徴収額は１万４,０００円になります。前にもご説明したかと思いますけども、１０月以降については３回払いというふうな、ご説明するとそういう制度で回っていくです。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１月１日に品川区に在住していた方は、６月に通知をして翌年の５月までは品川区に納めると、ちょっとそこの点をお願いします。","respondent":"高森税務課長","answer":"委員おっしゃるとおりです。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"８番なんですけど、これも平成２９年１月１日というのがなぜなのかということを一つお聞かせいただきたいのと、社債ということですよね。そこら辺のところがどういうふうに変わるのかというのをちょっと詳しく説明をお願いします。","respondent":"高森税務課長","answer":"なぜ平成２９年からかということについては、すみません、ちょっと資料がございません。３％とった中でそれを今度６と４に区と都の分ということで、翌年配分というか、配当されるような状況になるです。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"東京都が源泉徴収でとったものの６割を区に利子割交付金という形で入れるという仕組みになっていたと思うんですけど、公社債も上場株もあわせて損益通算ができると、そういう仕組みに変わるということでいいんか尋ねました。","respondent":"高森税務課長","answer":"委員おっしゃるとおり、全部ひっくるめた形で損益通算ができるという考え方でよろしいわけです。先ほど都民税のほうの話ですけども、平成２８年１月１日以降、所得割の課税対象とするという形になってあります。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今まで品川区には公社債の利子割交付金というのはどれぐらい入ってきていたのか、そして、それが今度なくなるわけですよね。品川区に対しての税金はどういう形で入ってくることになるのか、そこら辺の見通しというか、そこら辺のところはどうなるのかということもあわせてとの意見を述べました。","respondent":"高森税務課長","answer":"平成２５年度の予算では、平成２５年度株式等譲渡所得割交付金は、４,０００万円の予算を組んでいるところです。申告して、当初３％抜いていましたけど、住民税として納めていただいたものについては全てお返しするという形の手続をそこで行う形になります。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ちょっとよくわからないんですけど、そうすると、利子割交付金というのは、今までどおり入ってくるということなんか尋ねました。","respondent":"高森税務課長","answer":"それは税計算をしてみないと、区の収入になるのか、お返しするお金になるのか。５月３１日に出納閉鎖しますので、６月１日以降にそれが判明した場合は、ほかの出口から歳出として過誤納還付金として還付が発生すれば出す。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"わかりました。損益というんですかね、今のところは３年まで損益計算ができると、そういう仕組みということで捉えていいんか尋ねました。","respondent":"高森税務課長","answer":"委員おっしゃるとおり、そこの部分については３年ということで、それ以上のことは聞いてございません。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"賛成なんですけど、ちょっと８番の金融・証券税制の改正というところについて、欧米諸国ではないという状況なんですよね。この８番については拡大すべきではないというふうに思っているんですが、全体を見たときには、この条例には賛成ということにしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"}]},{"id":"topic-04","title":"平成２５年請願第１０号および(2)平成２５年請願第１１号、固定資産税及び都市計画税の軽減措置の継続","agenda":"平成２５年請願第１０号および(2)平成２５年請願第１１号、固定資産税及び都市計画税の軽減措置の継続","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"平成２６年度からどういうふうに変わるかというのを、それは継続してもらうのは当たり前であって、恒久減税みたいなところはどうするか。ここら辺の、つかんでいる情報があれば、ぜひ教えてほしい。","respondent":"高森税務課長","answer":"過日、税務課長会がありまして、成果等も入ってきていたんですけども、この件に関しての情報というのは、申しわけございません、入ってございません。","id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"恒久減税にしてほしいなんていう動きもずっとかけてきたわけでありますけれども、やはり継続してほしいという部分が非常に強い要望でもあるし、ぜひこれは取り上げていただきたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今年は６,４００件で、桁が１桁違うんですけど、ちょっとそこのところを聞かせてくださいとの意見を述べました。","respondent":"高森税務課長","answer":"委員おっしゃるとおり、平成２４年度のが誤りです。申しわけございませんでした。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それであれば、ぜひ議事録のほうも訂正をしていただくように、よろしくお願いします。もう一つちょっとお聞きしたいのが、ここまでの減額ということを求めてもいいのかなという思いがするんですけど、その点はいかがか尋ねました。","respondent":"高森税務課長","answer":"ずっとご意見もあるかと思うんですけど、現行では６５％ということになっています。財政調整交付金等で各区のほうに配分されている財源になってありますので６０％、何とも言いようがないというのが実情です。","id":"exchange-026"},{"speaker":"浅野委員","kind":"質問・要望","question":"具体的に回答ですか、それを一つ教えていただきたいのと、そういう資料とかがあれば教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"浅野委員","kind":"意見","question":"それが単年度でということは、どういう形で、結果として来ているのかなと。これが、「あなたと都税」に書かれているので初めてわかるのか、その前に何らかのあれが来るのかどうかとの意見を述べました。","respondent":"高森税務課長","answer":"本日お配りしました「あなたと都税」の抜粋で、品川区の分の対象の部分については、これは別途、東京都主税局税制部のほうにお尋ねをしていまして、照会をして、品川区の分として数字をいただいて、本日皆さんのほうに配付させていただいているという状況になっております。","id":"exchange-028"},{"speaker":"浅野委員","kind":"質問","question":"そうすると、都のほうの議決があって、これで決定ということで、今言われた件数とかそういうものを全部調べて手を打っていくと、そういうような手続になっているということでよろしいか尋ねました。","respondent":"高森税務課長","answer":"これも実は平成２４年度の速報値でございまして、３月までの数字をやっと最近もらったという状況になっています。そういう意味で、委員おっしゃるとおりです。","id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今税制調査会、自民党で始まったところもありまして、我々も税制調査会の償却資産税の軽減措置も継続してくれという話は直接的に要望してきました。やっぱり、小規模事業者を助けるためにも、これを継続していくということは必要だと考えていますので採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"いながわ委員","kind":"質問","question":"毎年出されている請願です。内容については１年１年ということですけど、恒久的な減税というんですかね、措置を願いつつも、今回採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"須貝委員","kind":"質問・要望","question":"区議会としても都のほうに要望するのは、そういう事業者に対して、やはり恒久減税という形で私は進んでいくべきものだと思います。それだけ述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"}]},{"id":"topic-05","title":"平成２５年請願第１３号、消費税増税中止を国に求める請願","agenda":"平成２５年請願第１３号、消費税増税中止を国に求める請願","exchanges":[{"speaker":"石田（秀）委員","kind":"意見","question":"やはり消費税だろうということをお考えになって、公明党とも話をして、民主党政権のときにこれができた。安倍首相の判断はどうなるかわかりませんが、我々としてはまず考えられないことでありますし、上げる必要もないと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"浅野委員","kind":"意見","question":"その財源はどうするかという大きな問題に突き当たったときに、公明党としてもこれについては賛成という形をとらせていただいております。この請願に関しましては、採択できないというふうに考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"いながわ委員","kind":"意見","question":"消費税、国のほうで今議論されておりますが、まだ民主党政権だったときに、そういう発信がありました。やはり必要性があるのではないかと思いますので、この請願に関しては、意見書を上げないということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"須貝委員","kind":"質問","question":"子育てという社会保障ですか、孫、これからの世代に対して現世代の大きなこれだけの負担をやっぱり引き継がせては私はいけないと思います。だから、今回の意見書については、反対します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"法人税を減税するとか、そういうところで大企業に５兆円減税とか、さまざまな施策をとっていくというところを景気対策として求めていますよね。社会保障を解体するんじゃないかと、思われるぐらいの社会保障については自己責任を求める、そういう社会保障の中身に大もとの基本理念を変えました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"石田（秀）委員","kind":"意見","question":"１０月にも安倍首相がと先ほど言いましたけれども、先ほど来言いましたように、これは民主党政権でもマニフェストになかった。我々としては、それはやっぱり今の話は受け入れられないということで、我々はちゃんとしっかりこれについては不採択で対応していくということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"須貝委員","kind":"意見","question":"じゃあ、なぜ賃上げができないんだ。意見だけ述べしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"浅野委員","kind":"質問","question":"国の借金ですか、皆さん言われているとおり次世代のツケとなってしまうだけことですので、それについては減らしていかなければならない。そういう意味では、この請願については受け入れることができないということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、内需を拡大することが１億３,０００万人ですからね、私は企業も海外から戻ってくるというふうなことにもつながっていくと思うんですね。７割から８割は来年４月から増税すべきじゃないと、そういう世論調査まで、議会の中で納得いくような議論をぜひしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/904361?Template=document&Id=1960#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":36300,"voices":131}},{"id":"h25-20130925-6","meetingId":"h25-cm09","date":"2013年9月25日","dateIso":"2013-09-25","committee":"区民委員会","time":"午前１０時００分～午後 １時３７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件整理しています。","topics":[{"id":"topic-01","title":"高齢者の消費者被害防止に向けた地域での見守り","agenda":"高齢者の消費者被害防止に向けた地域での見守り","exchanges":[{"speaker":"石田（し）委員","kind":"質問","question":"なのですが、最後のページを見ていただくと、５つ電話番号が書いてあるのです。５個の電話番号が載っていたら、５個電話番号が書いてあったら、その点どんなふうにお考えなのか説明を求めました。","respondent":"米田商業・観光課長","answer":"この辺のところは、わかりやすさについてはまた改めて検討してまいりたいと思いますが。そのような中でも、まず品川区の消費者センターですよということを改めて対面の中ではお話をしてまいりたいと考えています。","id":"exchange-001"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"もう少し、例えば１つの番号は大きく書いて、とりあえずここに電話してくださいと。これは要望で終わりますが、ぜひそういった工夫も考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"吉田委員","kind":"意見","question":"誰かに聞こうにも、どうしましょうというときに、時間帯はまちまち。それで被害に遭うこともあるのではないかと思うので、その辺の対処の仕方、時間外をもう一度詳しくお話いただけますかとの意見を述べました。","respondent":"米田商業・観光課長","answer":"これは本当に、刑事事件等になるようであるならば１１０番になるのですけれども、なかなかそういう立件も非常に難しいと思います。お話をしている中でお時間が若干超過したような場合でも、今のところこの営業時間帯でご連絡をお受けしているというような形で考えてあります。","id":"exchange-003"},{"speaker":"吉田委員","kind":"確認","question":"ということは、時間外に緊急というか、ご相談したいときは１１０番ということですか。その辺を確認したいのですけれども。","respondent":"米田商業・観光課長","answer":"すぐ立件する必要がある、駆けつける必要があるということがあれば１１０番でも対応していただけると思いますが。２４時間対応ができればベストかもしれませんが、今のところこのような形で対応しているものです。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"ご相談するのはなかなか難しいというのはわかるのですが、そうすると、地域の民生委員の方々がいらっしゃいますね。そういう方のご協力というのはどのような、時間外等は、要するにお近くの方とかの連携とか、その辺、最後にお聞きしたいのですけれども。","respondent":"米田商業・観光課長","answer":"まず行政の職員等も含めて緊急対応が必要か否か、想定の時間に相談へつなげるということは、またかけ直していただくこともあるかもしれませんが。そのような形で時間外にできるだけ広範囲に対応していきたいと考えています。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問・要望","question":"今の前向きなご答弁いただいたのですけれども、時間外に対応できるようなお考えもこれから広げていただいて、いつこういうことがあるかわからないし、なるべく１件でも減らしたいという思いでありますので、そういう意味でも、要望ですけれどもお考えほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"取り組みの周知だったりを伺いたいと思うのですけれども、もちろん地区民生委員協議会を通じて呼びかけるというのもとても大事だと思います。こういうパンフレットを渡す、高齢者福祉課など、ほかとの連携とその具体化をどんなふうにお考えなのか伺いたいと思います。","respondent":"米田商業・観光課長","answer":"１年経つとまた新手の被害、周りにそんな方がいませんかということを改めて認識していただくということで、これは例年の取り組みです。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"悪質商法に引っかかってしまってどうしよう、どうしようという相談は度々あるのですけれども、ご近所にもなかなか持てない。ぜひそうしたところでの取り組みを強めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"山元委員","kind":"質問","question":"今いろいろご質問があったのですけれども、もちろんそれもそうなのですけれども、今もありました。プレッシャーがあるかという気がするのですけれども、そういうものがあったらいいのかと思うのですが、その辺はいかがか尋ねました。","respondent":"米田商業・観光課長","answer":"そういった中で、詳しくは存じ上げておりませんが、そこにご自身の電話番号をお書きになるということはされているのかもしれないなと考えています。出向いていったところでのご意見等を踏まえながら対応してまいりたいと考えていますが、広く全体的に、民生委員以外の方々にも。","id":"exchange-009"},{"speaker":"山元委員","kind":"質問","question":"そうですか、すみません、私の認識不足で。ターゲットになっているのではないかと思いますので、その辺もぜひ考えていただければと思っていますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"僕もてっきり配るものだと思ったのです。「あっ」、ぜひいろいろお配りするなど活用していただきたいと思うのですけれども、そんなにだめなものなのか尋ねました。","respondent":"米田商業・観光課長","answer":"ただ、それ以外に関係機関ということでそれぞれの組織があり、見守りというようなことを考えております。他の部署との連携をとりまして、効果的なものがあるかというようなことについてはまた改めて考えてまいりたいと、このように考えております。","id":"exchange-011"}]},{"id":"topic-02","title":"のプレミアム付区内共通商品券発行事業への助成","agenda":"のプレミアム付区内共通商品券発行事業への助成","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"要するに事業として位置づけ直して、ぜひ商店街を応援していただきたいと思うのですけれども、それはいかがかということです。欠かせないものだと、商店街応援の事業として位置づけてか恒久策としてやっていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"米田商業・観光課長","answer":"平成２１年度から春、秋ということで、金額の違いはあれど継続しているという状況にあります。経済政策等いろいろ今実施されて期待感はあるという中でも厳しい状況はあるということもお伺いしておりますので、今年度は実施いたしまして。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"伺いたいのはどの指標でこれをやります、もうやめますと、どの指標で区は判断するのですか。そこを見ていくべきだと思うし、そこを見るならば来年のことは来年考えるのではなくて、いかがか尋ねました。","respondent":"米田商業・観光課長","answer":"プレミアム付区内共通商品券発行事業についても検討を重ねているところです。その指標がある程度達成できたから、品川区としても来年度こちらの事業を実施するか否かについてはまた重ねて検討してまいりたいと思ってあります。","id":"exchange-013"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"昨日の補正予算で消費者展の広告、宣伝ですね、その費用で約５００万円、バスと電車で５００万円。即日完売の勢いで販売されている中で、１,０００万円近いお金をつぎ込んで促進を促す必要があるのかどうか、その点を説明を求めました。","respondent":"米田商業・観光課長","answer":"今ご指摘もありましたようにある程度早く売れるという状況もある関係で、一定の見直しをして減額を図っていったということもあります。現状、商店街連合会が行っておりますＰＲの状況を踏まえまして、予算の計上を行ってまいりたいと考えています。","id":"exchange-014"}]},{"id":"topic-03","title":"の２「所管事務調査」","agenda":"の２「所管事務調査」","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"もう少しご説明いただきたいと思うのですけれども、具体的にどういうことに今、問題意識を持っていらっしゃるのかご説明ほしいと求めました。(2)ですけれども「新たな事業展開の可能性を検討する」とありますけれども、違うのか、そこを補足的にご説明いただけますか尋ねました。","respondent":"寺嶋協働・国際担当課長","answer":"内容のところをもう少し検討、検証しまして、より効果的な事業に進めていきたいという趣旨です。今後もその部分については継続していくものと考えておりますけれども、区内でも国際関係、国際交流という視点で活動している団体がたくさんおります。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"今のご説明は人数や派遣のターゲット、内容を検討するという方向がよくわからなかったので、もう一度ご説明いただけますでしょうか。変えようとしているのか、方向がよくわからないので、繰り返しですけれどももう少しご説明いただけますか尋ねました。","respondent":"寺嶋協働・国際担当課長","answer":"例えば交流につきましてもどういったことがもっともっと望まれていくのかということについては、まだまだ十分検討していく余地がある。それに向けて品川区としても受入態勢をしっかり組んでいくということは当然行政の責務として、これからの国際交流を考えております。","id":"exchange-016"},{"speaker":"石田（し）委員","kind":"意見","question":"今後は在住外国人以外にも観光される外国人の方とも積極的な交流と記されているのですが、具体的にどのような交流を区として考えているのか。","respondent":"寺嶋協働・国際担当課長","answer":"まだ検討段階で、今後品川区の事業に参加していきたいかみたいな話で、かなり積極的な反応が返ってきているというような情報も聞いております。","id":"exchange-017"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"でも、日本人は日本語で話かけないではないですか。学校教育もそうですけれども、その辺をぜひ区としても考えていただきたいと思うのですが、その辺の真意で何かお答えいただければ。","respondent":"寺嶋協働・国際担当課長","answer":"先ほどの派遣を経験した生徒の話と重複する部分もあるのですけれども、初日はしゃべれなかったけれども２日目はしゃべられるようになった。どういう接点を最初につくればいいかというあたりも含めまして、十分に研究していきたいと思います。","id":"exchange-018"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"文化を知るという部分もぜひ交流のところには加えてほしいと求めましたので、これは要望でありますけれども、よろしくお願いいたします。それと、１４の団体が記載されているのですが、実際にこの１４団体というのは品川区と何らかの接点があるという認識でよろしいか尋ねました。","respondent":"寺嶋協働・国際担当課長","answer":"ただ、品川区で実施している地域国際交流懇談会という事業がありまして、毎年国際関係に関する懇談会というのを実施して。そういった意味では区と連携を図ったり、情報交換ができる団体というのはこの表に書いていない団体も含めまして多数あると認識しております。","id":"exchange-019"},{"speaker":"石田（し）委員","kind":"質問","question":"大使館だったらどちらかというと区のほうのパイプがあったり、団体によって区が持つパイプと国際友好協会が持つパイプは違うと思うのです。そこだけ最後に説明を求めました。","respondent":"寺嶋協働・国際担当課長","answer":"国際友好協会とその他の団体との連携という意味では、一緒に意見交換をして、友好協会と直に団体とが情報交換をすることも常に進めております。品川区のほうもその場に当然かかわっておりますけれども、そういった細かな実務的な話は直にやっているということも聞いております。","id":"exchange-020"},{"speaker":"山元委員","kind":"質問・要望","question":"仮に私の家になったときにうちの家に来られたらどうしようという。どうしてそういうふうになってしまったのか、その状況がわかれば教えていただきたいし、その辺をお聞きしたいと思うのですけれども。","respondent":"寺嶋協働・国際担当課長","answer":"もしうちが条件的に可能なら受けてみようかというふうに検討してくださるご家庭もあるという情報も、ぜひ広げていきたいとは考えております。現在はそんな状況です。","id":"exchange-021"},{"speaker":"山元委員","kind":"質問・要望","question":"そういうおうちの方に謝礼とか、そういうのはあるのかというのと、あくまでもボランティアとしてお気持ちなのかを教えていただきたいということです。７年後を毎年実施するわけですから、定員をもう少し広げる予定はあるのかどうか、その辺も教えていただければ。","respondent":"寺嶋協働・国際担当課長","answer":"それが１点目。それからどこまで行政として支援したほうがいいのか、すべきなのかというあたりでバランスを考えながら、十分研究していきたいと思います。","id":"exchange-022"},{"speaker":"山元委員","kind":"質問","question":"「どうしたんですか」と声をかけてあげることは大事なのですけれども、日本語でいいと思うのです、「どうしましたか」ではないけれども。そういう人たちの事業というか、声をかけて日本のいいところをみんなでしましょうみたいな事業を考えていらっしゃるとか、予定はありますか。","respondent":"寺嶋協働・国際担当課長","answer":"ただいまのご質問につきましては、庁内で検討会議を立ち上げまして、十分に検討していきたいということで、いわゆる都市像でいうところのにぎわい都市と、安全・安心都市の両立も含めまして、十分に研究していきたいと思います。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"確認","question":"改めてお聞きしたかったのですけれども、姉妹都市、友好都市の対象になる区民の方、学生が対象ととってしまっていいのかという、そこの確認。","respondent":"寺嶋協働・国際担当課長","answer":"これは例えばポートランド市と最初に協定を交わしたときの内容からいきますと、区民、市民という表現になっておりますので、学生ではなくて一般の区民、あちらの市民の方の全てが対象です。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"そこら辺の流れを教えていただきたい。この辺を含めてお聞かせいただきたい。","respondent":"寺嶋協働・国際担当課長","answer":"決して学生に特化したというふうに方向転換したわけではございませんので、改めてそういった状況も踏まえまして事業を検討していきたいと思います。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"意見","question":"そこのつながりを少し活かせれば、学生の派遣なのかどうかわからないけれども、区として区民と向こうの市民との交流みたいな形ができれば望ましい。","respondent":"寺嶋協働・国際担当課長","answer":"友好都市、交流は続けていくけれども、より特定分野に特化したお互いにメリットのある交流をしていきたいといった声も出ております。世の中の風潮もそういうふうに流れているところは重々認識しておりますので。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"もう一つ、向こうはシャットアウトしているのかどうかは別にしても、品川区の方も積極的に入れるような形につくれないのかと。そういう感覚的なものを身近にできるところがあれば、つくっていただきたいという希望がありますけれども、その辺もお答えいただければ。","respondent":"寺嶋協働・国際担当課長","answer":"その内容につきまして若干ご説明しますと、日本に住んでいるタイの方などが集まって普通のお祭りとして実施しているということです。」ということにもなるといけないので、一つ何かの形でお知らせができるような方法があれば検討していきたいと考えています。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それからルートも、そういう軽い交流からでもスタートできればと思いますので、ぜひ検討していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"向副委員長","kind":"確認","question":"大使館との交流で１点だけ確認させていただければと思うのですけれども、大仏展とか、美術館の内覧会とかが定期的にあるではないですか。そういう点での交流というのは、品川区にあるものを大使館の方とか、領事館の方にアピールしようという交流は今あるのか尋ねました。","respondent":"寺嶋協働・国際担当課長","answer":"平成２１年から平成２４年までは継続してやって、今年度も予定としては、先方の都合がつけば予定しているのですけれども。もっともっと大使館とのパイプは強めていきたいという思いはありますので、そういった形がとれるように勉強していきたいと思います。","id":"exchange-029"},{"speaker":"向副委員長","kind":"意見","question":"今日はこれで終わるのですが、結構目が肥えている方というのは多分多いと思うのです。１時間、２時間夕方に時間を設けるとか、またとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"意見","question":"そういうお子様、通訳での交流、区の検討会議の中にもその辺を入れてということを言っていくことはできないかというのはちょっと感じております。姉妹都市、その辺はしっかりと議会も声を出していきたいと思いますので、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"何かあったときに、日本で何かあっても向こうでは何もないですから、災害というのは。さまざまな視点で国際交流をどんどん、小学生、中学生も含めた国際交流をやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"中塚委員","kind":"意見","question":"最近ではヘッドスピーチなどの問題もありますけれども、やはり違いを差別に発展させない力を培っていく。オリンピックも、五輪憲章のシンボルマークもそうですけれども、そういうところにこそ国際友好の発展の方向が多少あるのではないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"吉田委員","kind":"意見","question":"２０２０年の五輪もありますけれども、それにちょうど今盛り上がっていくところ、いつやるのというところがあるのではないかと思います。学校のことも出ましたけれども、高齢者の方もそうですが、そういう意味で周知していくのが一番大切なのではないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"国際交流の事業はどういう目的ですかというのが書いてあると思うのですが、両国の発展、世界平和の繁栄などと書いてあるわけです。だから、大きなテーマだと思うので、区としてできる国際友好というのを改めて考えるとどうなのかと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"山元委員","kind":"質問・要望","question":"そういう意味では今ここにある大使館とかいろいろありますけれども、そことの交流が大事かと思います。そんな感じにしていただきたいと思うのと同時に、ぜひ７年後には、オリンピックを味わっていただければいいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"向副委員長","kind":"意見","question":"国際交流については３０年の歴史という中で、方向性、そちらを見ていけたらいいかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"}]},{"id":"topic-04","title":"では行政視察についてなのですが、本件につきましては地域振興事業部長のみお残りいただく予定でございますので、先に予定表上、４のその他を議題に供します。 初めに…","agenda":"では行政視察についてなのですが、本件につきましては地域振興事業部長のみお残りいただく予定でございますので、先に予定表上、４のその他を議題に供します。 初めに…","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"商店街にどういった状況があるのかということと、どういった中身の検討を現状考えていらっしゃるのか、ご説明ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そこら辺を区としてどう考えていくのかというのが、どうしても課題になってくると思うのでそこら辺につきましてお聞きしたいと思っています。あそこは足がない場所になると思うので、現場の人は車で来るかどうかわからないですけれども、考え方を教えてほしいと求めました。","respondent":"米田商業・観光課長、安藤文化スポーツ振興課長","answer":"店舗の取り組み、冊子の中で細かく、地域の店舗ということで紹介をしてまいる予定です。どのような対応が可能であるかということを考えているということですので、今後も引続き設置者側に働きかけてまいりたいと考えているところです。私からは、２０２０年東京オリンピック・パラリンピックにつきましてご説明させていただきたいと思います。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問","question":"そういう現状についてはどうこれから解決していこうとお考えなのか、そこを１点伺いたいと思います。八潮に住んでいる方にとっては生活に欠かせないお店ですから、何かそういうのがないのかとも思うのですけれども、そこを伺いたいと思います。","respondent":"米田商業・観光課長","answer":"いわゆる八潮地区内においては店舗がほとんどないという状況はこちらとしても認識しておりまして、こちらとしても十分認識はしています。","id":"exchange-040"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"先に、買い物支援のところで確認ですけれども、これは地域振興事業部ではないかもしれないですけれども、配食関係を商店街でやりましたね。違う部署なので答えにくいかもしれないですけれども、そこら辺を１点、もう一回確認させてください。","respondent":"米田商業・観光課長、安藤文化スポーツ振興課長","answer":"十分福祉部門の買い物支援の方策とも、本会議でもご答弁申し上げましたように、十分連携させながら今後考えてまいりたいと思ってあります。適時適切に、また地域の方への情報提供にも努めするということは… それから、また野球場ですが、今、大井ふ頭中央海浜公園については野球場は６面あると認識しています。ただ、そこら辺を見きわめながら野球場の代替施設も東京都に働きかけていきたいと考えています。","id":"exchange-041"},{"speaker":"山元委員","kind":"質問・要望","question":"もしくはポスティングでもいいですけれども、チラシでダイエーが１月閉店とかいう、それを見てみんな慌てている人もいるわけです。ダイエーなのか新都市ライフなのかちょっとあれですけれども、状況をお知らせするような動作をぜひともしていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"}]},{"id":"topic-05","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"渡辺委員長","kind":"質問・要望","question":"その辺も現地で、あと国体も近年で開催されたので、どうつなげているのかというのを当日伺ってみようと思っています。皆様のほうで何かありますか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"中塚委員","kind":"意見","question":"実際震災から２年以上たっているから、何らかの取り組みも始まっているのかもしれない。一緒に楽しむとか、まだ２年しかたっていませんから復興といっても長い話ではあるけれども、その取り組みの一端でも聞くことができたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"山元委員","kind":"質問","question":"それをどういうふうにお誘いというのか、うまくいった例などを教えていただいて、そんなことも聞いてみたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/398926?Template=document&Id=2678#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":54336,"voices":116}},{"id":"h25-20130925-7","meetingId":"h25-cm09","date":"2013年9月25日","dateIso":"2013-09-25","committee":"厚生委員会","time":"午前１０時００分～午後 １時３８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件整理しています。","topics":[{"id":"topic-01","title":"はじめに、(1)の杜松小学校跡高齢者福祉施設等の工事","agenda":"はじめに、(1)の杜松小学校跡高齢者福祉施設等の工事","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"どのぐらいの応札があって、業者が落札できたのかというのがまず一つ、お伺いさせていただきたい。品川区で仕事をしたことが実際にあるのかどうか、その辺、もしわかれば教えていただきたい。","respondent":"永尾高齢者福祉課長","answer":"９月２０日に入札を行いまして、最初５者から応札が来ましたけれども、１者は辞退をされております。この決定した業者につきましては、実績もあるというふうに認識しています。","id":"exchange-001"},{"speaker":"渡部委員","kind":"質問・要望","question":"では、これは無事に決着したということで、今後順調に進めていただいて、しっかりとした品質の高いもので、これから区民の皆さんにとって利益のあるものになるように、これは要望で終わりますので、しっかり納期どおりいくように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"たけうち委員","kind":"質問・要望","question":"確認なんですが、屋内運動場は特に手を加えずにそのまま、ということかということが１点。それから、プールがあるんですけれども、これはどうするのか、もし所管が違っていたら、わかれば教えていただきたい。","respondent":"永尾高齢者福祉課長","answer":"屋内運動場については、手を加えないということで、工事のときの資材を置いたりとか、事務所がわりに使うということを想定しています。プールは取り払うことになっております。","id":"exchange-003"},{"speaker":"井上委員","kind":"確認","question":"４番目の小規模多機能型居宅介護というのは、小規模多機能型居宅介護というのは、どういう意味なのか。地域交流拠点というところは、どのようなものをイメージしているのか、ちょっとその辺の内容について、もう一度確認をさせてください。","respondent":"永尾高齢者福祉課長","answer":"多目的室だとか、介護予防拠点だとか、スタジオとかを設置の予定になっております。この運営の仕方については、地域の方の話し合いの中で詳細は詰まっていく予定になっております。","id":"exchange-004"},{"speaker":"井上委員","kind":"質問","question":"４番目の小規模多機能型居宅介護のところは、小規模多機能型施設というふうに、今の説明だとそうなるんですけれども、そういうところのユニットをつくっていくという意味か尋ねました。","respondent":"永尾高齢者福祉課長","answer":"その一つには、堀りごたつを設置しておりまして、そこで皆さんも集いながらくつろげるようなイメージになっております。居室１から４については、そこで泊まりをすることが可能という想定をしています。","id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"地域密着型特別養護老人ホームということで、小規模であるということだけで、地域密着型ということは、利用者は品川区内ということでいいのか。この場合は、地域密着型ということは、品川区が認定する施設になるということで理解をしていいのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"品川区立で、指定管理者が設置という形をとっていますので、こちらに関しても同じような形態をとる予定です。これまで区のほうで実施している小規模多機能と特別養護老人ホームと同じ形態をとりますので、区民にご利用いただくということを考えております。","id":"exchange-006"}]},{"id":"topic-02","title":"の後期高齢者医療制度保険料","agenda":"の後期高齢者医療制度保険料","exchanges":[{"speaker":"井上委員","kind":"意見","question":"２枚目も１枚目もそうなんですけれども、医療給付費の自然増の２.５％の根拠を、もうちょっと詳しくお願いしたいと思いますとの意見を述べました。","respondent":"間部国保医療年金課長","answer":"例えば１ページ目のところで見ますと、前年度比増減というところで、計画と実績のパーセントが載ってあります。平成２４・２５年度については８.２％増となっておりまして、平成２５年度に入ってからの増も含めて、２.５％と見積もっているものです。","id":"exchange-007"},{"speaker":"井上委員","kind":"質問","question":"２の検討案の決定条件の中で、(3)で、東京都が所得係数が１.７２０と、これは平均なので、それによって随分と差があるんですね。という数なのか、もっと極端に違う層の方たちがどれぐらいいるのかとか、そういった分析はどうなっているんか尋ねました。","respondent":"間部国保医療年金課長","answer":"所得係数のお尋ねですが、委員ご存じかと思いますが、後期高齢者医療制度につきましては、都道府県で一つ、４７の保険者で運営しておりまして、申しわけないんですが、品川区の状況については、ほぼ東京都と同様ということで認識をしています。","id":"exchange-008"},{"speaker":"井上委員","kind":"質問","question":"それから収納率９８％というふうにしている中で、可能な限り分析をする必要があるのではないかということで、これは意見でとどめたいと思います。さっき、私はメリットはないと言い切りましたけれども、品川区が頑張れば、何か品川区にそういったものはないのか尋ねました。","respondent":"間部国保医療年金課長","answer":"やはり後期にも反映すると考えておりますので、その取り組みについては、今後もきちんと推進していきたいと考えております。品川区でも９８％前後なんですが、これがより１００％に近づけば、財政上のメリットは考えられます。","id":"exchange-009"},{"speaker":"たけうち委員","kind":"質問","question":"４７都道府県の中では、一番安いのか、ちょっとその辺の状況を教えてもらいたい。一般財源を投入しない場合と投入する場合と２通り出ているんですけれども、まだそこははっきりしていないのか、その辺の状況を教えてもらえますか。","respondent":"間部国保医療年金課長","answer":"政令どおりで実施した場合、できればこの４項目の軽減対策を継続する方向で考えてほしいということは、広域連合に申し入れをしています。あらゆる手立てをくんで、最後の足らずの部分については致し方ないのかなと、こういうような見解を持っているものです。","id":"exchange-010"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"すごくわかりづらくなってしまっていると思うんですけれども、なぜなのかということ。年金収入額が１６８万円から１７０万円と２万円上がっただけで、一気に３万円上がってしまうという、今現在どういう状況なのか説明を求めました。","respondent":"間部国保医療年金課長","answer":"したがまして、そういうことも含めますと、トータルで考えれば、低所得者対策ということで実施をされていく方向性。いろいろな面で対応ができるのかなと思っていますので、その旨はお伝えいたしますが、制度的にはなかなか難しいところだなと考えております。","id":"exchange-011"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"さらに消費税も増税されて、負担増極まりないところまでいくというところでは、ほんとうに大変な状況になっていくと思うんです。定着してきたとおっしゃっていたんですけれども、どういったところが定着したと思っているのか、ちょっと伺っていいか尋ねました。","respondent":"間部国保医療年金課長","answer":"制度の定着の件ですが、広域連合におきましてはコールセンターを設置していたんですが、そこでは約４万件の問い合わせがございました。これから国において議論されるものと思いますので、今のところは、そういう見解です。","id":"exchange-012"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"こういった上げ幅の軽減だったりとか、私たちは廃止を求めますけれども、そういったところを広域連合にもどんどんと訴えていってほしいと思います。国の方針というのはどういうもので、いつぐらいにこれが確定してくるのかを、説明を求めました。","respondent":"間部国保医療年金課長","answer":"ただ、この件も、ちょうど国が概算要求を締め切るか、締め切らないところなんですけれども、そういう中で徐々に明らかになるということです。例年、大体、秋から冬にかけて数字が提示されるということになっていますので、今後の推移を見守っていきたいと思っています。","id":"exchange-013"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"それから、滞納者数と、短期証になっている方の人数がわかれば、説明を求めました。","respondent":"間部国保医療年金課長","answer":"被保険者が３万５,１０３名のところ、滞納者８８８人ということで、パーセンテージとしては２.５３％の滞納者がいらっしゃいました。短期証につきましては、平成２５年３月末現在ですけれども、４３件発行しています。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問","question":"きのうも、補正の中でご説明があったんですけれども、アウトリーチチームの派遣ということで、これは具体的には、大体いつぐらいから始める予定でいらっしゃるんか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"今、事前の準備を行っておりますので、議会の承認が得られたらすぐに始められるようにしたいと考えております。","id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ヘルパーとかがついてなかったわけですから、家族もまだ理解できていないという中で、それを説明するのは難しい。これは家族がお願いをすれば、使用させていただけるものなのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"これは、申請して利用するとなっておりますので、ケアマネージャー等からの紹介もあるかとは思いますけれども、もしご希望があれば、ご家族のほうから申請をしていただければと思います。","id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問","question":"もう少し詳しい説明を聞きたかったんですけれども、それはやっぱり携帯電話か何かのシステムを利用しているものなのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"３回目以降１０５円とか、利用１回につき１万５００円かかるということ、初期費用が７,３５０円かかるということ。利用者の実数としては、平成２４年度では１１人ということになっております。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問","question":"細かいことを聞いて申しわけないんですけれども、例えば、先ほどの方なんかは、財布も何も持たずにぱっと家を出られてしまったんですが、これは常に身につけておけるような形態のものなのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"高齢者が常にそれを身につけていて、その端末機の反応を見るという形になります。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問","question":"もう１回、細かくて申しわけないんですけれども、ペンダントのような、もしくは手足につけるようなものなんか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"端末機を背中の中に入れることによって、そこで感知をして、おおよその場所を知るということです。","id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問","question":"先ほど、認知症サポーターの話がありましたが、１点は認知症サポーターについてお伺いしたいんです。今まで１回受けた方、何か緩やかな形で集団として何をかを行うというような、そういったお考えというのはないのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"もう１３地区全部やっておりますけれども、自治会とか、そういうところもどんどんこの講座を受ける必要があると考えております。まちばで、認知症サポーター養成事業はいかがですかという形で、こちらでそういうものをお勧めしながら広げているところです。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問・要望","question":"平成２４年度までに、サポーターの方が６,２９５人いらっしゃるということで、ぜひこういったところの活用も図ってほしいと求めました。平成２５年度から推進をしていくと、品川区としてどのように研究をされているのか、説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"区でもいろいろ検討している中で、一つの方法ではないかということで、議論にはなっております。場所の問題もありますし、サポーターの支援の仕方などもいろいろ難しいところがあるので、何か参考にできないかとは考えているところです。","id":"exchange-021"},{"speaker":"あくつ委員","kind":"意見","question":"いろいろ調べていると、海外でも先進国のオランダとか、イギリス等でもいろいろな効果があると。うまく自分の感情等を表現できるというところで、私自身もちょっと研究してみたいと思いますけれども、ぜひ研究を進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"井上委員","kind":"質問","question":"今、ＧＰＳの件で、ちょっと関連してお伺いしたいんですけれども、先ほど、平成２５年８月末、品川区では要介護認定者のうち６,０００人だというふうに示してありますけれども、この中で、介護認定の中で、徘徊が非常に困ったことになっているという方たちは何人ぐらいいらっしゃるんか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"現実に、徘徊の方のカウントというのは非常に難しくなっておりまして、何人というところまではつかみ切れていないところです。その辺の基準のつけ方が難しいということで、区のほうで把握しているのが、日常生活自立度という公式のものでの把握となっております。","id":"exchange-023"},{"speaker":"井上委員","kind":"質問","question":"なぜ１１人かと言えば、やはり１回探しに行ったときの１万円余の金額というのは、すごく大きい負担になると思うんですよ。１１人でしたということで、１万円余かかる探しにいった件数というのは、どのくらい把握をしているのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"ですので、いつもこういう経路でくるよと、そういうような認識の中で探したりということで解決しているケースもたくさんあると思うんです。こういう内容のことを、介護者教室とか、認知症のいろいろな講座の中で啓発をしていく必要があると考えているところです。","id":"exchange-024"},{"speaker":"井上委員","kind":"質問・要望","question":"２４時間監視をしていることにすごく疲れている介護者がいるわけですから、相手先の方もいらっしゃる中で夜中にそこを探すんですかということです。初期投資の７,３５０円というのは区が負担をされているのか、対象者が限定されているのかどうかを、説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"対象者は、区内に在住の６５歳以上の方ということで、介護認定を受けている受けていないは関係はございません。","id":"exchange-025"},{"speaker":"井上委員","kind":"質問","question":"なかなか介護保険とかいうと、ちょっと相談にいきにくかったり、家族がどうしていいかわからないという状況にあると思うんです。その辺の対策としては、どういう支援体制があるんか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"６０歳未満の方になるかと思うんですけれども、なかなか直接在宅介護支援センターに行くというような形はとりづらいということで、つなげたりというような形になるのではないかと考えています。","id":"exchange-026"},{"speaker":"井上委員","kind":"意見","question":"先ほど、研究をしていくということだったので、そういったところにもぜひ。なぜ来ないのというのがすごくジレンマだと思うんですけれども、ぜひ研究をしていって、実践をしていただけたらと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"たけうち委員","kind":"質問・要望","question":"ご家族に確認することができるんでしょうけれども、適切につないでくれるところまでやってくれるとしたら、それはどこが所管なのかということ。そういうふうな高い料金設定にならざるを得ないのか、ちょっとそこは素人的なことで申しわけなんですけれども、３点説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"これはこのままこの後も継続していきますので、認知症早期発見・早期診断推進事業は、一つまた選択肢が増えたというようなことになっております。","id":"exchange-028"},{"speaker":"たけうち委員","kind":"質問","question":"誰にどうしたらいいのか、場合によっては保健センターのほうで、ちょっと様子を見てもらったりすることができると思っておけばいいんでしょうか。利用料が安くなるということは非常に難しいことなのかなと受けとめるしかないのか、一応、説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"今回出された６,０００人よりも、同じ基準にすれば、それに対応するいろいろな事業というのは考えていく必要があると認識しています。日常生活費ということで、おむつとか、その他生活していくための雑費的なものも含んでの金額です。","id":"exchange-029"},{"speaker":"渡部委員","kind":"質問・要望","question":"キャラバンメイトが品川区に多い理由というのですか、ちょっとその辺の理由を教えていただきたい。１時間半の研修で取れるというのがあるんですけれども、一度、お伺いしてよろしいか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"キャラバンメイトが多いというのは、品川福祉カレッジを品川区の場合ずっと続けてやってきておりまして、その中で推進してきたというような経緯があります。","id":"exchange-030"},{"speaker":"渡部委員","kind":"質問・要望","question":"そういう方々が大勢いるわけですから、町会とかにも出前講座に行ってというように、ぜひ積極的にやってほしいと求めました。そういうところにしっかり力を入れていくのが一番かなと、ある意味で思うんですが、その辺はいかがか尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"介護予防ですとか、認知症予防事業、さまざまな認知症になる前の事業ということで、高齢者いきがい課のほうでは、実施をしています。","id":"exchange-031"},{"speaker":"渡部委員","kind":"質問","question":"あそこのおばあちゃん、相談に乗ってくれないかというような感じで、民生委員を経由してというケースが多々あると思うんです。もしくはヘルパーが気づいて、ヘルパーから上がってくるというケースもあろうかと思うんですが、どれくらいの割合か尋ねました。","respondent":"永尾高齢者福祉課長","answer":"直接在宅介護支援センターに相談に行って、どう対応していいかわからないという方は、埋もれてしまうのかなと思います。はヘルパーが面倒を見ているときに、そういう疑いがあるのではないかというような話を持ってくるというケースのほうが多いかなと思います。","id":"exchange-032"},{"speaker":"渡部委員","kind":"質問","question":"ですから僕は、１回１回相談するのではなくて、やっぱりどこかで限界が来る。その班単位で見たら、少し気にしてあげてくださいというような仕組みづくりができればなと思うんですが、いかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"地域の中で当たり前のように見守れるような環境をつくるということが大事で、それを目的としたのが認知症サポーター養成事業になっております。何か活躍できるようなものがあったらということを、今、検討しています。","id":"exchange-033"},{"speaker":"渡部委員","kind":"提案","question":"果たして何ができるんだろうかというのが、すぐに見つかるものでもないし、行政の方々は一生懸命考えていただいていると思います。これからしっかり自民党の中でも考えて、いろいろ提案できるような形に勉強していきたいと思いますので、そのときはとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"認知症対策として、見守り等々のことはありますけれども、施設を増やしていくという考えはあるのか、どうなのかということ。昨日もお話があったかもしれないんですけれども、荏原病院の専門医という方は、どれくらいいらっしゃるんか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"以前にご説明したとおり、大井六丁目のほうで予定しているのものと、１カ所出てきているというところです。医師については、そういう内容になっております。","id":"exchange-035"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"個々の相談だったものを、地域だったり、在宅介護支援センターだったり、そういったところから来る相談を、アウトリーチチームで訪問するということだったと思うんですけれども、情報というか、要は、在宅介護支援センターだったりが把握できる範囲というのは、どれくらいと考えているんか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"は、ご家族の方が直接在宅介護支援センターのほうにご相談に来るという情報、在宅介護支援センターを非常に頼りにしているところでありますので。先日も、医師会のほうと、その辺の話をしてきたところです。","id":"exchange-036"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"あの人ちょっとどうしたかしらというときには、みんな高齢だし、その人だけを孤立させないようにしていたりという話を聞いたりするんです。孤立させない事業なんかもありますけれども、そういった原因というのを、区としてはどう考えていらっしゃるのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"家族で言えば、その状態を受容できない、受け入れることができないという気持ち、そういうものが心の中にあるのではないかと思います。そうすると、周りからは理解できなくて、この人は何かおかしいのではないかというような判断になってしまうんだと思うんです。","id":"exchange-037"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"認知症になっても安心して暮らし続けられるまちづくりというところでも、ほんとうに地域のつながりとか絆が大事だと思うんです。区として認知症高齢者と言われる方々を、こういった事業も始めていく目的を、大きなところでどう考えているのかをお聞かせ願いたいと思いますとの意見を述べました。","respondent":"永尾高齢者福祉課長","answer":"そして受容した後、区のほうで指導していってあげるとともに、やっぱり休息するような事業も考えていかなければいけないと考えています。そのほか民生委員、地域の方々も合わせた中で、どう進めていくかということを考えていきたいと考えています。","id":"exchange-038"},{"speaker":"井上委員","kind":"質問","question":"先ほど、こころの健康相談に相談をすればいいということがわかって、私もよかったと思ったんですが、ここに相談した後、それは家族ではないので、支援として、その方に具体的にどういうふうに進んでいくのか、ちょっと説明を求めました。","respondent":"大石品川区保健所荏原保健センター所長","answer":"いきなり来られて受けられるというものではありませんので、具体的には、保健師を通して予約を入れるという形になると思います。どういった診断がつくのかといったことによっても対応が変わってきますし、また、そういった経過をたどっていくという形になるかと思います。","id":"exchange-039"},{"speaker":"井上委員","kind":"質問","question":"あの人が心配だと思ったときに、どこへ相談したらいいですかっていうときに、こころの健康相談に行くのかという会話の流れかなと思ったんですよね。あの方は多分心配だからといったときに、改めまして、そういうときはどこに相談に行けばいいのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"そういう相談を受けた場合には、まずは在宅介護支援センターに行くのが一番的確ではないかと思います。そういうときに、保健所の保健師さんにご相談したからどうかというところで、こころの健康相談につなげるという形になるかと思います。","id":"exchange-040"},{"speaker":"井上委員","kind":"質問","question":"そういうインフォメーションがあったらいいのではないかと思うんですけれども、品川区の地域包括支援センターは、そういう役割ではないのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"地域の在宅介護支援センターもあれば、区の地域包括支援センターということもあるし、また。この場合は、民生委員が区の地域包括支援センターのほうにご連絡していただいたり、在宅介護支援センターに連絡をいただいたりということで。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問","question":"その方に対応してもらわなければいけないわけですから、そこの部分のシステムができているかどうかというところが明確にあればいいなと。やるところは決まっていたほうが、システム的には機能すると思うんですけれども、いかがか尋ねました。","respondent":"早津健康福祉事業部長","answer":"そうなると、既に基本的なところの対応ができておりますので、まちばの方でこういうことをご心配されているということを追加情報として行くわけです。","id":"exchange-042"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（ち）副委員長","kind":"質問","question":"これは、後ほどにでも、一覧としていただくということはできますか。もしくは、詳しく１事業ずつ教えていただくことは可能か尋ねました。","respondent":"竹田生活福祉課長","answer":"現在、調査中のものですが、後ほど文書でお渡しすることは可能だと思います。","id":"exchange-043"},{"speaker":"たけうち委員","kind":"質問・要望","question":"地域総合支援センターという言い方なんですか、動きがあるのかどうか、もしわかれば教えてもらいたいと思います。は要望ですけれども、そこで食事ができればいいなと、要望です。","respondent":"早津健康福祉事業部長","answer":"地域総合支援センターと名前はありますけれども、就労関係に特化された中での総合センターということだと思います。名前は初めてです。","id":"exchange-044"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"北九州市って、乳児健診が非常に充実しているところで、北九州市の母子手帳ってものすごく詳しいんですよ、品川区の倍くらいあるんです。それに派生して要望なんですが、乳児健診のシステムとか、そちらにも少し触れていただければと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"井上委員","kind":"質問","question":"うちの健康づくりも、随分前になってしまっているんですけれども、品川区との違いみたいなものが感じられますか。どうですか、つくり方について、何か特色があるみたいなところはあるのか尋ねました。","respondent":"矢野品川区保健所長","answer":"今回の計画は、健康日本２１というものに基づいているということが、ちょっと新しいのかなというところで、世代ごとのこころの健康づくりなんていうのが入っているところとか、あとは社会基盤の整備というところで、企業と連携したという部分は、ちょっと特徴的かなと思います。","id":"exchange-046"},{"speaker":"井上委員","kind":"意見","question":"健康づくりのプランをつくるとか、こういうのを参考にして、私たちで聞いていくときに、常に品川区とリンクしていくんですけれども、そんなところの計画みたいなものは、この先、どういうふうにイメージしていったらいいかなと思うのですがとの意見を述べました。","respondent":"早津健康福祉事業部長","answer":"今は長期計画で策定しておりますので、長期計画策定後の課題の一つだと考えています。","id":"exchange-047"},{"speaker":"井上委員","kind":"意見","question":"ここをイメージして、この話を聞けばいいのかというところで、げんき品川もあるんですよね。ここは一体化して、ちょっと品川区と置き換えたら、どういうふうに視察をしていったらいいかという心構え的なものなんですけれどもとの意見を述べました。","respondent":"早津健康福祉事業部長","answer":"この資料からではなかなか難しいんですが、多分ここは就労に特化した総合支援センター。大学校のようなものも持っているというのが、就労の中でも総合的というのが売りになるのではないかと思うんです。","id":"exchange-048"},{"speaker":"井上委員","kind":"意見","question":"宿泊施設込みの２年というのは、どういう経費か、仕組みがちょっとわからない。場所的に、品川区で考えると、そういう場所が確保できのかとか、仕組みをとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"渡部委員","kind":"意見","question":"だから、あえて行政がそこにまで首を突っ込んだというのは、何か斬新的だなという感じがしないではないんです。ただ、何を連携しようしているのかというのが、ちょっとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"どれくらいの受診対象があって、どのくらいの数字が出ているのかというのが、ちょっと聞きたいと思いました。今、品川区では求められている中で、そういったスムーズが流れがつくれていけているのかなというのが気になるところでした。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"たけうち委員","kind":"意見","question":"４年くらい経過していますので、もう既に４年くらいたっているので、そんな話をお願いしたいと思いますとの意見を述べました。","respondent":"早津健康福祉事業部長","answer":"品川区は、認知症疾患医療センター自体は、もう昨年からあります。そこと連携した新しい事業が早期発見・早期診断事業ということです。","id":"exchange-052"},{"speaker":"鈴木（博）委員","kind":"質問","question":"認知症相談医というのが、普通の開業医療機関と九州大学病院のちょうど中間に位置するような感じで位置づけられているんですけれども、これはどういう資格で、どういう形で養成されるのかということをお聞きしたい、質問ですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/626613?Template=document&Id=3368#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":46567,"voices":141}},{"id":"h25-20130925-8","meetingId":"h25-cm09","date":"2013年9月25日","dateIso":"2013-09-25","committee":"建設委員会","time":"午前１０時００分～午後 ２時２３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を58件整理しています。","topics":[{"id":"topic-01","title":"の１、「報告事項」を行います。 初めに、(1)「平成２４年度指定管理者による管理に対するモニタリング・評価について」","agenda":"の１、「報告事項」を行います。 初めに、(1)「平成２４年度指定管理者による管理に対するモニタリング・評価について」","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"区民住宅と区営住宅の戸数を聞き漏らしたかもしれないので教えていただきたいのと、滞納の件数、どういう対応をしているのか改めてお伺いしたいです。裏面の３のサービス向上及び業務改善の視点というところで、意見・要望を傾聴し、この辺の居住者の意見・要望を受けとめる仕組みを説明を求めました。","respondent":"大串住宅担当課長","answer":"昨日の審議、あるいはご報告の中でもご説明させていただきましたが、なるべく滞納額が膨らまないうちにということで対応しているところです。対応の人数、あなたは今こういう状況ですよ、なるべく早目の納付をお願いしますということで納付指導を行っているということです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"工夫していただきたいと思うのと、区営住宅のほうでも簡単にできることであると思うので、ぜひ実施していただきたいなと思いました。その辺でやはり困難ケース、福祉に一刻も早くつなげたほうがいいというケースのところの区との関係はどうなっているのかお聞きします。","respondent":"大串住宅担当課長","answer":"滞納者への対応です。区の他のセクション、その中でそういう相談をもらったということであれば、こちらのほうが窓口になってご紹介するということもやっているところです。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特に福祉関係のところは本当に敏感であっていただきたいなと思うのが、いろいろあると思うんですけれども、その辺はどうなんか尋ねました。","respondent":"大串住宅担当課長","answer":"ご親族の方に、今、逆に東急のほうは２４時間体制の防災センターが設置されております。ですので、マニュアルもあわせてつくって、そういった不測の事態には対応するようにしているといったところです。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"見守り対応マニュアルがあるということで、一定安心するところなんですけれども、こういった事例に関しては、区のほうに報告があるんでしょうか。情報というのはあるのかなというところも説明を求めました。","respondent":"大串住宅担当課長","answer":"そのときにこちらのほうから指示をすることがあれば、当然指示をしますし、あるいは継続して状況を確認してくれという指示をもって。今年の夏は暑かったので、そういったことはさせていただきましたけれども、特に今年度何かということはございませんでした。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"１カ所の職員の配置と場長がどう配置されているのか聞きたいところが一つと、トラブルというのはどういうトラブルが多いのかという点と、あと定期的利用者アンケートというのはどういうものか説明を求めました。","respondent":"谷口交通安全担当課長","answer":"場長は１１名おりまして、固定配置が５カ所あるんですけれども、あとは時間を見ながら各配置のところを回ったりしてやっている状況です。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"ここを聞きたいのと、あと、職員の方たちの労働環境の改善についてのテーマはないのか。冬は寒く夏は暑くてなかなか体を休めるところがないような発言をされていたので、そういう労働環境の改善について何かあったら説明を求めました。","respondent":"谷口交通安全担当課長","answer":"寒いがあるところですけれども、それは指定管理者のＮＣＤと協議しながら、環境改善については定期的に努めているところです。機器が老朽化してまいりますので、それを各配置員に対して指導しながら、効率的に使えるように努めております。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問","question":"端的にお伺いします。こういう区営住宅、非常に町会が安定していくと思うんですが、そのことのお考えを説明を求めました。","respondent":"大串住宅担当課長","answer":"こちらのほうが近隣の都営住宅を含めまして、西五反田谷山町会という町会を結成して、町会の加盟をしているという情報は得ております。","id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問・要望","question":"あくまで区営の駐輪場ですから、そういうお考えはないでしょうかというのが１点と、確かに効率化はいいんです。両面の話になるのかもしれないけれども、それをうまくやってほしいと思うんですが、いかがか尋ねました。","respondent":"谷口交通安全担当課長","answer":"それは改善に向けて日々区とＮＣＤとで協議しながら進めているところです。勤務環境につきましても、またＮＣＤと協議を進めまして、少しずつ改善を図っていきたいと考えております。","id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問・要望","question":"恐らくもう既に例えば立会川駅の駐輪場はちゃんと冷暖房完備されていると思うんだけれども、そうでないところもあるはずですよ。それはもうご存じでしょうから、その中で優先的に考えていくとか、そういうお考えをもう少しお聞かせいただきたいと思うんですが、いかがか尋ねました。","respondent":"谷口交通安全担当課長","answer":"ＮＣＤとは委託契約しておりまして、勤務環境だとかはＮＣＤのほうでやっている関係がありますので、それはまたそういう状況があるということで、ＮＣＤに申し入れをしながら、今、いつかということはできませんけれども、協議はやっていきたいと思います。","id":"exchange-009"},{"speaker":"伊藤委員","kind":"質問・要望","question":"効率化はもちろん議会として求めていくんですけれども、だからといって、苦情が出たらいけない話になるので、難しい話なんですよね。効率化してくださいというのとサービスを低下させないというのは難しいところなんだけれども、でも、取り組んでください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"端的にお願いします。２８号という記載の中で、この滞納者１件当たりの対応回数を見てみると、そこのところはどうか尋ねました。","respondent":"大串住宅担当課長","answer":"できれば滞納されている方全員に基本的に同じような形で対応できれば一番よろしいんですけれども。そうなってしまうと、１人当たりの対応件数としては数が減ってきてしまう。","id":"exchange-011"},{"speaker":"大沢委員","kind":"質問・要望","question":"ただ、逆にそのケースでない方を放っておくことによって、第２、第３のそういう方も生まれかねない。今、課題ということでおっしゃいましたので、課題を解決すべく、この取り組みを行ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"どういうことが大事なのかという、経験が非常に有効であれば提供できるのかなというところで、何か方向性があったら教えてください。裏面を見ると、どういうメリットを生かして削減、縮減を図ったのかというところを教えてほしいと求めました。","respondent":"大串住宅担当課長","answer":"これから２０年の満了ということでオーナーのほうに返還する住宅が出てまいりますけれども、各オーナーとも対応していきたいと考えております。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"スケールメリットが出せるところは縮小という形ができているということで、かなりいい結果かなと考えています。要望ですけれども、入居されている方に迷惑がかからない形で、そのときに時間をかけて十分に対応してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]},{"id":"topic-02","title":"リニア中央新幹線の環境影響評価（準備書）について","agenda":"リニア中央新幹線の環境影響評価（準備書）について","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"どういうところでこういうことが導入されるのか検討されているのかというのがまず一つ前段でお伺いしたいところと、１個あったのと、品川区内で場所とか項目的に特に問題を感じるところがないのかどうか教えてほしいと求めました。","respondent":"野呂瀬環境課長、藤田都市計画課長","answer":"２点ご質問ですけれども、最初の質問は導入に当たっての区の評価は難しいところですよね。ほとんどが４０メートルの地下を通っていくわけですので、特段区のほうに環境悪化が講じるようなことになるという形は認識しておりません。あらましの冊子の表紙をおめくりいただきまして、１ページの「はじめに」というところに経緯等が記載されてあります。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"事業者が行うので、いろいろ問題を起こさないようにしっかりやれよといった意見とか要望を出しているという受けとめ方でいいんでしょうか。区がこれにどうかかわっていくのかという意見がいろいろ出ると思うので、品川区はどう受けとめていくのかというあたりも説明を求めました。","respondent":"野呂瀬環境課長","answer":"あくまでも関連する自治体の中において住民説明会をするということになっていますので、今回、その前段の２年前には方法書というものが出されました。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"意見もしっかり受けとめていただきたい。しっかりと受けとめて、区でかかわる部分もちゃんと意見を言っていっていただきたいなと思いますが、いかがか尋ねました。","respondent":"野呂瀬環境課長","answer":"先ほどのご質問では、住民説明会のときの区のかかわり方ということですので、区のほうは周知依頼によって協力していく。送付された後、それは工事期間中も含めて環境影響評価の効果を遵守しながらやっていくようにという区の意見は申し伝えるつもりです。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問","question":"これは部長にお伺いするんですが、どういうところで検討がされて、さまざま出てくると思うんです。まちづくりでももちろんそうですけれども、どのような場面で議論がされるのか説明を求めました。","respondent":"片田都市環境事業部長","answer":"今回、オリンピックの話もありまして、大きな問題については庁内の中でも検討会を立ち上げてという流れで、今、進めてきているという状況があります。","id":"exchange-018"}]},{"id":"topic-03","title":"しながわ中央公園拡張整備計画（ＪＴ跡地）説明会の開催について","agenda":"しながわ中央公園拡張整備計画（ＪＴ跡地）説明会の開催について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"１個だけちょっとよくわからないところが。近隣公園という意味と位置づけ、どういう公園なのか説明を求めました。","respondent":"多並公園課長","answer":"その次には地区公園というものがありまして、もう少し限られた、約５００ｍぐらいの範囲なんですけれども、そこの範囲を誘致距離とする地区公園。そういう位置づけの中で、都市計画上の各公園の分担の機能の中で分かれている呼び方の中の話です。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問","question":"一体化して評価するのかなと思っていたんですが、今までのところは総合公園で、そのほかに近隣公園がくっつくという位置づけなんですか。ちょっとそこのところがよくわからないので説明を求めました。","respondent":"藤田都市計画課長","answer":"その１個上が近隣公園ということで、もう少し広い幅でいろいろ来ていただくための公園です。面積的な要件とか、広い範囲の方々にご利用いただいても構わない公園だという、都市計画上の位置づけとしてはそういう形になってあります。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"一体という考えではなくて別々という位置づけなのかが一つと、あとすいません、この説明会の周知の範囲と周知の方法を説明を求めました。","respondent":"多並公園課長","answer":"都市計画の今回の考え方ですが、追加ということで、一体的にしながわ中央公園を変更し、区域を拡張するという考え方なので、プラスする形です。もう一つの説明会の周知ですが、あと町会の回覧板等で周知いただくことと、周知する形で丁寧な対応をさせていただこうと思っています。","id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"それと、一貫校になったことで校庭をもうちょっと確保してほしいんだという意見があって、ここを使えないだろうかというのが出ていたと思うんです。豊葉の杜学園のＰＴＡの方々にもご案内したほうがよろしいのではないかと思ったんですが、いかがか尋ねました。","respondent":"多並公園課長、松代防災まちづくり事業部長","answer":"そこら辺の整備の内容も検討した中で、やはり球技を利用できるような形にするためには、周りに防球ネットという高いフェンスを立てなきゃいけません。ただ、今後、説明会でもそういうことで考えていきます。都市公園法に基づく公園としての位置づけで進めてまいりますけれども、この整備内容の主たる目的は防災１点でまず整備を考えてあります。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"最後に、今、災害時用のヘリポートというのがありますね。これがもう既に自衛隊のほうとは全てある程度の交渉が進んでいる中での計画という認識でよろしいか尋ねました。","respondent":"多並公園課長","answer":"ただ、その中を確認すると、ここでできるだろうということで確認しております。今、基本設計の段階ですので、詳細設計をもう少し詰めていきたいと考えております。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺の可能性というか、さっき部長が力強くおっしゃったのでだめなのかなと思いつつも伺いたいと思います。いかがか尋ねました。","respondent":"松代防災まちづくり事業部長","answer":"はトイレ等を含めまして、ほかの施設等でも配慮しているのと同等以上に、ここではきちんとした配慮をしていきたいと考えています。したがいまして、一定の遊具、それ以外の施設についてはほかのところでしっかりと対応して考えていきたいと思っているところです。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区民の貴重な財産になる、また防災をというところでは防災の役割を十分果たすという意味でも、いろいろな方のご意見が必要かと思います。近隣だけでなく、できたらもうちょっと広くご周知していただきたいなと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"伊藤委員","kind":"質問・要望","question":"確認なんですけれども、災害時ですから、それ以外でさまざまな区民の用途にもなるわけですよね。それから使えないときがあったとしても、それがヘリポートから区役所にさまざまな物資がスムーズに対応できると思ったんですが、いかがか尋ねました。","respondent":"松代防災まちづくり事業部長","answer":"２６号線が整備された後には、今は東京都管理ですけれども、品川区の管理になってまいります。少しその整備には時間がかかると考えていますが、必要性というものを計画の中で続けていきたいと、このように考えているものです。","id":"exchange-026"},{"speaker":"伊藤委員","kind":"質問・要望","question":"要望で終わりますけれども、ですから、こちらの要望としてぜひ内部で検討してください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"こんの副委員長","kind":"質問","question":"防災拠点ということで整備が進んでいるということを伺いまして、一つには災害時の炊き出しというのは、ここではやるというお考えはありますかというのをまず聞きたいと思います。","respondent":"多並公園課長","answer":"それがもう少し先になると、今度は仮設住宅というのも一つの考え方になろうかと思っています。そういうところでいいますと、ここの場所の考え方としましては、現在のところはそこまでできるというのは考えているところではございません。","id":"exchange-028"},{"speaker":"こんの副委員長","kind":"質問","question":"なぜそういう話をお聞きしたかというと、椅子、ここの絵にはないので考えていらっしゃるかどうか。あるいは、ここに絵がないだけで、それはもうお考えなのか、その辺をお聞きします。","respondent":"多並公園課長","answer":"これはまだ本当に基本計画というか、設計の本当のまだまとまりの段階ですので、今後もう少し詳細になっていくときに、もちろんご意見を踏まえながら、防災機能ということを考えながらいろいろ検討してまいりたいと考えています。","id":"exchange-029"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"ぜひご検討ほしいと求めました。多分説明会の中でもそういったご要望とかももしかしたら出てくるかもしれないですし、これは要望でお願いしたいと思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-04","title":"品川区公園施設長寿命化計画策定について","agenda":"品川区公園施設長寿命化計画策定について","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"委託なんですか。やっぱり防災のことを考えちゃうと、地域の皆さんの声が災害時でも使えるトイレにしてほしいというところがあるんですが、その辺を説明を求めました。","respondent":"多並公園課長","answer":"もう一個、トイレの考え方ですが、今回の公園施設長寿命化の考え方の中に、トイレというのは建物に当たります。フェンスだとか、そのような公園施設についての長寿命化を一個一個立てたものであり、そういうものはこの中に入ってございません。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問・要望","question":"委託はどういうところに委託されるのか、予算書を見てこなかったので、予算をちょっと教えていただきたいのと、今回、トイレは建物なので入っていないということなので、ぜひこういった声を伝えてほしいと求めました。","respondent":"多並公園課長","answer":"この調査に当たりまして、まず平成２３年度に調査を行いました。契約としては６７０万の費用で調査を行って、今回この資料とするものです。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"どういう現状があったからこういうことが起きてきたのかなということなんですけれども、そういう意味からすると、位置づけです。どういう考え方で始めようとしたのかなというところを詳しく説明を求めました。","respondent":"多並公園課長、松代防災まちづくり事業部長","answer":"その中で長寿命化計画を立てると、先ほど答弁させていただいた調査についても国費がつくということで、平成２５年度までの実施の中でということです。国も推し進めているものであり、今回… バリアフリーの対応をしっかりとしていくという計画も一方でやっておりますし、身障者対応として誰でも使えるようなトイレに変えていくとか、今。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問・要望","question":"ちょっと不思議だったんです。これが出てきたということは、それを確保しながら、今後もすてきな公園をたくさんつくっていただきたいなと思って要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"木村委員","kind":"質問","question":"結構予防型保全型のほうになるものも多いと思うんですけれども、これはどういうふうにして分けたのかわからないのですが、もし簡単に説明できるようだったら説明を求めました。","respondent":"多並公園課長","answer":"いわゆる腐食するのを防止していって、放っておいたら１０年ぐらいで壊れちゃうものを１５年とか２０年とか、手をかけながらやっていく。そういう考え方で国のほうでもいろいろな検討をした結果示されているもので、このような形で今回の計画を立てさせていただいているものです。","id":"exchange-035"},{"speaker":"大沢委員","kind":"質問","question":"要は国交省か厚労省かという、児童福祉法とこれは違ってくるじゃないですか。そこはどういうふうになっているんか尋ねました。","respondent":"多並公園課長","answer":"国から示されている今回の国交省のものは、都市公園法に基づく公園のみが対象となっております。国が予算の中でいろいろ検討していますが、今回、このようなものを立てさせていただいたものです。","id":"exchange-036"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"１点、今年の夏、去年もそういう報道があったかと思うんですが、滑り台、特に夏はものすごく熱くなって、やけどをしたお子さんがいる。この計画の中というよりは事後保全型のほうにかかわってくることなのか、この滑り台の考え方をどう考えていますか尋ねました。","respondent":"多並公園課長","answer":"今の滑り台だけではなく、いろいろな施設については、直射日光が当たって熱くなるという問題はいろいろなものがあります。更新もしくは工事をやるときに、その時点の新たな一番どういうものがいいかというのも含めながら検討していくようなものだと考えています。","id":"exchange-037"},{"speaker":"こんの副委員長","kind":"質問","question":"その更新時期、あるいはその間のメンテナンスが必要だというのは確かにそうなんですが、そういった事故につながるようなものに関しては、いわゆるそれを待たずして改善していくという考え方は持っていかれたほうがいいかなと思うんですけれども、いかがか尋ねました。","respondent":"多並公園課長","answer":"もちろんさまざまなご意見をいただきながら、改善できる経費があれば、もちろんそこは改善していくところです。ただ、それはちょっとその状況を見ながら確認させていただいて、改善できる点があればもちろん改善を今後もしていきたいと思っています。","id":"exchange-038"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"それは一気にというわけにはいかないんでしょうけれども、ぜひそういうお考えをお持ちの上で、いろいろなところで対処してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"先ほどの質問で、児童遊園は対象外ということで、児童遊園はやらないんか尋ねました。","respondent":"多並公園課長","answer":"先ほどのものは国費の対象とならないということであり、品川区としては計画を立てさせていただきましたので、このとおりやらせていただきます。","id":"exchange-040"}]},{"id":"topic-05","title":"しながわ水族館経営改善検討委員会中間報告について","agenda":"しながわ水族館経営改善検討委員会中間報告について","exchanges":[{"speaker":"伊藤委員","kind":"提案","question":"議事進行でお願いしたいんですけれども、昨日の委員会に比べたら非常に順調に進んでいますので、できればここで一旦休憩していただいて、このしながわ水族館のことについては午後に質問したらどうですかという提案をしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"伊藤委員","kind":"提案","question":"この水族館をこれから最大限活用するところであることは確認できたんですが、私たちで考えた提案を幾つかお話をさせていただきたいんですけれども。確認したいのは、サンシャインとの相互乗り入れはどうか尋ねました。","respondent":"多並公園課長","answer":"サンシャインのもともとの考え方自体ももう一度確認するところなんですが、いろいろな形ではできるかと考えています。割引の考え方とか、今後、サンシャインと協議していきたいと考えています。","id":"exchange-042"},{"speaker":"伊藤委員","kind":"提案","question":"幹事会もあるでしょうから、例えば年間これぐらいの人数だったらこれぐらい割り引いて入ってもらえますよとか、これはこれでいいんですよ。だけれども、外に向かっていかないと、私たちとしてはちょっと厳しいものがある気がしますので、改めてお考えを説明を求めました。","respondent":"多並公園課長","answer":"大田区との連携というお話があって、今、そっちのほうでやっていたところなんです。方法等、まずは隣の大田区からとか、そこら辺は今後考えていきたいとは思います。","id":"exchange-043"},{"speaker":"伊藤委員","kind":"質問","question":"まとめますけれども、つまり使用許可でやってもらっている施設ですから、品川区がかかわっている部分もあるんでしょう。サンシャインというのは民間業者ですから、これだけだと品川区の中だけだし、もちろんこれもやってほしいんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"あまり伺ったことがないので、本当にさまざまな努力をされているんだなというのを受けとめて、努力しなくちゃいけないなとまず一つ思いました。わかりやすい展示の仕方、見やすい展示というのはものすごく大事であるなと思っているんですが、当初のところを教えていただけたらと思います。","respondent":"多並公園課長","answer":"区民の方から品川区が水辺に面する区として区民と触れ合える機会ということで、そのような親しめる施設ということで水族館をスタートしています。そのとき公園の中に設置するということで、都市公園法に基づく管理許可のもとに、そのような形の位置づけで運営しているものです。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、また２６号線とか、評判が少しずつ上がっているところはやっぱりそういった展示の方法を工夫しているところが多いと見ていたんです。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問","question":"その分析はどうされているのかというのが一つと、８割、９割が入場料。要は赤字でもやっていくというお考えがあるのかどうかをまずお聞きしたいと思います。","respondent":"多並公園課長","answer":"大体６から８％ぐらいのプラスだったという動向を見ると、なかなかしながわ水族館だけでどこまでこれが上がったのかというのは難しいところです。","id":"exchange-047"},{"speaker":"西本委員","kind":"提案","question":"提案ですけれども、ここに児童センターの赤ちゃんクラブとか、かなりお母さんたちがいっぱい来るんですよね。先ほどのはどういうお考えか尋ねました。","respondent":"多並公園課長","answer":"今年度に至っては経営改善検討委員会を開き、先ほどいろいろなお話をさせていただきましたが、そういう取り組みを今年度やっているところです。","id":"exchange-048"},{"speaker":"西本委員","kind":"提案","question":"いろいろな提案内容があるんですが、今まではやっていなかったというんだけれども、これらの提案内容をすることによってどれだけ活性化されるもの。例えば今まで５０だったものが、これをすることで８０、１００のレベルで活性化が上がるだろうという感覚はいかがか尋ねました。","respondent":"多並公園課長","answer":"そういうような取り組みをいろいろな形でできないかということで、今回、今後の進め方を考えようということです。そういう考えで、できる限りトータルのほうもやっていきたいという考えです。","id":"exchange-049"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、立会川が一番近いんですよね。そこの商店を宣伝するとか、そういうコラボレーションを考えられていたら、ご意見をいただきたいです。","respondent":"多並公園課長","answer":"このアイデアの中で踏み切ったのは、ゆるキャラとなっていますけれども、実質は確認できただけでも商店街に１５もキャラクターがあると。水族館の帰りに寄れるとか、そんな形もできないかなというのもここのアイデアの中の一つで、活性化の材料に使っていこうです。","id":"exchange-050"},{"speaker":"伊藤委員","kind":"質問","question":"地元の開催する品川区でもあるから、２０２０年にも多分水族館はあると思うので、そういう意味でお客さんを呼び込む。まして京浜急行だから羽田空港から１本で来れるから、検討してみてはいかがでしょうかということで、ご答弁ください。","respondent":"松代防災まちづくり事業部長","answer":"ご提案のあった水族館という施設を持っております品川区としても、そういったことが今後どう考えられるか、もちろん検討の一つだと考えています。","id":"exchange-051"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、ここの検討委員会の皆様はその部分の知見が広い方たちなんですけれども、なぜここについては複合施設化という文言が出てきていないのか。課題として取り上げないのか、それとも課題として取り上げられないのか、どちらなのか、そこのところを説明ほしいと求めました。","respondent":"多並公園課長","answer":"このいわゆるあり方の全体的な考え方につきましては、もともと平成２３年度にあり方検討委員会というものを行い、実施してきたところです。その状況を見ながら、またあり方については今後その状況に応じた形で、踏まえながら、また検討を再開していきたいと考えているところです。","id":"exchange-052"},{"speaker":"大沢委員","kind":"質問・要望","question":"やはり娯楽の施設という位置づけも考えると、集客というのはやはり人が集まらなければしようがないので、人を集めるにはどういうふうにすればいいか。確かに今までの人数をどうすれば改善できるかというのは、この中間報告とありますけれども、もう一回お考えをお聞かせほしいと求めました。","respondent":"松代防災まちづくり事業部長","answer":"今、委員からお話があったような複合的な部分も当然検討の一つにあるところだと思いますが、そういう形も今後の検討の一つかもしれませんけれども。その際には、今、委員からのお話にあったことも当然ながら入れて検討してまいりたいと考えているところです。","id":"exchange-053"}]},{"id":"topic-06","title":"「所管事務調査」「木密地域不燃化１０年プロジェクト」に関すること","agenda":"「所管事務調査」「木密地域不燃化１０年プロジェクト」に関すること","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"その辺の変化というのはあるんですか。何カ所が何時間後にどう広がったという数字が多分あったかと思うんですが、わかったら説明を求めました。","respondent":"品川木密整備担当課長","answer":"出火件数ですが、前回は４８件。今回の被害想定で４０件という形で、多少減少が見られるです。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問","question":"ガスで通電火災とか、そういうものの対策とかもとられているんですかね。よくわかりませんが、出火件数は減っているけれども、延焼して燃えてしまうのは倍に増えるという、この辺の見方は何なんか尋ねました。","respondent":"品川木密整備担当課長","answer":"今、その中では６弱までは昭和５６年以前の未耐震の住宅でもそれほど倒壊はないんですが、これが６強になると急激に倒壊する件数が増えます。倒壊する住宅が増えれば増えるほど燃えぐさが多くなって、火災の延焼が広がるというふうに見ております。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問","question":"焼失棟数の表はいろいろあるんですが、これは火元によってのずれとかは算定していないんですよね。どこで火が出たらとかという、それはどういう形になるんか尋ねました。","respondent":"品川木密整備担当課長、鈴木防災課長","answer":"４０カ所と出ているんですけれども、またいろいろ個人の問題とかもあるので、多分非公表になっているのではないかと思います。 火災の延焼のシミュレーションの仕方が従来と違いまして、クラスター方式といいまして、エリアで燃えやすさの度合いからケースを想定するんです。ですから、今、木密整備担当課長からお答えしたような答えになるということだと思います。","id":"exchange-056"}]},{"id":"topic-07","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"質問の中で、区内の消防車の台数をお伺いしたんですが、この内訳について正確に教えていただきたいんです。特に消防車という質問でお伺いしたんですが、可搬ポンプなどもあわせてのご報告だったので、可搬ポンプの考え方自体も教えてほしいと求めました。","respondent":"鈴木防災課長","answer":"震災時の火災への対応ですが、同時多発する火災については、一つの火災に対して１台のポンプで消火活動をするという考え方があります。先日の区長の答弁にありましたように、同時火災に対しては理論上区内で６０カ所まで対応ができることになるです。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問","question":"後段のほうですけれども、先ほどの出火件数が４０カ所ということにおいては現状においては初期の対応はできるという考えでよろしいんでしょうか。その辺も含めて検討されているのかどうか、そこも聞かせてください。","respondent":"鈴木防災課長","answer":"消防車のポンプ車と可搬ポンプについては、ほぼ能力は同じですので、同等の対応ができるというのが消防の考え方です。区外隣接の消防署や消防団も同様に地区を越えて支援し合うという全体の支援の体制を組んでいるというふうに聞いています。","id":"exchange-058"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/890615?Template=document&Id=4086#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":58623,"voices":166}}]);
